export type WebExportCancelableStatus = "queued" | "running" | "retry_wait";

export type WebExportCancelGate = {
  synced: boolean;
  busy: boolean;
  status: string;
};

export type WebExportCancelOutcome =
  | { kind: "retryable"; message: string }
  | { kind: "refresh_only"; message: string }
  | { kind: "unauthorized"; message: string };

export function isWebExportCancelableStatus(status: string): status is WebExportCancelableStatus {
  return status === "queued" || status === "running" || status === "retry_wait";
}

export function canStartWebExportCancel(gate: WebExportCancelGate): boolean {
  return gate.synced && !gate.busy && isWebExportCancelableStatus(gate.status);
}

export function webExportCancelOfflineMessage(): string {
  return "请先连接共享账号后再取消导出任务。";
}

export function webExportCancelBusyMessage(): string {
  return "正在取消导出，请稍候。";
}

export function webExportCancelConfirmMessage(fileName: string): string {
  const name = fileName.trim() || "该导出任务";
  return `确定取消「${name}」？取消后不可下载；列表会保留已取消记录。`;
}

export function webExportCancelSuccessMessage(): string {
  return "导出任务已取消，列表已刷新。";
}

export function interpretWebExportCancelFailure(error: unknown): WebExportCancelOutcome {
  const status = typeof error === "object" && error && "status" in error
    ? Number((error as { status?: unknown }).status)
    : NaN;
  const code = typeof error === "object" && error && "code" in error
    ? String((error as { code?: unknown }).code ?? "")
    : "";
  const message = error instanceof Error
    ? error.message
    : typeof error === "object" && error && "message" in error && typeof (error as { message?: unknown }).message === "string"
      ? (error as { message: string }).message
      : "取消导出失败";
  if (status === 401 || code === "UNAUTHORIZED" || code === "SESSION_REVOKED") {
    return { kind: "unauthorized", message: "共享会话已失效，请重新连接后再取消导出。" };
  }
  if (status === 409 || code === "EXPORT_ALREADY_FINISHED" || code === "EXPORT_NOT_CANCELABLE") {
    return {
      kind: "refresh_only",
      message: "该导出已结束，无法再取消。请刷新列表查看最新状态。",
    };
  }
  return {
    kind: "retryable",
    message: /网络|failed to fetch|timeout/i.test(message)
      ? "网络异常，导出尚未取消。列表未改动，可重试。"
      : `${message}。导出尚未取消，列表未改动，可重试。`,
  };
}

export function shouldRefreshExportsAfterCancelFailure(outcome: WebExportCancelOutcome): boolean {
  return outcome.kind === "refresh_only" || outcome.kind === "unauthorized";
}

export function shouldKeepExportListOnCancelFailure(outcome: WebExportCancelOutcome): boolean {
  return outcome.kind === "retryable";
}
