function applyQualityPreset(preset: QualityPreset): void {
  const next = qualityPresets[preset];
  const paletteId = preset === "economy" ? creationDefaults("quick").paletteId : next.paletteId;
  settings.preset = preset;
  settings.size = next.size;
  settings.maxColors = next.maxColors;
  settings.crisp = next.crisp;
  if (currentCloudProjectId.value
    && workspacePalette.value?.id !== paletteId
    && shared.state.palettes.some((palette) => palette.id === paletteId)) {
    void shared.changePalette(paletteId, next.maxColors)
      .then(() => applySharedState({ forceProject: true }))
      .catch((error) => notify(error instanceof Error ? error.message : "切换色卡失败"));
  } else {
    setWorkspacePalette(paletteId);
  }
}

