function colorDisplayName(name: string, code: string): string {
  const withoutBrand = name
    .replace(/^MARD\s+/i, "")
    .replace(/^Artkal(?:\s+M(?:\s+Mini)?)?\s+/i, "")
    .trim();
  return withoutBrand && withoutBrand !== code ? withoutBrand : `色号 ${code}`;
}

