function setWorkspacePalette(paletteId: string | null, paletteVersion?: number | null): void {
  workspacePaletteId.value = paletteId;
  workspacePaletteVersion.value = paletteVersion
    ?? shared.state.palettes.find((palette) => palette.id === paletteId)?.version
    ?? null;
  settings.palette = paletteName.value;
  if (!paletteMap.value.has(selectedCode.value)) selectedCode.value = beadPalette.value[0]?.code ?? "A01";
}

function restoreWorkspacePalette(saved: { paletteId?: string | null; paletteVersion?: number | null }): void {
  // Keep the requested id while the catalog is loading; once loaded it must
  // resolve to that exact palette rather than silently falling back to 221.
  const resolved = storedDraftPaletteId(saved, shared.state.palettes);
  setWorkspacePalette(resolved ?? saved.paletteId ?? null, saved.paletteVersion ?? null);
}

