}

function cloneGrid(value: PatternGrid): PatternGrid {
  return { width: value.width, height: value.height, cells: [...value.cells] };
}

function scheduleMaterialCount(): void {
  window.clearTimeout(materialTimer);
  materialTimer = window.setTimeout(() => {
    materialWorker?.terminate();
    materialWorker = undefined;
    const gridSnapshot = cloneGrid(grid.value);
    const paletteSnapshot = beadPalette.value.map((color) => ({ ...color }));
    if (gridSnapshot.cells.length < 10_000 || typeof Worker === "undefined") {
      materialRows.value = countMaterials(gridSnapshot, paletteSnapshot);
      return;
    }
    const worker = new Worker(new URL("./material-worker.ts", import.meta.url), { type: "module" });
    materialWorker = worker;
    worker.onmessage = (event: MessageEvent<Array<BeadColor & { quantity: number }>>) => {
      if (materialWorker !== worker) return;
      materialRows.value = event.data;
      worker.terminate();
      materialWorker = undefined;
    };
    worker.onerror = () => {
      if (materialWorker !== worker) return;
      materialRows.value = countMaterials(gridSnapshot, paletteSnapshot);
      worker.terminate();
      materialWorker = undefined;
    };
    worker.postMessage({ grid: gridSnapshot, palette: paletteSnapshot });
  }, 60);
}

function checkpoint(): void {
  history.value.push(cloneGrid(grid.value));
  if (history.value.length > 30) history.value.shift();
  future.value = [];
}

function undo(): void {
  const previous = history.value.pop();
  if (!previous) return;
  future.value.push(cloneGrid(grid.value));
  grid.value = previous;
  markDirty();
}

function redo(): void {
  const next = future.value.pop();
  if (!next) return;
  history.value.push(cloneGrid(grid.value));
  grid.value = next;
  markDirty();
}

function markDirty(): void {
  if (suppressAutosave) return;
  const targetProjectId = draftTargetId.value;
  dirty.value = true;
  hasLocalDraft.value = true;
  status.value = "正在保存…";
  draftGeneration += 1;
  window.clearTimeout(saveTimer);
  saveTimer = window.setTimeout(() => { void flushDraft(); }, 500);
}

