    paletteContractVersion: 1,
    paletteId: workspacePalette.value?.id ?? workspacePaletteId.value,
    paletteVersion: workspacePalette.value?.version ?? workspacePaletteVersion.value,
  };
}

function prepareLegacyDraft(sourceKey: string, savedName: string, savedGrid: PatternGrid, knownCurrentContract = false): PatternGrid {
  if (knownCurrentContract) return savedGrid;
  const plan = planLegacyGridMigration(savedGrid, { unversioned: true });
  if (!plan.isLegacy) return savedGrid;
  const detectedAt = new Date().toISOString();
  const backupKey = `pindou-web-legacy-backup:${Date.now()}`;
  localStorage.setItem(backupKey, JSON.stringify({
    name: savedName,
    grid: savedGrid,
    audit: { version: LEGACY_GRID_MIGRATION_VERSION, sourceKey, detectedAt, decision: plan.requiresConfirmation ? "pending" : "auto-migrated", entries: plan.entries },
  }));
  if (plan.requiresConfirmation) {
    legacyMigrationReview.value = { sourceKey, backupKey, originalGrid: cloneGrid(savedGrid), plan };
    lastCloudSaveFailed = true;
    status.value = "旧草稿含需确认的色号 · 云端提交已暂停";
    return savedGrid;
  }
  return plan.migratedGrid;
}

function confirmLegacyMigration(): void {
  const review = legacyMigrationReview.value;
  if (!review) return;
  const migrationPalette = shared.state.palettes.find((palette) => palette.id === "mard-291-v1");
  if (!migrationPalette) {
    lastCloudSaveFailed = true;
    status.value = "291 色迁移色卡尚未加载";
    notify("请先重试加载色卡，迁移确认前不会写入云端");
    return;
  }
  if (!gridUsesOnlyPaletteCodes(review.plan.migratedGrid, migrationPalette)) {
    lastCloudSaveFailed = true;
    status.value = "迁移结果含非 291 色卡色号 · 云端提交已阻止";
    notify("旧草稿含无法安全迁移到 291 色卡的色号");
    return;
  }
  const stored = JSON.parse(localStorage.getItem(review.backupKey) ?? "{}") as Record<string, unknown> & { audit?: Record<string, unknown> };
  localStorage.setItem(review.backupKey, JSON.stringify({
    ...stored,
    audit: { ...stored.audit, decision: "confirmed", confirmedAt: new Date().toISOString() },
  }));
  grid.value = cloneGrid(review.plan.migratedGrid);
  setWorkspacePalette(migrationPalette.id, migrationPalette.version);
  legacyMigrationReview.value = null;
  lastCloudSaveFailed = !cloudProjectGridCompatible(grid.value);
  status.value = lastCloudSaveFailed
    ? `迁移已确认 · 单边超过 ${CLOUD_PROJECT_MAX_EDGE} 格，仅保存在本机`
    : "旧色号迁移已确认，正在保存";
  markDirty();
  scheduleDraw();
}

function keepCurrentPaletteCodes(): void {
  const review = legacyMigrationReview.value;
  if (!review) return;
  const migrationPalette = shared.state.palettes.find((palette) => palette.id === "mard-291-v1");
  if (!migrationPalette || !gridUsesOnlyPaletteCodes(review.originalGrid, migrationPalette)) {
    lastCloudSaveFailed = true;
    status.value = "原色号不完全属于 291 色卡 · 云端提交已阻止";
    notify("原色号无法按 291 色卡安全解释，请采用建议迁移");
    return;
  }
  const stored = JSON.parse(localStorage.getItem(review.backupKey) ?? "{}") as Record<string, unknown> & { audit?: Record<string, unknown> };
  localStorage.setItem(review.backupKey, JSON.stringify({
    ...stored,
    audit: { ...stored.audit, decision: "kept-original", confirmedAt: new Date().toISOString() },
  }));
  grid.value = cloneGrid(review.originalGrid);
  setWorkspacePalette(migrationPalette.id, migrationPalette.version);
  legacyMigrationReview.value = null;
  lastCloudSaveFailed = !cloudProjectGridCompatible(grid.value);
  status.value = lastCloudSaveFailed ? "原色号已保留 · 大图仅保存在本机" : "已确认使用当前色卡编码";
  markDirty();
}

function flushDraft(): Promise<void> {
  window.clearTimeout(saveTimer);
  if (!dirty.value) return saveQueue;
  const generation = draftGeneration;
  const targetProjectId = draftTargetId.value;
  const savedName = projectName.value;
  const savedGrid = cloneGrid(grid.value);
  saveQueue = saveQueue.catch(() => undefined).then(async () => {
    let cloudSaved = true;
    const key = `pindou-web-draft:${targetProjectId ?? "local"}`;
    localStorage.setItem(key, JSON.stringify({ name: savedName, grid: savedGrid, synced: false, updatedAt: new Date().toISOString(), ...localDraftContract() }));
    if (legacyMigrationReview.value) {
      cloudSaved = false;
      lastCloudSaveFailed = true;
      status.value = "本机原稿已备份 · 确认旧色号替换前不会提交新 revision";
    } else if (shared.state.status === "synced" && targetProjectId && workspacePalette.value?.id !== shared.state.activeProject?.paletteId) {
      cloudSaved = false;
      lastCloudSaveFailed = true;
      status.value = "本机已保存 · 色卡与云端作品不一致";
      notify("当前草稿色卡与云端作品不一致，请先完成明确的作品换卡迁移");
    } else if (shared.state.status === "synced" && targetProjectId && !cloudProjectGridCompatible(savedGrid)) {
      cloudSaved = false;
      lastCloudSaveFailed = true;
      status.value = `本机已保存 · 云端单边上限为 ${CLOUD_PROJECT_MAX_EDGE} 格`;
      const noticeKey = `${savedGrid.width}x${savedGrid.height}`;
      if (lastCloudContractNotice !== noticeKey) {
        lastCloudContractNotice = noticeKey;
        notify(`当前 ${savedGrid.width}×${savedGrid.height} 图纸保留在本机；云端普通作品单边最多 ${CLOUD_PROJECT_MAX_EDGE} 格，未提交`);
      }
    } else if (shared.state.status === "synced" && targetProjectId) {
      status.value = "正在同步云端…";
      try {
        await shared.saveDraft(targetProjectId, savedGrid, savedName);
        lastCloudSaveFailed = false;
        if (draftConflict.value?.projectId === targetProjectId) draftConflict.value = null;
        localStorage.setItem(key, JSON.stringify({ name: savedName, grid: savedGrid, synced: true, updatedAt: new Date().toISOString(), ...localDraftContract() }));
        status.value = "已同步到小程序与 Web";
      } catch (error) {
        cloudSaved = false;
        lastCloudSaveFailed = true;
        status.value = "本机已保存 · 云端同步失败";
        if (error instanceof ApiError && error.status === 409 && targetProjectId) {
          try {
            const [{ project }, draftResult] = await Promise.all([
              shared.api.project(targetProjectId),
              shared.api.draft(targetProjectId) as Promise<{ draft: { draftRevision: number; grid: PatternGrid; name?: string } | null }>,
            ]);
            shared.state.activeProject = project;
            shared.state.draftRevision = draftResult.draft?.draftRevision ?? 0;
            draftConflict.value = {
              projectId: targetProjectId,
              localGrid: savedGrid,
              localName: savedName,
              remoteGrid: draftResult.draft?.grid ?? project.grid,
              remoteName: draftResult.draft?.name ?? project.name,
            };
          } catch { /* keep the recoverable local backup */ }
        }
        notify(error instanceof Error ? error.message : "云端草稿保存失败");
      }
    } else status.value = "已自动保存到本机";
    if (draftGeneration === generation) dirty.value = !cloudSaved;
  });
  return saveQueue;
}

function restoreUnsyncedProjectBackup(projectId: string): boolean {
  try {
    const local = JSON.parse(localStorage.getItem(`pindou-web-draft:${projectId}`) ?? "null") as { name?: string; grid?: PatternGrid; synced?: boolean; paletteContractVersion?: number; paletteId?: string | null; paletteVersion?: number | null } | null;
    const localGrid = local?.grid;
    if (local?.synced === false && localGrid && localGrid.cells.length === localGrid.width * localGrid.height) {
      suppressAutosave = true;
      restoreWorkspacePalette(local);
      projectName.value = local.name || projectName.value;
      grid.value = prepareLegacyDraft(`pindou-web-draft:${projectId}`, local.name || projectName.value, localGrid, local.paletteContractVersion === 1);
      status.value = "已恢复尚未同步的本机草稿";
      lastCloudSaveFailed = true;
      queueMicrotask(() => { suppressAutosave = false; markDirty(); });
      return true;
    }
  } catch { /* ignore a corrupt project-local backup */ }
  return false;
}

async function keepLocalDraft(): Promise<void> {
  const conflict = draftConflict.value;
  if (!conflict || shared.state.activeProject?.id !== conflict.projectId) return;
  const latestGrid = cloneGrid(grid.value);
  const latestName = projectName.value;
  try {
    await shared.saveDraft(conflict.projectId, latestGrid, latestName);
    grid.value = latestGrid;
    projectName.value = latestName;
    lastCloudSaveFailed = false;
    dirty.value = false;
    draftConflict.value = null;
    status.value = "已同步到小程序与 Web";
    localStorage.setItem(`pindou-web-draft:${conflict.projectId}`, JSON.stringify({ name: latestName, grid: latestGrid, synced: true, updatedAt: new Date().toISOString(), ...localDraftContract() }));
    scheduleDraw();
  } catch (error) { notify(error instanceof Error ? error.message : "本机草稿覆盖失败"); }
}

function useCloudDraft(): void {
  const conflict = draftConflict.value;
  if (!conflict) return;
  grid.value = cloneGrid(conflict.remoteGrid);
  projectName.value = conflict.remoteName;
  dirty.value = false;
  lastCloudSaveFailed = false;
  draftConflict.value = null;
  status.value = "已采用云端草稿";
  localStorage.setItem(`pindou-web-draft:${conflict.projectId}`, JSON.stringify({ name: conflict.remoteName, grid: conflict.remoteGrid, synced: true, updatedAt: new Date().toISOString(), ...localDraftContract() }));
  scheduleDraw();
}

function applySharedState(options: { forceProject?: boolean } = {}): void {
  credits.value = shared.state.credits;
  const preserveLocalWorkspace = !options.forceProject && draftTargetId.value === null && hasLocalDraft.value;
  if (preserveLocalWorkspace) {
    // Hydration may load the account's last cloud project into shared state.
    // The browser draft remains the active canvas and keeps its own palette.
    settings.palette = paletteName.value;
    if (!paletteMap.value.has(selectedCode.value)) selectedCode.value = beadPalette.value[0]?.code ?? "A01";
    return;
  }
  const project = shared.state.activeProject;
  if (!project) {
    draftTargetId.value = null;
    hasLocalDraft.value = Boolean(localStorage.getItem("pindou-web-draft:local"));
    if (!hasLocalDraft.value) setWorkspacePalette(shared.state.activePalette?.id ?? null, shared.state.activePalette?.version ?? null);
    return;
  }
  if (legacyMigrationReview.value && legacyMigrationReview.value.sourceKey !== `pindou-web-draft:${project.id}`) {
    legacyMigrationReview.value = null;
    lastCloudSaveFailed = false;
  }
  suppressAutosave = true;
  projectName.value = project.name;
  grid.value = cloneGrid(project.grid);
  draftTargetId.value = project.id;
  setWorkspacePalette(project.paletteId, shared.state.palettes.find((palette) => palette.id === project.paletteId)?.version ?? null);
  createMode.value = project.mode;
  hasLocalDraft.value = true;
  status.value = "已同步到小程序与 Web";
  scheduleDraw();
  queueMicrotask(() => { suppressAutosave = false; });
  restoreUnsyncedProjectBackup(project.id);
}

async function openProject(projectId: string): Promise<void> {
  await flushDraft();
  if (lastCloudSaveFailed && draftTargetId.value && draftTargetId.value !== projectId) { notify("当前作品尚未同步，已阻止切换；请恢复网络后重试"); return; }
  try {
    await shared.openProject(projectId);
    applySharedState({ forceProject: true });
  // A source from another workspace must never regenerate this project's grid.
  if (sourceUrl.value.startsWith("blob:")) URL.revokeObjectURL(sourceUrl.value);
  sourceUrl.value = ""; sourceImage.value = null; sourceFile.value = null;
  try {
    const recovered = await subjectEditorSource(projectId, shared.state.userId);
    if (recovered && currentCloudProjectId.value === projectId) {
      sourceUrl.value = recovered.url; sourceImage.value = recovered.image; sourceFile.value = recovered.file;
      settings.transparentBackground = true; settings.size = recovered.size; settings.maxColors = recovered.maxColors;
    } else if (recovered) URL.revokeObjectURL(recovered.url);
  } catch { /* The saved grid remains editable when the local image has expired. */ }
    history.value = [];
    future.value = [];
    navigate("editor");
    notify(`已打开 ${projectName.value}`);
  } catch (error) {
    notify(error instanceof Error ? error.message : "作品加载失败");
  }
}

async function openGalleryWork(work: GalleryWork): Promise<void> {
  try {
    await flushDraft();
    let palette = shared.state.palettes.find((item) => item.id === "mard-221-v1");
    let usedBundledPalette = false;
    if (!palette && shared.state.paletteStatus !== "ready") {
      try {
        await shared.refreshPalettes();
        palette = shared.state.palettes.find((item) => item.id === "mard-221-v1");
      } catch {
        // Gallery assets are local and must remain editable while the cloud API is unavailable.
      }
    }
    if (!palette) {
      palette = shared.ensureBundledPalette();
      usedBundledPalette = true;
    } else if (shared.state.paletteStatus === "error") {
      usedBundledPalette = true;
    }
    const response = await fetch(work.data, { cache: "no-cache" });
    if (!response.ok) throw new Error(`图纸数据读取失败（${response.status}）`);
    const validCodes = new Set(palette.colors.filter((color) => color.available).map((color) => color.code));
    const nextGrid = parseGalleryPattern(await response.json(), work, validCodes);
    const galleryImage = new Image();
    await new Promise<void>((resolve, reject) => {
      galleryImage.onload = () => resolve();
      galleryImage.onerror = () => reject(new Error("4K 高清原图读取失败"));
      galleryImage.src = work.display;
    });

    suppressAutosave = true;
    draftTargetId.value = null;
    projectName.value = work.title;
    grid.value = nextGrid;
    if (sourceUrl.value.startsWith("blob:")) URL.revokeObjectURL(sourceUrl.value);
    sourceUrl.value = work.display;
    sourceImage.value = galleryImage;
    sourceFile.value = null;
    setWorkspacePalette(palette.id, palette.version);
    createMode.value = "pixel";
    settings.size = Math.max(work.width, work.height);
    settings.maxColors = work.usedColors;
    settings.preset = "balanced";
    zoom.value = 2;
    previewZoom.value = 1;
    showGrid.value = false;
    showCodes.value = false;
    editorViewMode.value = "preview";
    history.value = [];
    future.value = [];
    cursorIndex.value = 0;
    hasLocalDraft.value = true;
    dirty.value = false;
    lastCloudSaveFailed = false;
    draftConflict.value = null;
    status.value = "已从高清图纸库载入 · 正在保存";
    localStorage.setItem("pindou-web-draft:local", JSON.stringify({
      name: work.title,
      grid: nextGrid,
      synced: false,
      source: { type: "gallery", id: work.id },
      updatedAt: new Date().toISOString(),
      paletteContractVersion: 1,
      paletteId: palette.id,
      paletteVersion: palette.version,
    }));
    suppressAutosave = false;
    status.value = "已从高清图纸库载入 · 自动保存到本机";
    scheduleMaterialCount();
    await navigate("editor");
    notify(usedBundledPalette
      ? `已在编辑器中打开《${work.title}》 · 当前使用内置 221 色卡`
      : `已在编辑器中打开《${work.title}》`);
  } catch (error) {
    suppressAutosave = false;
    notify(error instanceof Error ? error.message : "图纸载入失败，请稍后重试");
  }
}

async function renameProject(projectId: string): Promise<void> {
  await flushDraft();
  if (lastCloudSaveFailed && shared.state.activeProject?.id === projectId) { notify("云端草稿尚未同步，已阻止重命名以免丢失编辑"); return; }
  if (shared.state.activeProject?.id === projectId) await shared.commitActiveDraft();
  const { project } = await shared.api.project(projectId);
  const name = window.prompt("输入新的作品名称", project.name)?.trim();
  if (!name || name === project.name) return;
  try {
    await shared.api.renameProject(project, name);
    await shared.refresh();
    applySharedState();
    notify("作品已重命名并同步");
  } catch (error) {
    notify(error instanceof Error ? error.message : "作品重命名失败");
  }
}

async function copyProject(projectId: string): Promise<void> {
