async function changePaletteById(paletteId: string): Promise<void> {
  if (!paletteId) return;
  if (currentCloudProjectId.value
    ? paletteId === shared.state.activeProject?.paletteId
    : paletteId === workspacePalette.value?.id) return;
  if (currentCloudProjectId.value && shared.state.status !== "synced") {
    notify("作品换卡需要先连接共享账号；本地新作品仍可选择正式色卡");
    return;
  }
  if (currentCloudProjectId.value && !window.confirm("更换色卡会按最近色创建新的作品版本，是否继续？")) return;
  try {
    const migratingRetiredLegacy = Boolean(
      currentCloudProjectId.value
      && shared.state.activeProject?.paletteId === "mard-basic-v1"
      && paletteId === "mard-291-v1",
    );
    if (migratingRetiredLegacy) {
      if ((dirty.value || shared.state.draftRevision > 0) && !window.confirm(
        "旧色卡迁移会从已提交的图纸版本创建新版本，并丢弃当前未提交草稿。是否继续？",
      )) return;
    } else {
      await flushDraft();
      if (currentCloudProjectId.value && lastCloudSaveFailed) { notify("云端草稿尚未同步，已阻止换色卡以免丢失编辑"); return; }
    }
    if (currentCloudProjectId.value) {
      if (!migratingRetiredLegacy) await shared.commitActiveDraft();
      try {
        await shared.changePalette(paletteId, settings.maxColors);
      } catch (error) {
        if (!(error instanceof ApiError) || error.code !== "LEGACY_PALETTE_CONFIRMATION_REQUIRED") throw error;
        const details = parseLegacyPaletteConfirmationDetails(error.details);
        if (!details) throw new Error("服务端返回的旧色卡迁移详情无效，已阻止确认");
        if (!window.confirm(legacyPaletteConfirmationMessage(details))) {
          status.value = `已取消 ${details.migrationVersion} 迁移，原作品未变更`;
          notify("旧色卡迁移已取消，未提交任何映射");
          return;
        }
        // This is a distinct mutation call, so ApiClient creates a fresh
        // idempotency key rather than replaying the rejected request.
        await shared.changePalette(paletteId, settings.maxColors, true);
      }
      applySharedState({ forceProject: true });
      notify("色卡已切换；作品已保留旧版本并完成换卡");
    } else {
      setWorkspacePalette(paletteId);
      markDirty();
      notify("本机作品已切换色卡，下次生成将使用新色卡");
    }
  } catch (error) {
    notify(error instanceof Error ? error.message : "色卡切换失败");
  }
}

