async function importPalette(event: Event): Promise<void> {
  const input = event.target as HTMLInputElement;
  const file = input.files?.[0];
  input.value = "";
  if (!file) return;
  try {
    const text = await file.text();
    let payload: { name: string; brand: string; beadSizeMm: number; colors: Array<{ code: string; name: string; hex: string; unitPriceCents?: number }> };
    if (file.name.toLowerCase().endsWith(".json")) {
      payload = JSON.parse(text) as typeof payload;
    } else {
      const rows = parseCsv(text).slice(1);
      payload = {
        name: file.name.replace(/\.[^.]+$/, ""),
        brand: "用户导入",
        beadSizeMm: 5,
        colors: rows.map(([code, name, hex, price]) => ({ code: code ?? "", name: name || code || "", hex: hex ?? "", unitPriceCents: Number(price) || 0 })),
      };
    }
    if (!payload.name?.trim() || !payload.brand?.trim() || !Number.isFinite(payload.beadSizeMm) || payload.colors?.length < 2 || payload.colors.some((color) => !color.code || !color.name || !/^#[0-9a-f]{6}$/i.test(color.hex))) {
      throw new Error("色卡文件无效：需包含名称、品牌、豆径，以及至少 2 个 code/name/#RRGGBB 颜色");
    }
    await shared.api.createPalette(payload);
    await shared.refresh();
    applySharedState();
    notify(`已导入自定义色卡“${payload.name}”`);
  } catch (error) {
    notify(error instanceof Error ? error.message : "色卡导入失败");
  }
}

async function connectAccount(): Promise<void> {
  if (logoutBusy.value || shared.state.status === "connecting") {
    notify(logoutBusy.value ? webLogoutBusyMessage() : "正在连接共享账号…");
    return;
  }
  if (shared.state.status === "synced") {
    await logoutAccount();
    return;
  }
  await startWebLogin();
}

function inviteGate() {
  return {
    synced: shared.state.status === "synced",
    busy: inviteBusy.value,
    loadFailed: inviteFailed.value,
  };
}

async function loadInvite(): Promise<void> {
  const gate = inviteGate();
  if (!canLoadWebInvite(gate) && !canRetryWebInviteLoad(gate)) {
    notify(webInviteOfflineMessage());
    return;
  }
  inviteBusy.value = true;
  try {
    const ensured = await shared.api.ensureInviteCode();
    const summary = ensured.inviteSummary as {
      invite?: { code?: string };
      binding?: { inviteCode?: string } | null;
      rewardPolicy?: { awardsCredits?: boolean };
    };
    inviteCode.value = ensured.invite.code;
    inviteBoundCode.value = summary.binding?.inviteCode ?? null;
    inviteFailed.value = false;
    inviteMessage.value = null;
    notify(`邀请码 ${ensured.invite.code} 已就绪。${webInvitePendingRewardMessage()}`);
  } catch (error) {
    const outcome = interpretWebInviteFailure(error);
    inviteFailed.value = outcome.kind === "retryable";
    inviteMessage.value = outcome.message;
    notify(outcome.message);
  } finally {
    inviteBusy.value = false;
  }
}

async function acceptInvite(): Promise<void> {
  const gate = { ...inviteGate(), hasPendingCode: Boolean(pendingInviteCode.value.trim()) };
  if (!canAcceptWebInvite(gate)) {
    notify(gate.synced ? "请填写有效邀请码后再接受。" : webInviteOfflineMessage());
    return;
  }
  inviteBusy.value = true;
  try {
    const result = await shared.api.acceptInvite(pendingInviteCode.value.trim().toUpperCase()) as {
      inviteSummary: {
        invite?: { code?: string };
        binding?: { inviteCode?: string } | null;
        entitlements?: Array<{ status?: string; creditLedgerId?: string | null }>;
        rewardPolicy?: { awardsCredits?: boolean };
      };
      rewardApplied?: { delta?: number } | null;
    };
    const summary = result.inviteSummary;
    inviteCode.value = summary.invite?.code ?? inviteCode.value;
    inviteBoundCode.value = summary.binding?.inviteCode ?? null;
    inviteFailed.value = false;
    const unexpectedCredit = !summary.rewardPolicy?.awardsCredits
      && (summary.entitlements || []).some((entry) => entry.status === "credited" || entry.creditLedgerId);
    inviteMessage.value = unexpectedCredit
      ? "服务端奖励策略异常：本客户端拒绝伪造到账。"
      : result.rewardApplied?.delta
        ? `邀请已绑定，邀请人应到账 +${result.rewardApplied.delta} 次（以账本为准）`
        : "邀请已绑定，次数以服务端账本为准。";
    notify(
      result.rewardApplied?.delta
        ? `邀请已绑定；邀请人应到账 +${result.rewardApplied.delta} 次（以账本为准）`
        : inviteMessage.value,
    );
    await shared.refreshCredits().catch(() => undefined);
    credits.value = shared.state.credits;
  } catch (error) {
    const outcome = interpretWebInviteFailure(error);
    inviteFailed.value = outcome.kind === "retryable";
    inviteMessage.value = outcome.message;
    notify(outcome.message);
  } finally {
    inviteBusy.value = false;
  }
}

async function saveCloudVersion(): Promise<void> {
  const gate = {
    synced: shared.state.status === "synced",
    busy: saveVersionBusy.value,
    hasCloudProject: Boolean(currentCloudProjectId.value && shared.state.activeProject?.id === currentCloudProjectId.value),
    hasUnresolvedDraftIssue: Boolean(draftConflict.value || lastCloudSaveFailed),
  };
  if (!canStartWebSaveVersion(gate) && !canRetryWebSaveVersion({ ...gate, lastFailed: saveVersionFailed.value })) {
    if (!gate.synced || !gate.hasCloudProject) {
      notify(webSaveVersionOfflineMessage());
      return;
    }
    if (gate.hasUnresolvedDraftIssue) {
      notify(webSaveVersionDraftIssueMessage());
      return;
    }
    notify(webSaveVersionBusyMessage());
    return;
  }
  if (!window.confirm(webSaveVersionConfirmMessage(projectName.value))) return;
  saveVersionBusy.value = true;
  try {
    await flushDraft();
    if (lastCloudSaveFailed || draftConflict.value) {
      saveVersionFailed.value = true;
      notify(webSaveVersionDraftIssueMessage());
      return;
    }
    const beforeRevision = shared.state.activeProject?.currentRevision ?? 0;
    if (shared.state.draftRevision === 0) {
      saveVersionFailed.value = false;
      status.value = webSaveVersionAlreadyCurrentMessage(beforeRevision);
      notify(webSaveVersionAlreadyCurrentMessage(beforeRevision));
      return;
    }
    const project = await shared.commitActiveDraft();
    if (!project) {
      saveVersionFailed.value = true;
      notify(webSaveVersionOfflineMessage());
      return;
    }
    applySharedState({ forceProject: true });
    saveVersionFailed.value = false;
    status.value = `已保存版本 ${project.currentRevision}`;
    notify(webSaveVersionSuccessMessage(project.currentRevision));
  } catch (error) {
    const outcome = interpretWebSaveVersionFailure(error);
    saveVersionFailed.value = outcome.kind === "retryable" || outcome.kind === "conflict";
    if (outcome.kind === "unauthorized") {
      saveVersionFailed.value = false;
    }
    notify(outcome.message);
  } finally {
    saveVersionBusy.value = false;
  }
}

async function logoutAccount(): Promise<void> {
  const gate = {
    synced: shared.state.status === "synced",
    busy: logoutBusy.value || shared.state.status === "connecting",
    hasToken: Boolean(shared.api.getToken()),
  };
  if (!canStartWebLogout(gate) && !canRetryWebLogout({ ...gate, lastFailed: logoutFailed.value })) {
    notify(webLogoutOfflineMessage());
    return;
  }
  const hasUnsaved = dirty.value || hasLocalDraft.value;
  if (!window.confirm(webLogoutConfirmMessage(hasUnsaved))) return;
  logoutBusy.value = true;
  cancelWebLogin({ silent: true });
  try {
    await flushDraft().catch(() => undefined);
    await shared.logout();
    logoutFailed.value = false;
    if (draftTargetId.value) {
      const snapshotName = projectName.value;
      const snapshotGrid = cloneGrid(grid.value);
      localStorage.setItem("pindou-web-draft:local", JSON.stringify({
        name: snapshotName,
        grid: snapshotGrid,
        synced: false,
        updatedAt: new Date().toISOString(),
        ...localDraftContract(),
      }));
      draftTargetId.value = null;
      hasLocalDraft.value = true;
    } else {
      hasLocalDraft.value = Boolean(localStorage.getItem("pindou-web-draft:local"));
    }
    credits.value = null;
    applySharedState();
    status.value = dirty.value ? "未保存 · 本地草稿" : (hasLocalDraft.value ? "本地草稿已保留" : "本地模式");
    notify(webLogoutSuccessMessage());
  } catch (error) {
    logoutFailed.value = true;
    notify(error instanceof Error ? error.message : "退出登录失败，可重试");
  } finally {
    logoutBusy.value = false;
  }
}

async function startWebLogin(): Promise<void> {
  if (webLoginBusy.value) {
    notify(webLoginCreatingMessage());
    return;
  }
  const generation = nextWebLoginGeneration(webLoginGeneration);
  webLoginGeneration = generation;
  webLoginBusy.value = true;
  webLoginPhase.value = "creating";
  webLoginCode.value = "";
  webLoginExpiresAt.value = "";
  try {
    const challenge = await shared.api.createWebLoginChallenge();
    if (generation !== webLoginGeneration) return;
    webLoginCode.value = challenge.code;
    webLoginExpiresAt.value = challenge.expiresAt;
    webLoginPhase.value = "waiting";
    pollWebLogin(challenge.token, challenge.sessionToken, generation);
  } catch (error) {
    if (generation !== webLoginGeneration) return;
    webLoginBusy.value = false;
    webLoginPhase.value = "idle";
    webLoginCode.value = "";
    notify(error instanceof Error ? error.message : "Web 登录请求创建失败");
  }
}

function pollWebLogin(pollToken: string, sessionToken: string, generation: number): void {
  window.clearTimeout(loginPoll);
  loginPoll = window.setTimeout(async () => {
    if (generation !== webLoginGeneration) return;
    try {
      const result = await shared.api.webLoginStatus(pollToken);
      if (generation !== webLoginGeneration) return;
      if (shouldAdoptWebLogin({ generation, activeGeneration: webLoginGeneration, status: result.status })) {
        webLoginPhase.value = "adopting";
        await shared.adoptWebSession(sessionToken, pollToken);
        if (generation !== webLoginGeneration) return;
        applySharedState();
        webLoginCode.value = "";
        webLoginBusy.value = false;
        webLoginPhase.value = "idle";
        notify("微信账号已连接，作品与次数开始共享");
        return;
      }
      if (result.status === "expired") {
        webLoginBusy.value = false;
        webLoginPhase.value = "idle";
        webLoginCode.value = "";
        notify("配对码已过期，请重新获取");
        return;
      }
      if (shouldContinueWebLoginPoll({ generation, activeGeneration: webLoginGeneration, status: result.status })) {
        pollWebLogin(pollToken, sessionToken, generation);
      }
    } catch (error) {
      if (generation !== webLoginGeneration) return;
      webLoginBusy.value = false;
      webLoginPhase.value = "idle";
      webLoginCode.value = "";
      notify(error instanceof Error ? error.message : "登录状态读取失败");
    }
  }, 1500);
}

function cancelWebLogin(options?: { silent?: boolean }): void {
  webLoginGeneration = nextWebLoginGeneration(webLoginGeneration);
  window.clearTimeout(loginPoll);
  loginPoll = undefined;
  const hadBusy = webLoginBusy.value || webLoginPhase.value !== "idle";
  webLoginBusy.value = false;
  webLoginPhase.value = "idle";
  webLoginCode.value = "";
  webLoginExpiresAt.value = "";
  if (hadBusy && !options?.silent) notify(webLoginCancelKeepsLocalDraftMessage());
}

async function ensureLocalExportReady(): Promise<boolean> {
  await flushDraft();
  if (shared.state.status === "synced" && draftTargetId.value && (lastCloudSaveFailed || draftConflict.value)) {
    notify("请先完成云端同步或解决草稿冲突，再打印或导出");
    return false;
  }
  return true;
}

async function printPage(): Promise<void> {
  if (!await ensureLocalExportReady()) return;
  window.print();
}

function notify(message: string): void {
  toast.value = message;
  window.setTimeout(() => {
    if (toast.value === message) toast.value = "";
  }, 2200);
}

function toggleRail(): void {
  railCollapsed.value = !railCollapsed.value;
  localStorage.setItem("pindou-web-rail-collapsed", railCollapsed.value ? "1" : "0");
}

function showZoomHintOnce(): void {
  if (localStorage.getItem("pindou-web-zoom-hint-seen") === "1") return;
  localStorage.setItem("pindou-web-zoom-hint-seen", "1");
  zoomHintVisible.value = true;
  window.clearTimeout(zoomHintTimer);
  zoomHintTimer = window.setTimeout(() => { zoomHintVisible.value = false; }, 6500);
}

function dismissZoomHint(): void {
  zoomHintVisible.value = false;
  window.clearTimeout(zoomHintTimer);
}

function clampPreviewZoom(value: number): number {
  return Math.max(previewZoomMin, Math.min(previewZoomMax, Math.round(value * 10) / 10));
}

function setEditorViewMode(mode: "preview" | "edit"): void {
  if (mode === "edit") {
    showCodes.value = true;
    zoom.value = Math.max(14, zoom.value);
  }
  if (editorViewMode.value === mode) {
    if (mode === "edit") scheduleDraw();
    return;
  }
  editorViewMode.value = mode;
  nextTick(() => {
    if (mode === "edit") scheduleDraw();
  });
}

function updatePreviewZoom(nextValue: number, clientX?: number, clientY?: number): void {
  const nextZoom = clampPreviewZoom(nextValue);
  if (nextZoom === previewZoom.value) return;
  const scroller = canvasScroller.value;
  const stage = previewStage.value;
  if (!scroller || !stage) {
    previewZoom.value = nextZoom;
    return;
  }

  const bounds = scroller.getBoundingClientRect();
  const pointerX = clientX === undefined ? scroller.clientWidth / 2 : clientX - bounds.left;
  const pointerY = clientY === undefined ? scroller.clientHeight / 2 : clientY - bounds.top;
  const previousWidth = Math.max(1, stage.offsetWidth);
  const previousHeight = Math.max(1, stage.offsetHeight);
  const logicalX = (scroller.scrollLeft + pointerX - stage.offsetLeft) / previousWidth;
  const logicalY = (scroller.scrollTop + pointerY - stage.offsetTop) / previousHeight;
  previewZoom.value = nextZoom;

  nextTick(() => window.requestAnimationFrame(() => {
    const nextStage = previewStage.value;
    if (!nextStage) return;
    scroller.scrollLeft = nextStage.offsetLeft + logicalX * nextStage.offsetWidth - pointerX;
    scroller.scrollTop = nextStage.offsetTop + logicalY * nextStage.offsetHeight - pointerY;
  }));
}

function changeEditorZoom(direction: -1 | 1): void {
  if (editorViewMode.value === "preview") {
    updatePreviewZoom(previewZoom.value + direction * 0.1);
    return;
  }
  zoom.value = Math.max(2, Math.min(zoomMax.value, zoom.value + direction * 2));
}

function editorWheel(event: WheelEvent): void {
  if (!event.ctrlKey) return;
  event.preventDefault();
  const scroller = canvasScroller.value;
  if (!scroller) return;
  if (editorViewMode.value === "preview") {
    updatePreviewZoom(previewZoom.value + (event.deltaY < 0 ? 0.1 : -0.1), event.clientX, event.clientY);
    return;
  }
  const stage = canvasStage.value;
  if (!stage) return;
  const previous = cellSize.value;
  const nextZoom = Math.max(2, Math.min(zoomMax.value, zoom.value + (event.deltaY < 0 ? 2 : -2)));
  if (nextZoom === zoom.value) return;
  const bounds = scroller.getBoundingClientRect();
  const pointerX = event.clientX - bounds.left;
  const pointerY = event.clientY - bounds.top;
  const logicalX = (Math.max(0, scroller.scrollLeft - stage.offsetLeft) + pointerX) / previous;
  const logicalY = (Math.max(0, scroller.scrollTop - stage.offsetTop) + pointerY) / previous;
  zoom.value = nextZoom;
  nextTick(() => window.requestAnimationFrame(() => {
    scroller.scrollLeft = stage.offsetLeft + logicalX * cellSize.value - pointerX;
    scroller.scrollTop = stage.offsetTop + logicalY * cellSize.value - pointerY;
    scheduleDraw();
  }));
}

function draw(): void {
  const target = canvas.value;
  const scroller = canvasScroller.value;
  const stage = canvasStage.value;
  if (!target || !scroller || !stage) return;
  const cell = cellSize.value;
  const logicalWidth = grid.value.width * cell;
  const logicalHeight = grid.value.height * cell;
  const viewportX = Math.max(0, Math.min(logicalWidth, scroller.scrollLeft - stage.offsetLeft));
  const viewportY = Math.max(0, Math.min(logicalHeight, scroller.scrollTop - stage.offsetTop));
  const width = Math.max(1, Math.min(logicalWidth - viewportX, scroller.clientWidth + cell * 3));
  const height = Math.max(1, Math.min(logicalHeight - viewportY, scroller.clientHeight + cell * 3));
  canvasViewport.x = viewportX;
  canvasViewport.y = viewportY;
  canvasViewport.width = width;
  canvasViewport.height = height;
  const ratio = Math.max(1, Math.min(1.5, window.devicePixelRatio || 1));
  target.width = Math.ceil(width * ratio);
  target.height = Math.ceil(height * ratio);
  target.style.width = `${width}px`;
  target.style.height = `${height}px`;
  target.style.transform = `translate(${viewportX}px, ${viewportY}px)`;
  const context = target.getContext("2d");
  if (!context) return;
  context.scale(ratio, ratio);
  context.clearRect(0, 0, width, height);

  const startX = Math.max(0, Math.floor(viewportX / cell));
  const startY = Math.max(0, Math.floor(viewportY / cell));
  const endX = Math.min(grid.value.width, Math.ceil((viewportX + width) / cell));
  const endY = Math.min(grid.value.height, Math.ceil((viewportY + height) / cell));
  for (let y = startY; y < endY; y += 1) {
    for (let x = startX; x < endX; x += 1) {
      const code = grid.value.cells[y * grid.value.width + x];
      const color = code ? paletteMap.value.get(code) : null;
      const isMuted = highlightedCode.value && code !== highlightedCode.value;
      context.fillStyle = color?.hex ?? "#ffffff";
      context.globalAlpha = isMuted ? 0.16 : 1;
      const drawX = x * cell - viewportX;
      const drawY = y * cell - viewportY;
      context.fillRect(drawX, drawY, cell, cell);
      if (showCodes.value && cell >= 14 && code) {
        context.globalAlpha = isMuted ? 0.2 : 0.72;
        context.fillStyle = luminance(color?.hex ?? "#ffffff") > 145 ? "#20201e" : "#ffffff";
        context.font = `700 ${Math.max(5, Math.min(cell * 0.36, cell - 2))}px Inter, sans-serif`;
        context.textAlign = "center";
        context.textBaseline = "middle";
        context.fillText(code, drawX + cell / 2, drawY + cell / 2 + 0.5);
      }
    }
  }
  context.globalAlpha = 1;
  if (effectiveShowGrid.value) {
    const minorAlpha = cell <= 6 ? .065 : cell <= 9 ? .1 : .14;
    const majorAlpha = cell <= 6 ? .22 : cell <= 9 ? .31 : .42;
    for (let x = startX; x <= endX; x += 1) {
      context.beginPath();
      context.strokeStyle = `rgba(73,63,44,${x % 10 === 0 ? majorAlpha : minorAlpha})`;
      context.lineWidth = x % 10 === 0 ? 1.25 : 0.5;
      context.moveTo(x * cell - viewportX, 0);
      context.lineTo(x * cell - viewportX, height);
      context.stroke();
    }
    for (let y = startY; y <= endY; y += 1) {
      context.beginPath();
      context.strokeStyle = `rgba(73,63,44,${y % 10 === 0 ? majorAlpha : minorAlpha})`;
      context.lineWidth = y % 10 === 0 ? 1.25 : 0.5;
      context.moveTo(0, y * cell - viewportY);
      context.lineTo(width, y * cell - viewportY);
      context.stroke();
    }
  }
  const cursorX = cursorIndex.value % grid.value.width;
  const cursorY = Math.floor(cursorIndex.value / grid.value.width);
  if (cursorX >= startX && cursorX < endX && cursorY >= startY && cursorY < endY) {
    context.strokeStyle = "#cc9512";
    context.lineWidth = Math.max(2, cell * .12);
    context.strokeRect(cursorX * cell - viewportX + 1, cursorY * cell - viewportY + 1, Math.max(1, cell - 2), Math.max(1, cell - 2));
  }
}

function scheduleDraw(): void {
  if (drawFrame !== undefined) return;
  drawFrame = window.requestAnimationFrame(() => {
    drawFrame = undefined;
    draw();
  });
}

function luminance(hex: string): number {
  const value = Number.parseInt(hex.slice(1), 16);
  return ((value >> 16) & 255) * 0.299 + ((value >> 8) & 255) * 0.587 + (value & 255) * 0.114;
}

function cellAt(event: PointerEvent): number | null {
  const target = canvas.value;
  if (!target) return null;
  const bounds = target.getBoundingClientRect();
  const x = Math.floor((event.clientX - bounds.left + canvasViewport.x) / cellSize.value);
  const y = Math.floor((event.clientY - bounds.top + canvasViewport.y) / cellSize.value);
  if (x < 0 || y < 0 || x >= grid.value.width || y >= grid.value.height) return null;
  return y * grid.value.width + x;
}

function applyTool(event: PointerEvent, initial = false): void {
  const index = cellAt(event);
  if (index === null) return;
  const current = grid.value.cells[index];
  if (activeTool.value === "picker") {
    if (current) selectedCode.value = current;
    activeTool.value = "brush";
    return;
  }
  if (initial) checkpoint();
  if (activeTool.value === "fill") {
    grid.value = fillRegion(grid.value, index, selectedCode.value);
    markDirty();
    return;
  }
  const next = activeTool.value === "eraser" ? null : selectedCode.value;
  if (current === next) return;
  grid.value.cells[index] = next;
  triggerRef(grid);
  markDirty();
}

function applyToolAtIndex(index: number): void {
  if (index < 0 || index >= grid.value.cells.length) return;
  checkpoint();
  const current = grid.value.cells[index];
  if (activeTool.value === "picker") {
    if (current) selectedCode.value = current;
    activeTool.value = "brush";
    return;
  }
  if (activeTool.value === "fill") grid.value = fillRegion(grid.value, index, selectedCode.value);
  else {
    grid.value.cells[index] = activeTool.value === "eraser" ? null : selectedCode.value;
    triggerRef(grid);
  }
  markDirty();
}

function canvasKeydown(event: KeyboardEvent): void {
  const x = cursorIndex.value % grid.value.width;
  const y = Math.floor(cursorIndex.value / grid.value.width);
  if (event.key === "ArrowLeft") cursorIndex.value = y * grid.value.width + Math.max(0, x - 1);
  else if (event.key === "ArrowRight") cursorIndex.value = y * grid.value.width + Math.min(grid.value.width - 1, x + 1);
  else if (event.key === "ArrowUp") cursorIndex.value = Math.max(0, y - 1) * grid.value.width + x;
  else if (event.key === "ArrowDown") cursorIndex.value = Math.min(grid.value.height - 1, y + 1) * grid.value.width + x;
  else if (event.key === " " || event.key === "Enter") applyToolAtIndex(cursorIndex.value);
  else return;
  event.preventDefault();
  scheduleDraw();
}

function pointerDown(event: PointerEvent): void {
  isDrawing.value = true;
  canvas.value?.setPointerCapture(event.pointerId);
  applyTool(event, true);
}

function pointerMove(event: PointerEvent): void {
  if (!isDrawing.value || !["brush", "eraser"].includes(activeTool.value)) return;
  applyTool(event);
}

function pointerUp(): void {
  isDrawing.value = false;
}

function chooseFile(): void {
  fileInput.value?.click();
}

async function handleFile(event: Event): Promise<void> {
  const file = (event.target as HTMLInputElement).files?.[0];
  if (!file) return;
  if (!file.type.startsWith("image/")) {
    notify("请选择 JPG、PNG 或 WebP 图片");
    return;
  }
  try {
    await saveLocalImageDraft(file);
  } catch {
    notify("图片已载入，但本机保存失败；关闭页面后需要重新选择");
  }
  sourceFile.value = file;
  aiUploadIdempotencyKey.value = crypto.randomUUID();
  aiUploadConsentVersion.value = "";
  if (sourceUrl.value) URL.revokeObjectURL(sourceUrl.value);
  sourceUrl.value = URL.createObjectURL(file);
  const image = new Image();
  image.onload = async () => {
    sourceImage.value = image;
    if (page.value === "create") {
      await flushDraft();
      if (lastCloudSaveFailed && draftTargetId.value) { notify("当前作品尚未同步，暂不能开始另一份作品"); return; }
      draftTargetId.value = null;
    }
    projectName.value = file.name.replace(/\.[^.]+$/, "") || "未命名作品";
    if (page.value === "editor") void regenerate();
    else notify("图片已读取，可以继续裁剪和设置");
  };
  image.onerror = () => notify("图片读取失败，请换一张试试");
  image.src = sourceUrl.value;
}

async function navigate(next: Page | HubPage | "editor" | "build"): Promise<void> {
  if (next === "create" && page.value !== "create") {
    if (!creationIntentPrepared) {
      const defaults = creationDefaults("normal");
      prepareCreate({ mode: "normal", ...defaults });
    }
  }
  if (next !== "create") creationIntentPrepared = false;
  if (next === "build" && shared.state.status === "synced" && currentCloudProjectId.value) {
    await flushDraft();
    if (lastCloudSaveFailed || draftConflict.value) { notify("请先解决草稿同步冲突，再进入制作模式"); return; }
    try {
      await shared.commitActiveDraft();
      applySharedState({ forceProject: true });
    } catch (error) {
      notify(error instanceof Error ? error.message : "图纸版本提交失败");
      return;
    }
  }
  page.value = next as Page;
  const url = new URL(window.location.href);
  url.searchParams.set("view", page.value);
  window.history.pushState({ page: page.value }, "", url);
  document.title = `${pageNames[page.value]} · ${PRODUCT_NAME}`;
  if (page.value === "editor" || page.value === "build") showZoomHintOnce();
  nextTick(scheduleDraw);
}

async function finishCreate(options: CreateOptions): Promise<void> {
  createMode.value = options.mode;
  settings.size = options.size;
  settings.maxColors = options.maxColors;
  settings.transparentBackground = options.transparentBackground;
  settings.preset = options.size <= 192 ? "economy" : options.size <= 384 ? "balanced" : options.size <= 768 ? "detail" : "ultra";
  settings.crisp = options.mode !== "pixel";
  if (!sourceImage.value) {
    notify("请先上传一张图片");
    return;
  }
  await flushDraft();
  if (lastCloudSaveFailed && draftTargetId.value) { notify("当前作品尚未同步，暂不能创建新作品"); return; }
  draftTargetId.value = null;
  await regenerate(options);
  await flushDraft();
  if (shared.state.status === "synced") {
    if (!cloudProjectGridCompatible(grid.value)) {
      status.value = `本机已保存 · ${grid.value.width}×${grid.value.height} 超过云端 ${CLOUD_PROJECT_MAX_EDGE} 格单边上限`;
      notify(`专业大图已保存在本机；云端普通作品单边最多 ${CLOUD_PROJECT_MAX_EDGE} 格，本次未提交`);
      navigate("editor");
      return;
    }
    try {
      const paletteId = workspacePalette.value?.id ?? workspacePaletteId.value;
      if (!paletteId) throw new Error("新作品的色卡尚未加载");
      const created = await shared.createProject(projectName.value, grid.value, options.mode, paletteId);
      draftTargetId.value = created.id;
      setWorkspacePalette(created.paletteId);
      status.value = "已创建共享作品";
    } catch (error) {
      notify(error instanceof Error ? `${error.message}；已保留本机草稿` : "云端作品创建失败；已保留本机草稿");
    }
  }
  navigate("editor");
  notify("图纸已创建，可以开始精修");
}

async function createBlankCanvas(size: number): Promise<void> {
  await flushDraft();
  if (lastCloudSaveFailed && draftTargetId.value) { notify("当前作品尚未同步，请先保存后再新建画布"); return; }
  suppressAutosave = true;
  draftTargetId.value = null;
  grid.value = createBlankGrid(Math.max(18, Math.min(200, size)));
  projectName.value = "空白拼豆画布";
  createMode.value = "pixel";
  sourceImage.value = null;
  sourceFile.value = null;
  if (sourceUrl.value.startsWith("blob:")) URL.revokeObjectURL(sourceUrl.value);
  sourceUrl.value = "";
  settings.size = size;
  activeTool.value = "brush";
  suppressAutosave = false;
  dirty.value = true;
  await flushDraft();
  navigate("editor");
  notify("已新建空白画布，手动绘制和编辑免费");
}

function processedSource(options?: Pick<CreateOptions, "cropRatio" | "freeCropRatio" | "cropScale" | "cropOffsetX" | "cropOffsetY" | "rotation">): HTMLCanvasElement | HTMLImageElement {
  const image = sourceImage.value;
  if (!image || !options) return image!;
  const crop = calculateCropRectangle(image.naturalWidth, image.naturalHeight, options);
  const canvas = document.createElement("canvas");
  canvas.width = crop.width;
  canvas.height = crop.height;
  const context = canvas.getContext("2d");
  if (!context) return image;
  drawCropResult(context, image, image.naturalWidth, image.naturalHeight, crop, 0, 0, crop.width, crop.height);
  return canvas;
}

async function regenerate(options?: CreateOptions): Promise<void> {
  if (regenerating.value) {
    notify("图纸正在生成，请稍候");
    return;
  }
  if (!sourceImage.value) {
    notify("先上传一张图片，再调整生成参数");
    return;
  }
  const source = processedSource(options);
  const sourceWidth = source instanceof HTMLCanvasElement ? source.width : source.naturalWidth;
  const sourceHeight = source instanceof HTMLCanvasElement ? source.height : source.naturalHeight;
  const size = Math.max(24, Math.round(settings.size));
  const quality = qualityPresets[settings.preset as QualityPreset] ?? qualityPresets.balanced;
  const ratio = sourceWidth / sourceHeight;
  const estimatedCells = ratio >= 1 ? size * Math.max(8, Math.round(size / ratio)) : Math.max(8, Math.round(size * ratio)) * size;
  if (!options && estimatedCells > 500_000 && !window.confirm(`将生成约 ${estimatedCells.toLocaleString()} 个拼豆格，处理和保存会占用较多内存。是否继续？`)) return;
  const inventoryOnly = options?.inventoryOnly ?? false;
  const eligiblePalette = inventoryOnly ? beadPalette.value.filter((color) => color.stock > 0) : beadPalette.value;
  if (!eligiblePalette.length) {
    notify("豆仓中没有可用颜色，请先补充库存或关闭“仅使用豆仓已有颜色”");
    return;
  }
  regenerating.value = true;
  status.value = "正在根据当前参数重新生成图纸…";
  pixelRun?.abort();
  const run = new AbortController();
  pixelRun = run;
  try {
    const nextGrid = await pixelateImageAsync(source, sourceWidth, sourceHeight, {
      size,
      maxColors: settings.maxColors,
      brightness: settings.brightness,
      contrast: settings.contrast,
      transparentBackground: settings.transparentBackground,
      preserveHardEdges: (options?.mode ?? createMode.value) === "pixel",
      crisp: settings.crisp,
      detailEnhancement: quality.detailEnhancement,
      ditherStrength: quality.ditherStrength,
      palette: eligiblePalette,
    }, run.signal);
    if (pixelRun !== run || run.signal.aborted) return;
    const unchanged = grid.value.width === nextGrid.width
      && grid.value.height === nextGrid.height
      && grid.value.cells.length === nextGrid.cells.length
      && grid.value.cells.every((code, index) => code === nextGrid.cells[index]);
    checkpoint();
    grid.value = nextGrid;
    editorViewMode.value = "edit";
    showCodes.value = true;
    showGrid.value = true;
    zoom.value = Math.max(14, zoom.value);
    highlightedCode.value = null;
    markDirty();
    scheduleMaterialCount();
    scheduleDraw();
    const usedColors = new Set(nextGrid.cells.filter((code): code is string => Boolean(code))).size;
    status.value = unchanged
      ? "已重新计算 · 当前参数生成结果与现有图纸一致"
      : `已重新生成 ${nextGrid.width}×${nextGrid.height} · ${usedColors} 色`;
    notify(unchanged
      ? "已重新计算；当前参数生成结果与现有图纸一致"
      : `已生成 ${nextGrid.width} × ${nextGrid.height} 图纸，使用 ${usedColors} 色`);
  } catch (error) {
    if (run.signal.aborted) return;
    status.value = "重新生成失败 · 已保留原图纸";
    notify(error instanceof Error ? `重新生成失败：${error.message}` : "重新生成失败，已保留原图纸");
  } finally {
    if (pixelRun === run) {
      pixelRun = undefined;
      regenerating.value = false;
    }
  }
}

function applyAiFailure(outcome: { message: string; canRetry: boolean }): void {
  aiState.value = "error";
  aiFailureMessage.value = outcome.message;
  aiFailureCanRetry.value = outcome.canRetry;
  notify(outcome.message);
}

async function startAi(rawOptions: Record<string, unknown>): Promise<void> {
  const options = rawOptions as unknown as CreateOptions;
  const palette = workspacePalette.value;
  if (shared.state.status !== "synced" || !palette || !sourceFile.value || !sourceImage.value) {
    applyAiFailure({
      message: "AI 重绘需要共享账号、可用色卡和已上传图片",
      canRetry: false,
    });
    return;
  }
  createMode.value = options.mode;
  const requestedLongSide = Math.max(24, Math.round(options.size));
  const aiLongSide = compatibleAiLongSide(requestedLongSide);
  if (requestedLongSide !== aiLongSide) {
    notify(`远端 AI 单边最多 ${CLOUD_GENERATION_MAX_EDGE} 格，本次已明确调整为 ${aiLongSide} 格`);
  }
  aiState.value = "uploading";
  aiProgress.value = 5;
  aiJob.value = null;
  aiFailureMessage.value = "";
  aiFailureCanRetry.value = true;
  try {
    const consent = await shared.api.privacyConsent();
    if (aiUploadConsentVersion.value !== consent.consentVersion) {
      aiUploadIdempotencyKey.value = crypto.randomUUID();
      aiUploadConsentVersion.value = consent.consentVersion;
    }
    const { asset } = await shared.api.uploadAiSource(sourceFile.value, consent.consentVersion, aiUploadIdempotencyKey.value);
    aiProgress.value = 18;
    const longSide = aiLongSide;
    const crop = calculateCropRectangle(sourceImage.value.naturalWidth, sourceImage.value.naturalHeight, options);
    const ratio = crop.width / crop.height;
    const width = ratio >= 1 ? longSide : Math.max(8, Math.round(longSide * ratio));
    const height = ratio >= 1 ? Math.max(8, Math.round(longSide / ratio)) : longSide;
    const result = await shared.api.createGenerationJob({
      kind: options.mode,
      paletteId: palette.id,
      sourceAssetId: asset.id,
      width,
      height,
      options: {
        crop: { ratio: options.cropRatio === "原图" ? "original" : options.cropRatio === "自由" ? "free" : options.cropRatio, freeRatio: options.freeCropRatio / 100, scale: options.cropScale / 100, rotation: options.rotation, offsetX: options.cropOffsetX, offsetY: options.cropOffsetY, flipX: false, flipY: false },
        removeBackground: options.removeBackground,
        figureStyle: ({ "Q 版全身": "chibi-full", "Q 版半身": "chibi-half", "像素头像": "pixel-avatar" } as Record<string, string>)[options.figureStyle ?? ""] ?? "chibi-full",
        coupleLayout: ({ "同框": "together", "左右分屏": "split", "分别生成": "solo" } as Record<string, string>)[options.coupleLayout ?? ""] ?? "together",
        maxColors: options.maxColors,
        transparentBackground: options.transparentBackground,
        inventoryOnly: options.inventoryOnly,
      },
    });
    aiJob.value = result.job;
    aiState.value = "generating";
    await pollGeneration(result.job.id);
  } catch (error) {
    applyAiFailure(interpretGenerationHttpFailure(error));
  }
}

async function pollGeneration(jobId: string): Promise<void> {
  window.clearTimeout(generationPoll);
  try {
    const { job } = await shared.api.generationJob(jobId);
    aiJob.value = job;
    aiProgress.value = Math.max(18, job.progress);
    if (job.status === "completed") {
      aiState.value = "ready";
      aiProgress.value = 100;
      aiFailureMessage.value = "";
      aiFailureCanRetry.value = true;
      await shared.refreshCredits();
      credits.value = shared.state.credits;
      return;
    }
    if (["failed", "canceled"].includes(job.status)) {
      applyAiFailure(interpretGenerationJobFailure(job));
      await shared.refreshCredits();
      credits.value = shared.state.credits;
      return;
    }
    generationPoll = window.setTimeout(() => void pollGeneration(jobId), 1500);
  } catch (error) {
    applyAiFailure(interpretGenerationHttpFailure(error));
  }
}

async function acceptAi(variantOrdinal: number): Promise<void> {
  const job = aiJob.value;
  const variant = job?.variants.find((item) => item.variantOrdinal === variantOrdinal);
  if (!job || !variant) return;
  aiState.value = "accepting";
  try {
    const projects = variant.outputs.map((output, index) => ({
      outputSlot: output.outputSlot,
      projectName: variant.outputs.length > 1 ? `${projectName.value} · ${index + 1}` : projectName.value,
    }));
    const result = await shared.api.acceptGenerationVariant(job.id, variantOrdinal, projects);
    await shared.refresh();
    const createdId = result.variant.outputs[0]?.project.id;
    if (createdId) await shared.openProject(createdId);
    applySharedState({ forceProject: true });
    navigate("editor");
    aiState.value = "idle";
    notify("AI 方案已由服务端采用，作品与次数已同步");
  } catch (error) {
    applyAiFailure(interpretGenerationHttpFailure(error));
  }
}

async function exportPng(): Promise<void> {
  if (!await ensureLocalExportReady()) return;
  const targetLongEdge = 3840;
  const titleHeight = 118;
  const legendWidth = 300;
  const landscape = grid.value.width >= grid.value.height;
  const unit = Math.max(1, Math.floor(landscape
    ? (targetLongEdge - legendWidth - 56) / grid.value.width
    : (targetLongEdge - titleHeight - 28) / grid.value.height));
  const out = document.createElement("canvas");
  out.width = grid.value.width * unit + legendWidth;
  out.height = Math.max(grid.value.height * unit + titleHeight, 720);
  const context = out.getContext("2d");
  if (!context) return;
  context.fillStyle = "#fffdfa";
  context.fillRect(0, 0, out.width, out.height);
  context.fillStyle = "#20201e";
  context.font = "700 28px sans-serif";
  context.fillText(projectName.value, 28, 42);
  context.font = "15px sans-serif";
  context.fillStyle = "#77746d";
  context.fillText(`${canvasLabel.value} · ${materials.value.length} 色 · ${beadCount.value} 颗`, 28, 72);
  const top = titleHeight;
  for (let y = 0; y < grid.value.height; y += 1) {
    for (let x = 0; x < grid.value.width; x += 1) {
      const code = grid.value.cells[y * grid.value.width + x];
      const color = code ? paletteMap.value.get(code) : null;
      context.fillStyle = color?.hex ?? "#ffffff";
      context.fillRect(x * unit, top + y * unit, unit, unit);
      if (unit >= 2) {
        context.strokeStyle = "rgba(70,64,52,.18)";
        context.strokeRect(x * unit, top + y * unit, unit, unit);
      }
      if (code && unit >= 10) {
        context.fillStyle = luminance(color?.hex ?? "#fff") > 145 ? "#222" : "#fff";
        context.font = `700 ${Math.max(7, Math.floor(unit * .34))}px sans-serif`;
        context.textAlign = "center";
        context.textBaseline = "middle";
        context.fillText(code, x * unit + unit / 2, top + y * unit + unit / 2);
      }
    }
  }
  context.textAlign = "left";
  context.textBaseline = "alphabetic";
  materials.value.forEach((item, index) => {
    const x = grid.value.width * unit + 28;
    const y = 46 + index * 38;
    context.fillStyle = item.hex;
    context.fillRect(x, y, 24, 24);
    context.strokeStyle = "#dedbd3";
    context.strokeRect(x, y, 24, 24);
    context.fillStyle = "#262522";
    context.font = "700 13px sans-serif";
    context.fillText(item.code, x + 36, y + 10);
    context.font = "12px sans-serif";
    context.fillStyle = "#77746d";
    context.fillText(`${item.quantity} 颗`, x + 36, y + 26);
  });
  const blob = await new Promise<Blob | null>((resolve) => out.toBlob(resolve, "image/png"));
  if (!blob) throw new Error("4K PNG 生成失败");
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.download = `${projectName.value || "拼豆图纸"}-4K.png`;
  link.href = url;
  link.click();
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
  notify(`4K PNG 已导出 · ${out.width}×${out.height}`);
}

async function exportPurchaseCsv(): Promise<void> {
  if (!await ensureLocalExportReady()) return;
  const rows = [
    ["色号", "颜色名称", "需要", "库存", "缺口", "位置"],
    ...materials.value.map((item) => [
      item.code,
      item.name,
      String(item.quantity),
      String(item.stock),
      String(Math.max(0, item.quantity - item.stock)),
      item.location ?? "未设置",
    ]),
  ];
  const csv = `\uFEFF${rows.map((row) => row.map((value) => `"${value.replace(/"/g, '""')}"`).join(",")).join("\r\n")}`;
  const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" }));
  const link = document.createElement("a");
  link.href = url;
  link.download = `${projectName.value || "拼豆作品"}-采购单.csv`;
  link.click();
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
  notify("采购单 CSV 已导出");
}

async function createCloudExport(format: "pdf" | "png"): Promise<void> {
  try {
    await flushDraft();
    if (lastCloudSaveFailed || draftConflict.value) throw new Error("当前草稿尚未安全同步，请先解决同步问题再导出");
    const project = await shared.commitActiveDraft();
    if (!project) throw new Error("请先打开一个共享作品");
    await shared.api.createExport(project, format);
    await shared.refreshExports();
    notify(`${format.toUpperCase()} 导出任务已创建，内容已锁定到版本 ${project.currentRevision}`);
    startExportPolling();
  } catch (error) {
    notify(error instanceof Error ? error.message : "导出任务创建失败");
  }
}

async function batchExport(projectIds: string[]): Promise<void> {
  let created = 0;
  for (const projectId of projectIds) {
    try {
      if (shared.state.activeProject?.id === projectId) {
        await flushDraft();
        if (lastCloudSaveFailed || draftConflict.value) throw new Error("当前草稿尚未安全同步，请先解决同步问题再批量导出");
      }
      let { project } = await shared.api.project(projectId);
      const draftResult = await shared.api.draft(projectId) as { draft: { draftRevision: number } | null };
      if (draftResult.draft) {
        const committed = await shared.api.commitDraft(project, draftResult.draft.draftRevision) as { project: typeof project };
        project = committed.project;
      }
      await shared.api.createExport(project, "pdf");
      created += 1;
    } catch (error) {
      notify(error instanceof Error ? error.message : `作品 ${projectId.slice(0, 8)} 导出失败`);
    }
  }
  await shared.refreshExports();
  startExportPolling();
  if (created) notify(`已创建 ${created} 个真实分页 PDF 任务`);
}

function startExportPolling(attempt = 0): void {
  window.clearTimeout(exportPoll);
  if (!shared.state.exports.some((job) => ["queued", "running", "retry_wait"].includes(job.status))) return;
  exportPoll = window.setTimeout(async () => {
    try {
      await shared.refreshExports();
      startExportPolling(attempt + 1);
    } catch {
      startExportPolling(Math.min(attempt + 1, 5));
    }
  }, Math.min(10_000, 1_500 * (attempt + 1)));
}

async function retryExport(exportId: string): Promise<void> {
  const failed = shared.state.exports.find((job) => job.id === exportId);
  if (!failed) return;
  try {
    const { project } = await shared.api.project(failed.projectId);
    await shared.api.createExport(project, failed.format, failed.projectRevision);
    await shared.refreshExports();
    startExportPolling();
    notify(`已重新创建 ${failed.format.toUpperCase()} 导出任务，旧任务保留用于审计`);
  } catch (error) {
    notify(error instanceof Error ? error.message : "重新创建导出失败");
  }
}

async function cancelExport(exportId: string): Promise<void> {
  const job = shared.state.exports.find((item) => item.id === exportId);
  const gate = {
    synced: shared.state.status === "synced",
    busy: Boolean(exportCancelBusyId.value),
    status: job?.status ?? "",
  };
  if (!job) {
    notify("导出任务不存在或列表已变化，请刷新后再试");
    return;
  }
  if (!canStartWebExportCancel(gate)) {
    if (!gate.synced) {
      notify(webExportCancelOfflineMessage());
      return;
    }
    if (gate.busy) {
      notify(webExportCancelBusyMessage());
      return;
    }
    notify("仅等待中、处理中或等待重试的导出可以取消");
    return;
  }
  if (!window.confirm(webExportCancelConfirmMessage(job.fileName))) return;
  exportCancelBusyId.value = exportId;
  const prior = shared.state.exports.slice();
  try {
    const result = await shared.api.cancelExport(exportId);
    await shared.refreshExports();
    if (!shared.state.exports.some((item) => item.id === exportId)) {
      shared.state.exports = [result.export, ...prior.filter((item) => item.id !== exportId)];
    }
    notify(webExportCancelSuccessMessage());
  } catch (error) {
    const outcome = interpretWebExportCancelFailure(error);
    if (shouldRefreshExportsAfterCancelFailure(outcome)) {
      try {
        await shared.refreshExports();
      } catch {
        shared.state.exports = prior;
      }
    } else {
      shared.state.exports = prior;
    }
    notify(outcome.message);
  } finally {
    exportCancelBusyId.value = null;
  }
}

async function downloadExport(exportId: string): Promise<void> {
  try {
    const blob = await shared.api.downloadExport(exportId);
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = shared.state.exports.find((job) => job.id === exportId)?.artifact?.fileName ?? "拼豆图纸";
    link.click();
    window.setTimeout(() => URL.revokeObjectURL(url), 1000);
  } catch (error) {
    notify(error instanceof Error ? error.message : "导出文件下载失败");
  }
}

async function adjustInventory(colorCode: string, delta: number, done?: InventoryCalibrateDone): Promise<void> {
  try {
    await shared.adjustInventory(colorCode, delta, workspacePalette.value?.id);
    const message = `${colorCode} 库存已同步，流水已刷新`;
    done?.("ok", message, null);
    if (!done) notify(message);
  } catch (error) {
    if (isInventoryCalibrateRefreshError(error)) {
      done?.("refresh", error.message, error.originFingerprint);
      if (!done) notify(error.message);
      return;
    }
    const message = error instanceof Error ? error.message : "库存同步失败";
    done?.("error", message, null);
    if (!done) notify(message);
  }
}

async function updateInventoryLocation(colorCode: string, location: string, done?: InventoryCalibrateDone): Promise<void> {
  try {
    await shared.updateInventoryLocation(colorCode, location, workspacePalette.value?.id);
    const message = `${colorCode} 仓位已保存，流水已刷新`;
    done?.("ok", message, null);
    if (!done) notify(message);
  } catch (error) {
    if (isInventoryCalibrateRefreshError(error)) {
      done?.("refresh", error.message, error.originFingerprint);
      if (!done) notify(error.message);
      return;
    }
    const message = error instanceof Error ? error.message : "仓位保存失败";
    done?.("error", message, null);
    if (!done) notify(message);
  }
}

async function calibrateInventory(
  preview: InventoryCalibratePreview,
  done: InventoryCalibrateDone,
): Promise<void> {
  try {
    await shared.calibrateInventoryBatch(preview);
    done("ok", "库存已按预览校准，流水已刷新", null);
  } catch (error) {
    if (isInventoryCalibrateRefreshError(error)) {
      done("refresh", error.message, error.originFingerprint);
      return;
    }
    done("error", error instanceof Error ? error.message : "库存校准失败", null);
  }
}

async function refreshInventorySnapshot(
  done: InventoryCalibrateRefreshDone,
  originFingerprint: string | null,
): Promise<void> {
  try {
    await shared.refreshInventorySnapshot(originFingerprint);
    done(true, "库存和流水已刷新");
  } catch (error) {
    done(false, error instanceof Error ? error.message : "库存流水刷新失败");
  }
}

function selectMaterial(code: string): void {
  selectedCode.value = code;
  highlightedCode.value = highlightedCode.value === code ? null : code;
}

watch([grid, zoom, showGrid, showCodes, effectiveShowGrid, highlightedCode, cursorIndex, page, beadPalette, editorViewMode], scheduleDraw, { deep: true });
watch([grid, beadPalette], scheduleMaterialCount, { deep: true, immediate: true });
watch(zoomMax, (maximum) => {
  if (zoom.value > maximum) zoom.value = maximum;
});
watch(projectName, markDirty);

onMounted(() => {
  window.addEventListener("resize", scheduleDraw);
  const localDraftKey = localStorage.getItem("pindou-web-draft:local") !== null ? "pindou-web-draft:local" : "pindou-web-draft";
  const saved = localStorage.getItem(localDraftKey);
  if (saved) {
    try {
      const parsed = JSON.parse(saved) as { name?: string; grid?: PatternGrid; paletteContractVersion?: number; paletteId?: string | null; paletteVersion?: number | null };
      const savedGrid = parsed.grid;
      if (savedGrid && savedGrid.cells.length === savedGrid.width * savedGrid.height) {
        restoreWorkspacePalette(parsed);
        grid.value = prepareLegacyDraft(localDraftKey, parsed.name || projectName.value, savedGrid, parsed.paletteContractVersion === 1);
        projectName.value = parsed.name || projectName.value;
        hasLocalDraft.value = true;
      }
    } catch {
      // Ignore an invalid local draft and keep the built-in sample.
    }
  }
  if (page.value === "create") {
    const defaults = creationDefaults("normal");
    prepareCreate({ mode: "normal", ...defaults });
  }
  void loadLocalImageDraft().then((file) => {
    if (!file || sourceFile.value) return;
    sourceFile.value = file;
    sourceUrl.value = URL.createObjectURL(file);
    const image = new Image();
    image.onload = () => { sourceImage.value = image; };
    image.onerror = () => notify("本机保存的图片无法读取，请重新选择");
    image.src = sourceUrl.value;
    if (page.value === "create") projectName.value = file.name.replace(/\.[^.]+$/, "") || "未命名作品";
  }).catch(() => undefined);
  window.addEventListener("popstate", () => {
    const next = new URL(window.location.href).searchParams.get("view") as Page | null;
    if (next && validPages.includes(next)) page.value = next;
  });
  document.title = `${pageNames[page.value]} · ${PRODUCT_NAME}`;
  if (page.value === "editor" || page.value === "build") showZoomHintOnce();
  scheduleDraw();
  void shared.restore().then((restored) => {
    if (shared.state.paletteStatus === "ready") applySharedState();
    if (restored) startExportPolling();
  });
});

onBeforeUnmount(() => {
  window.removeEventListener("resize", scheduleDraw);
  window.clearTimeout(materialTimer);
  materialWorker?.terminate();
  pixelRun?.abort();
  window.clearTimeout(saveTimer);
  window.clearTimeout(generationPoll);
  window.clearTimeout(exportPoll);
  window.clearTimeout(loginPoll);
  webLoginGeneration = nextWebLoginGeneration(webLoginGeneration);
  webLoginBusy.value = false;
  webLoginPhase.value = "idle";
  webLoginCode.value = "";
  window.clearTimeout(zoomHintTimer);
  if (drawFrame !== undefined) window.cancelAnimationFrame(drawFrame);
  if (sourceUrl.value) URL.revokeObjectURL(sourceUrl.value);
});
</script>

