      :inventory-account-id="shared.state.userId || shared.state.userName"
      :invite-code="inviteCode"
      :invite-bound-code="inviteBoundCode"
      :invite-busy="inviteBusy"
      :invite-failed="inviteFailed"
      :invite-message="inviteMessage"
      :pending-invite-code="pendingInviteCode"
      @navigate="navigate"
      @choose-file="chooseFile"
      @prepare-create="prepareCreate"
      @finish-create="finishCreate"
      @start-ai="startAi"
      @accept-ai="acceptAi"
      @open-project="openProject"
      @request-login="startWebLogin"
      @create-blank="createBlankCanvas"
      @open-gallery-work="openGalleryWork"
      @rename-project="renameProject"
      @copy-project="copyProject"
      @delete-project="deleteProject"
      @import-palette="choosePaletteFile"
      @change-palette="changePaletteById"
      @retry-palettes="retryPaletteCatalog"
      @batch-export="batchExport"
      @create-export="createCloudExport"
      @download-export="downloadExport"
      @retry-export="retryExport"
      @cancel-export="cancelExport"
      @load-invite="loadInvite"
      @accept-invite="acceptInvite"
      @update-pending-invite-code="pendingInviteCode = $event"
      @adjust-inventory="adjustInventory"
      @update-inventory-location="updateInventoryLocation"
      @calibrate-inventory="calibrateInventory"
      @refresh-inventory-snapshot="refreshInventorySnapshot"
      @export-png="exportPng"
      @notify="notify"
    />

    <BuildMode
      v-else-if="page === 'build'"
      :project-name="projectName"
      :project-id="currentCloudProjectId ?? 'local'"
      :project-revision="currentCloudProjectId ? (shared.state.activeProject?.currentRevision ?? 0) : 0"
      :sync-status="currentCloudProjectId ? shared.state.status : 'offline'"
      :grid="grid"
      :palette="beadPalette"
      :materials="materials"
      @back="navigate('editor')"
      @notify="notify"
    />

    <Transition name="zoom-hint">
      <div v-if="zoomHintVisible" class="zoom-hint" role="status"><AppIcon name="content" :size="18"/><span><b>画布快捷缩放</b><small>按住 Ctrl 并滚动鼠标滚轮，可围绕指针放大或缩小</small></span><button aria-label="关闭快捷缩放提示" @click="dismissZoomHint">×</button></div>
    </Transition>

    <div v-if="draftConflict" class="draft-conflict-banner" role="alert"><span><b>云端草稿已在另一设备更新</b><small>请选择采用云端内容，或用本机副本明确覆盖。</small></span><button class="outline-button" @click="useCloudDraft">采用云端</button><button class="primary-button" @click="keepLocalDraft">保留本机</button></div>
    <div v-if="legacyMigrationReview" class="draft-conflict-banner" role="alert"><span><b>无色卡契约的旧草稿需明确确认</b><small>迁移 {{ LEGACY_GRID_MIGRATION_VERSION }}：{{ legacyMigrationReview.plan.entries.map(item => `${item.oldCode}→${item.newCode}`).join('，') || '空图纸' }}。原稿和审计已另存；验证全部色号属于 291 色卡前不会提交新 revision。</small></span><button class="outline-button" @click="keepCurrentPaletteCodes">这是 291 色卡色号</button><button class="primary-button" @click="confirmLegacyMigration">确认替换并迁移</button></div>

    <aside v-if="page === 'editor'" class="settings-panel" :class="{ 'mobile-open': mobilePanel === 'settings' }">
      <section class="panel-section source-section">
        <div class="section-heading">
          <div><span class="eyebrow">SOURCE</span><h2>原图与参数</h2></div>
          <div class="panel-heading-actions"><button class="icon-button" title="重新上传" aria-label="重新上传图片" @click="chooseFile">↥</button><button class="icon-button mobile-only" aria-label="关闭参数面板" @click="mobilePanel = null">×</button></div>
        </div>
        <button class="source-card" @click="chooseFile">
          <img v-if="sourceUrl" :src="sourceUrl" alt="已上传的原图" />
          <div v-else class="sample-source">
            <span class="cat-face">●ᴥ●</span>
          </div>
          <span class="source-overlay">更换图片</span>
        </button>
        <p class="source-meta">JPG / PNG / WebP · 图片只在本机处理</p>
      </section>

      <section class="panel-section">
        <div class="section-heading compact"><h3>生成策略</h3><span class="tag">推荐</span></div>
        <div class="segmented" role="radiogroup" aria-label="生成策略">
          <button :class="{ active: settings.preset === 'economy' }" :aria-checked="settings.preset === 'economy'" role="radio" @click="applyQualityPreset('economy')"><b>快速模式</b><small>48 / 72 色</small></button>
          <button :class="{ active: settings.preset === 'balanced' }" :aria-checked="settings.preset === 'balanced'" role="radio" @click="applyQualityPreset('balanced')"><b>标准照片</b><small>默认 221 色</small></button>
          <button :class="{ active: settings.preset === 'detail' }" :aria-checked="settings.preset === 'detail'" role="radio" @click="applyQualityPreset('detail')"><b>高精人物</b><small>291 色</small></button>
          <button :class="{ active: settings.preset === 'ultra' }" :aria-checked="settings.preset === 'ultra'" role="radio" @click="applyQualityPreset('ultra')"><b>巨幅人物</b><small>291 色</small></button>
        </div>

        <label class="control-row">
          <span><b>最多用色</b><small>颜色越少，备料越轻松</small></span>
          <output>{{ settings.maxColors }} 色</output>
        </label>
        <input v-model.number="settings.maxColors" class="range" type="range" min="5" :max="workspacePalette?.colors.length ?? 32" />

        <label class="control-row">
          <span><b>网格尺寸</b><small>长边格数，自定义不设产品上限</small></span>
          <output>{{ settings.size }}</output>
        </label>
        <input v-model.number="settings.size" class="size-number-input" type="number" min="24" step="8" inputmode="numeric" />

        <label class="select-label">品牌色卡
          <select :value="workspacePalette?.id ?? workspacePaletteId ?? ''" :disabled="!shared.state.palettes.length || Boolean(currentCloudProjectId && shared.state.status !== 'synced')" :title="paletteVerified ? '色卡数据已通过应用校验' : '当前色卡尚未通过应用数据校验'" @change="changePalette"><option v-if="!workspacePalette" value="" disabled>请选择已加载色卡</option><optgroup label="快速模式"><option v-for="item in quickPalettes" :key="item.id" :value="item.id">{{ paletteDisplayName(item) }}</option></optgroup><optgroup label="标准照片模式"><option v-for="item in photoPalettes" :key="item.id" :value="item.id">{{ paletteDisplayName(item) }}</option></optgroup><optgroup label="高精度人物模式"><option v-for="item in portraitPalettes" :key="item.id" :value="item.id">{{ paletteDisplayName(item) }}</option></optgroup><optgroup v-if="customPalettes.length" label="自定义色卡"><option v-for="item in customPalettes" :key="item.id" :value="item.id">{{ paletteDisplayName(item) }}</option></optgroup></select>
        </label>

        <div class="toggle-row">
          <span><b>透明背景</b><small>保留原图透明区域</small></span>
          <button class="switch" aria-label="切换透明背景" :class="{ on: settings.transparentBackground }" role="switch" :aria-checked="settings.transparentBackground" @click="settings.transparentBackground = !settings.transparentBackground"><i></i></button>
        </div>
        <div class="toggle-row">
          <span><b>清晰优化</b><small>强化边缘与关键细节</small></span>
          <button class="switch" aria-label="切换清晰优化" :class="{ on: settings.crisp }" role="switch" :aria-checked="settings.crisp" @click="settings.crisp = !settings.crisp"><i></i></button>
        </div>
        <button class="generate-button" :class="{ 'is-loading': regenerating }" :disabled="!sourceImage || regenerating" :aria-busy="regenerating" @click="regenerate()">
          <span>✦</span> {{ regenerating ? "正在生成图纸…" : "重新生成图纸" }}
        </button>
      </section>
    </aside>

    <main v-if="page === 'editor'" class="workspace">
      <div class="workspace-toolbar">
        <div class="toolset" aria-label="编辑工具">
          <button :class="{ active: activeTool === 'brush' }" title="画笔 B" aria-label="画笔工具" @click="activeTool = 'brush'"><AppIcon name="brush" :size="17"/></button>
          <button :class="{ active: activeTool === 'eraser' }" title="橡皮 E" aria-label="橡皮工具" @click="activeTool = 'eraser'"><AppIcon name="eraser" :size="17"/></button>
          <button :class="{ active: activeTool === 'fill' }" title="填充 G" aria-label="填充工具" @click="activeTool = 'fill'"><AppIcon name="fill" :size="17"/></button>
          <button :class="{ active: activeTool === 'picker' }" title="吸色 I" aria-label="吸色工具" @click="activeTool = 'picker'"><AppIcon name="picker" :size="17"/></button>
          <span class="divider"></span>
          <button :disabled="history.length === 0" title="撤销" aria-label="撤销" @click="undo"><AppIcon name="undo" :size="17"/></button>
          <button :disabled="future.length === 0" title="重做" aria-label="重做" @click="redo"><AppIcon name="redo" :size="17"/></button>
        </div>
        <div class="editor-view-switch" aria-label="画布显示模式">
          <button :class="{ active: editorViewMode === 'preview' }" @click="setEditorViewMode('preview')">高清预览</button>
          <button :class="{ active: editorViewMode === 'edit' }" @click="setEditorViewMode('edit')">色号编辑</button>
        </div>
        <div class="view-options">
          <label v-if="editorViewMode === 'edit'"><input v-model="showGrid" type="checkbox" /> 网格</label>
          <label v-if="editorViewMode === 'edit'"><input v-model="showCodes" type="checkbox" /> 色号</label>
          <span class="zoom-gesture-hint">Ctrl + 滚轮缩放</span>
          <span class="divider"></span>
          <button aria-label="缩小当前视图" @click="changeEditorZoom(-1)"><AppIcon name="minus" :size="16"/></button>
          <output>{{ displayedZoomPercent }}%</output>
          <button aria-label="放大当前视图" @click="changeEditorZoom(1)"><AppIcon name="plus" :size="16"/></button>
          <button class="mobile-panel-trigger" @click="mobilePanel = 'settings'">参数</button>
          <button class="mobile-panel-trigger" @click="mobilePanel = 'materials'">材料</button>
        </div>
      </div>

      <div ref="canvasScroller" class="canvas-shell" :class="{ 'preview-mode': editorViewMode === 'preview' }" @wheel="editorWheel" @scroll="scheduleDraw">
        <div class="canvas-info">
          <span><i></i> {{ canvasLabel }}</span>
          <span>{{ materials.length }} 色</span>
          <span>{{ beadCount.toLocaleString() }} 颗</span>
        </div>
        <figure v-if="editorViewMode === 'preview' && sourceUrl" ref="previewStage" class="hd-preview-stage" :style="previewStageStyle"><img :src="sourceUrl" :alt="`${projectName}高清原图`" /><figcaption><b>4K 高清原图</b><span>切换“色号编辑”可修改 512×288 图纸</span></figcaption></figure>
        <div v-else ref="canvasStage" class="canvas-stage" :style="canvasSurfaceStyle">
          <canvas
            ref="canvas"
            :class="`tool-${activeTool}`"
            tabindex="0"
            role="grid"
            aria-label="拼豆图纸编辑画布"
            :aria-rowcount="grid.height"
            :aria-colcount="grid.width"
            :aria-description="`方向键移动当前格，空格或回车使用${activeTool === 'brush' ? '画笔' : activeTool === 'eraser' ? '橡皮' : activeTool === 'fill' ? '填充' : '吸色'}工具`"
            @keydown="canvasKeydown"
            @pointerdown="pointerDown"
            @pointermove="pointerMove"
            @pointerup="pointerUp"
            @pointercancel="pointerUp"
            @pointerleave="pointerUp"
          ></canvas>
        </div>
      </div>

      <div class="palette-dock">
        <div class="palette-title">
          <span>豆仓选色 · {{ beadPalette.length }} 色</span>
          <strong>{{ selectedCode }}</strong>
          <small>{{ paletteMap.get(selectedCode)?.name }} · 库存 {{ paletteMap.get(selectedCode)?.stock ?? 0 }} 颗</small>
        </div>
        <label class="palette-search">
          <span aria-hidden="true">⌕</span>
          <input v-model="paletteQuery" type="search" placeholder="搜索色号、名称或仓位" aria-label="搜索豆仓色号" />
        </label>
        <div class="swatches">
          <button
            v-for="color in filteredBeadPalette"
            :key="color.code"
            :class="{ active: selectedCode === color.code }"
            :title="`${color.code} · ${color.name} · 库存 ${color.stock} 颗${color.location ? ` · ${color.location}` : ''}`"
            @click="selectedCode = color.code"
          >
            <i :style="{ background: color.hex }"></i><span>{{ color.code }}</span><em>{{ color.stock }}</em>
          </button>
          <p v-if="!filteredBeadPalette.length" class="palette-empty">未找到匹配的色号</p>
        </div>
      </div>
    </main>

    <aside v-if="page === 'editor'" class="materials-panel" :class="{ 'mobile-open': mobilePanel === 'materials' }">
      <div class="materials-head">
        <div><span class="eyebrow">MATERIALS</span><h2>材料清单</h2></div>
        <div class="panel-heading-actions"><button class="icon-button" title="更多选项" aria-label="材料清单更多选项">•••</button><button class="icon-button mobile-only" aria-label="关闭材料面板" @click="mobilePanel = null">×</button></div>
      </div>
      <div class="summary-card">
        <div><small>总豆数</small><strong>{{ beadCount.toLocaleString() }}</strong><span>颗</span></div>
        <div><small>成品尺寸</small><strong>{{ physicalSize.width }} × {{ physicalSize.height }}</strong><span>cm</span></div>
        <div><small>使用颜色</small><strong>{{ materials.length }}</strong><span>色</span></div>
      </div>
      <div v-if="shortageCount" class="inventory-alert"><span>!</span><p><b>{{ shortageCount }} 个色号库存不足</b><small>清单已按缺口优先排序</small></p></div>
      <div class="material-list-head"><span>色号与数量</span><button @click="highlightedCode = null">清除高亮</button></div>
      <div class="material-list">
        <button
          v-for="(item, index) in materials"
          :key="item.code"
          :class="{ active: highlightedCode === item.code, shortage: item.quantity > item.stock }"
          @click="selectMaterial(item.code)"
        >
          <span class="rank">{{ index + 1 }}</span>
          <i :style="{ background: item.hex }"></i>
          <span class="material-name"><b>{{ item.code }}</b><small>{{ item.name }} · 库存 {{ item.stock }}</small></span>
          <strong>{{ item.quantity }}<small> 颗</small></strong>
        </button>
      </div>
      <div class="panel-footer">
        <button class="outline-button" @click="navigate('inventory')">打开豆仓</button>
        <button class="dark-button" @click="exportPurchaseCsv">导出采购单</button>
      </div>
    </aside>

    <button v-if="page === 'editor' && mobilePanel" class="panel-scrim" aria-label="关闭侧面板" @click="mobilePanel = null"></button>

    <div v-if="webAccessLocked" class="web-access-gate" role="dialog" aria-modal="true" aria-labelledby="web-access-title" @click="notify('需先使用微信小程序登录')">
      <section class="web-access-dialog" @click.stop>
        <img class="login-brand-mark" src="/brand-mark.png" alt="" width="72" height="72" />
        <span class="eyebrow">LOGIN REQUIRED</span>
        <h2 id="web-access-title">需先使用微信小程序登录</h2>
        <p>Web 端的作品、进度、豆仓、次数和导出功能，需要先与已登录的微信小程序配对。</p>
        <button class="primary-button" :disabled="webLoginBusy" @click="startWebLogin">{{ webLoginBusy ? '正在获取配对码…' : '使用微信小程序连接' }}</button>
      </section>
    </div>

    <div v-if="webLoginBusy || webLoginCode || webLoginPhase === 'creating' || webLoginPhase === 'waiting'" class="web-login-overlay" role="dialog" aria-modal="true" aria-labelledby="web-login-title">
      <section class="web-login-dialog">
        <img class="login-brand-mark" src="/brand-mark.png" alt="" width="72" height="72" />
        <span class="eyebrow">WECHAT PAIRING</span>
        <h2 id="web-login-title">用微信小程序连接账号</h2>
        <p v-if="webLoginPhase === 'creating' || !webLoginCode">{{ webLoginCreatingMessage() }}</p>
        <template v-else>
          <p>在已登录的豆格绘册小程序进入“我的 → 连接 Web”，输入下方一次性配对码。</p>
          <strong>{{ webLoginCode }}</strong>
          <small>有效期至 {{ new Date(webLoginExpiresAt).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }) }} · 正在等待确认</small>
        </template>
        <button class="outline-button" @click="cancelWebLogin()">取消</button>
      </section>
    </div>

    <Transition name="toast"><div v-if="toast" class="toast" role="status" aria-live="polite">✓ {{ toast }}</div></Transition>
  </div>
</template>
