<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from "vue";

import type { ApiBuildProgress, ApiCompletionPhoto } from "../api";
import {
  canManageCompletionPhotos,
  canRetryCompletionPhotoAction,
  completionPhotoListEmptyMessage,
  completionPhotoRetryLabel,
  completionPhotoUploadFingerprint,
  completionPhotoUploadSuccessMessage,
  interpretCompletionPhotoFailure,
  type CompletionPhotoRetryKind,
} from "../completion-photos";
import {
  canConfirmInventoryConsume,
  canRetryInventoryConsumeRefresh,
  inventoryConsumeAccountSwitchRefreshMessage,
  inventoryConsumeAfterPostRefreshOutcome,
  type InventoryConsumePhase,
} from "../inventory-consume";
import type { PatternGrid } from "../pixel-engine";
import type { BeadColor } from "../palette";
import { useSharedWorkspace } from "../shared-workspace";
import AppIcon from "./AppIcon.vue";

const props = defineProps<{
  projectName: string;
  projectId: string;
  projectRevision: number;
  syncStatus: "offline" | "connecting" | "synced" | "error";
  grid: PatternGrid;
  palette: BeadColor[];
  materials: Array<BeadColor & { quantity: number }>;
}>();

const emit = defineEmits<{ back: []; notify: [message: string] }>();
const canvas = ref<HTMLCanvasElement | null>(null);
const canvasScroller = ref<HTMLElement | null>(null);
const mode = ref<"color" | "region" | "row">("color");
const activeColor = ref(props.materials[0]?.code ?? props.palette[0]?.code ?? "M16");
const colorQuery = ref("");
const activeSection = ref(0);
const zoom = ref(13);
const completed = ref(new Set<number>());
const undoStack = ref<Array<Set<number>>>([]);
const progressRevision = ref(0);
const localDirty = ref(false);
const syncConflict = ref(false);
const remoteSnapshot = ref<ApiBuildProgress | null>(null);
const consumePhase = ref<InventoryConsumePhase>("idle");
const consumeMessage = ref("");
const consumeBusy = ref(false);
const consumeOriginFingerprint = ref<string | null>(null);
const photoBusy = ref(false);
const photoMessage = ref("");
const photoRetryable = ref(false);
const photoRetryKind = ref<CompletionPhotoRetryKind | null>(null);
const photos = ref<ApiCompletionPhoto[]>([]);
const photoPreviewUrls = ref<Record<string, string>>({});
const photoFileInput = ref<HTMLInputElement | null>(null);
const photoIdempotencyKey = ref("");
const photoFileFingerprint = ref("");
const pendingPhotoFile = ref<File | null>(null);
let persistTimer: number | undefined;
const shared = useSharedWorkspace();
const localKey = computed(() => `pindou-web-build-progress:${props.projectId}:${props.projectRevision}`);
const canConsumeInventory = computed(() => canConfirmInventoryConsume({
  synced: props.syncStatus === "synced",
  cloudProject: props.projectId !== "local" && props.projectRevision >= 1,
  buildComplete: progress.value === 100,
  busy: consumeBusy.value,
  phase: consumePhase.value,
}));
const canRefreshConsumeInventory = computed(() => canRetryInventoryConsumeRefresh({
  synced: props.syncStatus === "synced",
  busy: consumeBusy.value,
  phase: consumePhase.value,
}));
const canUseCompletionPhotos = computed(() => canManageCompletionPhotos({
  authenticated: Boolean(shared.api.getToken()),
  synced: props.syncStatus === "synced",
  cloudProject: props.projectId !== "local" && props.projectRevision >= 1,
  buildComplete: progress.value === 100,
  busy: photoBusy.value,
}));
const canRetryCompletionPhoto = computed(() => canRetryCompletionPhotoAction({
  busy: photoBusy.value,
  retryable: photoRetryable.value,
}));
const completionPhotoRetryButtonLabel = computed(() => completionPhotoRetryLabel(photoRetryKind.value));

const paletteMap = computed(() => new Map(props.palette.map((color) => [color.code, color])));
const cellSize = computed(() => Math.max(3, Math.min(zoom.value, 3072 / Math.max(props.grid.width, props.grid.height))));
const zoomMax = computed(() => Math.max(7, Math.floor(3072 / Math.max(props.grid.width, props.grid.height))));
const beadIndices = computed(() => props.grid.cells.map((code, index) => code ? index : -1).filter((index) => index >= 0));
const doneCount = computed(() => [...completed.value].filter((index) => props.grid.cells[index]).length);
const progress = computed(() => beadIndices.value.length ? Math.round(doneCount.value / beadIndices.value.length * 100) : 0);
const regionNames = ["左上区", "右上区", "左下区", "右下区"];

function matches(index: number): boolean {
  const code = props.grid.cells[index];
  if (!code) return false;
  const x = index % props.grid.width;
  const y = Math.floor(index / props.grid.width);
  if (mode.value === "color") return code === activeColor.value;
  if (mode.value === "row") return y === activeSection.value;
  const region = (y >= props.grid.height / 2 ? 2 : 0) + (x >= props.grid.width / 2 ? 1 : 0);
  return region === activeSection.value;
}

const targetIndices = computed(() => props.grid.cells.map((_, index) => matches(index) ? index : -1).filter((index) => index >= 0));
const targetDone = computed(() => targetIndices.value.filter((index) => completed.value.has(index)).length);
const targetTitle = computed(() => mode.value === "color" ? `${activeColor.value} · ${paletteMap.value.get(activeColor.value)?.name ?? ""}` : mode.value === "region" ? regionNames[activeSection.value] : `第 ${activeSection.value + 1} 行`);
const filteredMaterials = computed(() => {
  const query = colorQuery.value.trim().toLocaleLowerCase("zh-CN");
  if (!query) return props.materials;
  return props.materials.filter((item) => [item.code, item.name, item.location ?? ""]
    .some((value) => value.toLocaleLowerCase("zh-CN").includes(query)));
});

function luminance(hex: string): number {
  const value = Number.parseInt(hex.slice(1), 16);
  return ((value >> 16) & 255) * .299 + ((value >> 8) & 255) * .587 + (value & 255) * .114;
}

function draw(): void {
  const target = canvas.value;
  if (!target) return;
  const cell = cellSize.value;
  const width = props.grid.width * cell;
  const height = props.grid.height * cell;
  const ratio = Math.max(1, Math.min(1.5, devicePixelRatio || 1, 4096 / Math.max(width, height)));
  target.width = width * ratio;
  target.height = height * ratio;
  target.style.width = `${width}px`;
  target.style.height = `${height}px`;
  const context = target.getContext("2d");
  if (!context) return;
  context.scale(ratio, ratio);
  props.grid.cells.forEach((code, index) => {
    const x = index % props.grid.width;
    const y = Math.floor(index / props.grid.width);
    const color = code ? paletteMap.value.get(code)?.hex ?? "#fff" : "#fff";
    const isTarget = matches(index);
    context.globalAlpha = isTarget ? 1 : .17;
    context.fillStyle = color;
    context.fillRect(x * cell, y * cell, cell, cell);
    context.strokeStyle = "rgba(55,50,43,.18)";
    context.strokeRect(x * cell, y * cell, cell, cell);
    if (code && cell >= 8) {
      context.globalAlpha = isTarget ? .8 : .28;
      context.fillStyle = luminance(color) > 145 ? "#20201e" : "#fff";
      context.font = `700 ${Math.max(5, Math.min(cell * .36, cell - 2))}px Inter, sans-serif`;
      context.textAlign = "center";
      context.textBaseline = "middle";
      context.fillText(code, x * cell + cell / 2, y * cell + cell / 2 + .5);
    }
    if (completed.value.has(index)) {
      context.globalAlpha = 1;
      context.strokeStyle = "#147a48";
      context.lineWidth = Math.max(1.5, cell * .12);
      context.strokeRect(x * cell + 1, y * cell + 1, Math.max(1, cell - 2), Math.max(1, cell - 2));
      context.fillStyle = "#147a48";
      context.beginPath();
      context.arc(x * cell + cell - Math.max(2.5, cell * .18), y * cell + Math.max(2.5, cell * .18), Math.max(2, cell * .16), 0, Math.PI * 2);
      context.fill();
      if (cell >= 16) {
        context.fillStyle = "#fff";
        context.font = `800 ${Math.max(5, cell * .19)}px sans-serif`;
        context.textAlign = "center";
        context.textBaseline = "middle";
        context.fillText("✓", x * cell + cell - cell * .18, y * cell + cell * .19);
      }
    }
  });
  context.globalAlpha = 1;
}

function canvasWheel(event: WheelEvent): void {
  if (!event.ctrlKey) return;
  event.preventDefault();
  const scroller = canvasScroller.value;
  const target = canvas.value;
  if (!scroller || !target) return;
  const previous = cellSize.value;
  const nextZoom = Math.max(7, Math.min(zoomMax.value, zoom.value + (event.deltaY < 0 ? 2 : -2)));
  if (nextZoom === zoom.value) return;
  const bounds = target.getBoundingClientRect();
  const logicalX = (event.clientX - bounds.left) / previous;
  const logicalY = (event.clientY - bounds.top) / previous;
  zoom.value = nextZoom;
  nextTick(() => window.requestAnimationFrame(() => {
    const nextBounds = target.getBoundingClientRect();
    scroller.scrollLeft += nextBounds.left + logicalX * cellSize.value - event.clientX;
    scroller.scrollTop += nextBounds.top + logicalY * cellSize.value - event.clientY;
  }));
}

function indexAt(event: PointerEvent): number | null {
  const bounds = canvas.value?.getBoundingClientRect();
  if (!bounds) return null;
  const x = Math.floor((event.clientX - bounds.left) / (bounds.width / props.grid.width));
  const y = Math.floor((event.clientY - bounds.top) / (bounds.height / props.grid.height));
  if (x < 0 || y < 0 || x >= props.grid.width || y >= props.grid.height) return null;
  return y * props.grid.width + x;
}

function toggle(event: PointerEvent): void {
  const index = indexAt(event);
  if (index === null || !matches(index)) return;
  undoStack.value.push(new Set(completed.value));
  const next = new Set(completed.value);
  next.has(index) ? next.delete(index) : next.add(index);
  completed.value = next;
  persist();
}

function finishTarget(): void {
  undoStack.value.push(new Set(completed.value));
  const next = new Set(completed.value);
  targetIndices.value.forEach((index) => next.add(index));
  completed.value = next;
  persist();
  emit("notify", `${targetTitle.value} 已全部完成`);
}

function undo(): void {
  const previous = undoStack.value.pop();
  if (previous) completed.value = previous;
  persist();
}

function setMode(next: typeof mode.value): void {
  mode.value = next;
  activeSection.value = 0;
  persist();
}

function setActiveColor(code: string): void {
  activeColor.value = code;
  persist();
}

function setActiveSection(index: number): void {
  activeSection.value = index;
  persist();
}

function persist(): void {
  localDirty.value = true;
  saveLocalProgress(true);
  if (syncConflict.value) return;
  if (props.syncStatus !== "synced" || props.projectId === "local" || props.projectRevision < 1) return;
  window.clearTimeout(persistTimer);
  persistTimer = window.setTimeout(async () => {
    try {
      const apiMode = mode.value === "row" ? "row-column" : mode.value;
      const navigationCursor = mode.value === "color"
        ? { kind: "color", colorCode: activeColor.value }
        : mode.value === "region"
          ? { kind: "region", regionIndex: activeSection.value }
          : { kind: "row-column", axis: "row", index: activeSection.value };
      const result = await shared.api.saveBuildProgress(props.projectId, {
        projectRevision: props.projectRevision,
        baseProgressRevision: progressRevision.value,
        mode: apiMode,
        navigationCursor,
        completedIndices: [...completed.value].sort((a, b) => a - b),
      });
      progressRevision.value = result.progress.progressRevision;
      localDirty.value = false;
      saveLocalProgress(false);
    } catch (error) {
      try {
        const latest = await shared.api.buildProgress(props.projectId);
        if (latest.progress.projectRevision === props.projectRevision) {
          remoteSnapshot.value = latest.progress;
          syncConflict.value = true;
        }
      } catch { /* retain local copy even if conflict refresh is unavailable */ }
      emit("notify", error instanceof Error ? error.message : "制作进度同步失败，已保留本机副本");
    }
  }, 450);
}

function useRemoteProgress(): void {
  const remote = remoteSnapshot.value;
  if (!remote) return;
  completed.value = new Set(remote.completedIndices);
  progressRevision.value = remote.progressRevision;
  localDirty.value = false;
  syncConflict.value = false;
  saveLocalProgress(false);
  draw();
}

function overwriteWithLocalProgress(): void {
  const remote = remoteSnapshot.value;
  if (!remote) return;
  progressRevision.value = remote.progressRevision;
  syncConflict.value = false;
  persist();
}

async function flushBuildProgress(): Promise<void> {
  if (props.syncStatus !== "synced" || props.projectId === "local" || props.projectRevision < 1) return;
  window.clearTimeout(persistTimer);
  const apiMode = mode.value === "row" ? "row-column" : mode.value;
  const navigationCursor = mode.value === "color"
    ? { kind: "color", colorCode: activeColor.value }
    : mode.value === "region"
      ? { kind: "region", regionIndex: activeSection.value }
      : { kind: "row-column", axis: "row", index: activeSection.value };
  const result = await shared.api.saveBuildProgress(props.projectId, {
    projectRevision: props.projectRevision,
    baseProgressRevision: progressRevision.value,
    mode: apiMode,
    navigationCursor,
    completedIndices: [...completed.value].sort((a, b) => a - b),
  });
  progressRevision.value = result.progress.progressRevision;
  localDirty.value = false;
  saveLocalProgress(false);
}

async function confirmInventoryConsume(): Promise<void> {
  if (consumeBusy.value) return;
  if (!canConfirmInventoryConsume({
    synced: props.syncStatus === "synced",
    cloudProject: props.projectId !== "local" && props.projectRevision >= 1,
    buildComplete: progress.value === 100,
    busy: false,
    phase: consumePhase.value,
  })) return;
  consumeBusy.value = true;
  consumePhase.value = "busy";
  consumeMessage.value = "";
  try {
    if (progress.value === 100) await flushBuildProgress();
    const outcome = await shared.consumeProjectInventory(props.projectId, props.projectRevision, consumeOriginFingerprint.value);
    consumePhase.value = outcome.nextPhase;
    consumeMessage.value = outcome.message;
    consumeOriginFingerprint.value = "originFingerprint" in outcome ? outcome.originFingerprint ?? null : null;
    emit("notify", outcome.message);
  } catch (error) {
    // Unexpected throw before a returned outcome — treat as not-yet-submitted POST retry.
    consumePhase.value = "retryable";
    consumeMessage.value = error instanceof Error
      ? `${error.message}。库存尚未扣减，可重试确认扣减。`
      : "库存扣减失败，可重试确认扣减。";
    emit("notify", consumeMessage.value);
  } finally {
    consumeBusy.value = false;
  }
}

async function retryConsumeInventoryRefresh(): Promise<void> {
  if (consumeBusy.value) return;
  if (!canRetryInventoryConsumeRefresh({
    synced: props.syncStatus === "synced",
    busy: false,
    phase: consumePhase.value,
  })) return;
  consumeBusy.value = true;
  try {
    // Refresh-only recovery: inventory/ledger GET against the frozen origin fingerprint — never re-POST.
    await shared.refreshInventorySnapshot(
      consumeOriginFingerprint.value,
      inventoryConsumeAccountSwitchRefreshMessage(),
    );
    const outcome = inventoryConsumeAfterPostRefreshOutcome(true, 0);
    consumePhase.value = outcome.nextPhase;
    consumeMessage.value = outcome.message;
    consumeOriginFingerprint.value = null;
    emit("notify", outcome.message);
  } catch (error) {
    const accountSwitched = error instanceof Error && /原账号已提交|切回原账号/.test(error.message);
    const outcome = inventoryConsumeAfterPostRefreshOutcome(
      false,
      0,
      consumeOriginFingerprint.value ?? undefined,
      { accountSwitched },
    );
    consumePhase.value = outcome.nextPhase;
    consumeMessage.value = outcome.message;
    emit("notify", outcome.message);
  } finally {
    consumeBusy.value = false;
  }
}

function saveLocalProgress(dirty: boolean): void {
  localStorage.setItem(localKey.value, JSON.stringify({
    completedIndices: [...completed.value],
    progressRevision: progressRevision.value,
    updatedAt: new Date().toISOString(),
    dirty,
  }));
}

function revokePhotoPreviews(): void {
  for (const url of Object.values(photoPreviewUrls.value)) {
    if (url.startsWith("blob:")) URL.revokeObjectURL(url);
  }
  photoPreviewUrls.value = {};
}

function mintPhotoIdempotencyKey(): string {
  return crypto.randomUUID();
}

async function loadPhotoPreview(photo: ApiCompletionPhoto): Promise<void> {
  if (photoPreviewUrls.value[photo.id]) return;
  try {
    const blob = await shared.api.downloadCompletionPhotoContent(photo.projectId, photo.id);
    const url = URL.createObjectURL(blob);
    photoPreviewUrls.value = { ...photoPreviewUrls.value, [photo.id]: url };
  } catch (error) {
    const outcome = interpretCompletionPhotoFailure(error);
    photoMessage.value = outcome.message;
    photoRetryable.value = outcome.canRetry;
    photoRetryKind.value = outcome.canRetry ? "load" : null;
  }
}

async function refreshCompletionPhotos(): Promise<void> {
  if (!(props.projectId !== "local" && props.projectRevision >= 1 && props.syncStatus === "synced" && progress.value === 100)) {
    return;
  }
  if (!shared.api.getToken()) {
    photoMessage.value = "请先登录后再查看完工照";
    photoRetryable.value = false;
    photoRetryKind.value = null;
    return;
  }
  photoBusy.value = true;
  photoMessage.value = "正在加载完工照…";
  photoRetryable.value = false;
  photoRetryKind.value = null;
  try {
    const result = await shared.api.listCompletionPhotos(props.projectId, props.projectRevision);
    revokePhotoPreviews();
    photos.value = result.photos;
    photoMessage.value = result.photos.length
      ? `已加载 ${result.photos.length} 张完工照（版本 ${result.revision}）`
      : completionPhotoListEmptyMessage();
    await Promise.all(result.photos.map((photo) => loadPhotoPreview(photo)));
  } catch (error) {
    const outcome = interpretCompletionPhotoFailure(error);
    photoMessage.value = outcome.message;
    photoRetryable.value = outcome.canRetry;
    photoRetryKind.value = outcome.canRetry ? "load" : null;
  } finally {
    photoBusy.value = false;
  }
}

async function uploadCompletionPhotoFile(file: File): Promise<void> {
  if (!canManageCompletionPhotos({
    authenticated: Boolean(shared.api.getToken()),
    synced: props.syncStatus === "synced",
    cloudProject: props.projectId !== "local" && props.projectRevision >= 1,
    buildComplete: progress.value === 100,
    busy: false,
  })) {
    photoMessage.value = "请先完成制作并同步云端进度后再上传完工照";
    photoRetryable.value = false;
    photoRetryKind.value = null;
    return;
  }
  const fingerprint = completionPhotoUploadFingerprint(file, props.projectRevision);
  if (!photoIdempotencyKey.value || photoFileFingerprint.value !== fingerprint) {
    photoIdempotencyKey.value = mintPhotoIdempotencyKey();
    photoFileFingerprint.value = fingerprint;
  }
  pendingPhotoFile.value = file;
  photoBusy.value = true;
  photoMessage.value = "正在上传完工照…";
  photoRetryable.value = false;
  photoRetryKind.value = null;
  try {
    const { photo } = await shared.api.uploadCompletionPhoto(
      props.projectId,
      props.projectRevision,
      file,
      photoIdempotencyKey.value,
    );
    photoMessage.value = completionPhotoUploadSuccessMessage(photo);
    photoRetryable.value = false;
    photoRetryKind.value = null;
    pendingPhotoFile.value = null;
    photoIdempotencyKey.value = mintPhotoIdempotencyKey();
    photoFileFingerprint.value = "";
    if (!photos.value.some((item) => item.id === photo.id)) {
      photos.value = [photo, ...photos.value];
    }
    await loadPhotoPreview(photo);
    emit("notify", photoMessage.value);
  } catch (error) {
    const outcome = interpretCompletionPhotoFailure(error);
    photoMessage.value = outcome.message;
    photoRetryable.value = outcome.canRetry;
    photoRetryKind.value = outcome.canRetry ? "upload" : null;
    if (outcome.rotateIdempotencyKey) {
      photoIdempotencyKey.value = mintPhotoIdempotencyKey();
      // Keep pending file + updated fingerprint so retry can proceed with the new key.
      photoFileFingerprint.value = fingerprint;
    }
    emit("notify", outcome.message);
  } finally {
    photoBusy.value = false;
  }
}

function onCompletionPhotoPicked(event: Event): void {
  const input = event.target as HTMLInputElement;
  const file = input.files?.[0];
  input.value = "";
  if (!file) return;
  void uploadCompletionPhotoFile(file);
}

function pickCompletionPhoto(): void {
  if (photoBusy.value) return;
  photoFileInput.value?.click();
}

function retryCompletionPhotoAction(): void {
  if (!canRetryCompletionPhoto.value) return;
  if (photoRetryKind.value === "upload") {
    const file = pendingPhotoFile.value;
    if (!file) {
      photoMessage.value = "没有可重试的完工照文件，请重新选择后上传";
      photoRetryable.value = false;
      photoRetryKind.value = null;
      return;
    }
    void uploadCompletionPhotoFile(file);
    return;
  }
  void refreshCompletionPhotos();
}

watch([mode, activeColor, activeSection, zoom, completed], () => nextTick(draw), { deep: true });
watch(
  () => [progress.value, props.syncStatus, props.projectId, props.projectRevision] as const,
  ([nextProgress, syncStatus]) => {
    if (nextProgress === 100 && syncStatus === "synced") void refreshCompletionPhotos();
  },
);
watch(zoomMax, (maximum) => {
  if (zoom.value > maximum) zoom.value = maximum;
});
onMounted(() => {
  try {
    const saved = JSON.parse(localStorage.getItem(localKey.value) ?? "null") as number[] | { completedIndices?: number[]; progressRevision?: number; dirty?: boolean; updatedAt?: string } | null;
    const indices = Array.isArray(saved) ? saved : saved?.completedIndices ?? [];
    completed.value = new Set(indices.filter((index) => Number.isInteger(index) && index >= 0 && index < props.grid.cells.length));
    progressRevision.value = Array.isArray(saved) ? 0 : saved?.progressRevision ?? 0;
    localDirty.value = Array.isArray(saved) ? indices.length > 0 : saved?.dirty ?? false;
  } catch { /* keep empty progress */ }
  if (props.syncStatus === "synced" && props.projectId !== "local") {
    void shared.api.buildProgress(props.projectId).then(({ progress: remote }) => {
      if (remote.projectRevision !== props.projectRevision) {
        emit("notify", "图纸版本已变化，请重新核对制作进度");
        return;
      }
      remoteSnapshot.value = remote;
      mode.value = remote.mode === "row-column" ? "row" : remote.mode;
      if (remote.navigationCursor && typeof remote.navigationCursor === "object") {
        const cursor = remote.navigationCursor as { colorCode?: string; regionIndex?: number; index?: number };
        if (cursor.colorCode) activeColor.value = cursor.colorCode;
        if (cursor.regionIndex !== undefined) activeSection.value = cursor.regionIndex;
        if (cursor.index !== undefined) activeSection.value = cursor.index;
      }
      if (localDirty.value) {
        if (remote.progressRevision !== progressRevision.value) {
          syncConflict.value = true;
          emit("notify", "本机和另一设备都更新了制作进度，请选择保留哪一份");
        } else {
          emit("notify", "检测到尚未同步的本机制作进度，正在继续同步");
          persist();
        }
      } else {
        progressRevision.value = remote.progressRevision;
        completed.value = new Set(remote.completedIndices);
        saveLocalProgress(false);
      }
      draw();
    }).catch((error) => emit("notify", error instanceof Error ? error.message : "制作进度读取失败"));
  }
  draw();
});
onBeforeUnmount(() => {
  window.clearTimeout(persistTimer);
  revokePhotoPreviews();
});
</script>

<template>
  <section class="build-workbench">
    <div v-if="syncConflict" class="build-conflict" role="alert"><span><b>制作进度发生冲突</b><small>本机与另一设备都已更新，系统不会自动覆盖。</small></span><button class="outline-button" @click="useRemoteProgress">采用云端</button><button class="primary-button" @click="overwriteWithLocalProgress">保留本机</button></div>
    <header class="build-top"><button class="outline-button" @click="emit('back')">← 返回编辑器</button><div><span class="eyebrow">BUILD MODE</span><h1>{{ projectName }}</h1><small>图纸版本 {{ projectRevision || '本机' }} · {{ syncStatus === 'synced' ? '进度同步到微信小程序' : '进度保存在此浏览器' }}</small></div><button class="outline-button" @click="emit('notify','按颜色、区域或行逐格标记，进度会自动保存')">制作说明</button></header>
    <div class="build-tabs-wide"><button :class="{ active: mode === 'color' }" @click="setMode('color')">按颜色</button><button :class="{ active: mode === 'region' }" @click="setMode('region')">按区域</button><button :class="{ active: mode === 'row' }" @click="setMode('row')">按行制作</button></div>
    <main class="build-center"><div class="build-canvas-toolbar"><div><i :style="{ background: mode === 'color' ? paletteMap.get(activeColor)?.hex : '#f7c948' }"></i><span><b>{{ targetTitle }}</b><small>点击高亮格标记完成 · 格内显示色号</small></span></div><strong>{{ targetDone }} / {{ targetIndices.length }}</strong><aside><button aria-label="缩小制作图纸" @click="zoom = Math.max(7, zoom - 2)"><AppIcon name="minus" :size="15"/></button><span>{{ Math.round(zoom / 13 * 100) }}%</span><button aria-label="放大制作图纸" @click="zoom = Math.min(zoomMax, zoom + 2)"><AppIcon name="plus" :size="15"/></button></aside></div><div ref="canvasScroller" class="build-canvas-scroll" @wheel="canvasWheel"><canvas ref="canvas" role="img" aria-label="制作进度画布，格内显示对应色号" @pointerdown="toggle"></canvas></div></main>
    <aside class="build-progress-panel"><div class="progress-ring" :style="{ '--progress': `${progress * 3.6}deg` }"><span><b>{{ progress }}%</b><small>总进度</small></span></div><h3>已完成 {{ doneCount.toLocaleString() }} / {{ beadIndices.length.toLocaleString() }} 颗</h3><p>{{ progress === 100 ? '全部完成，可以上传成品照了' : `预计还需 ${Math.ceil((beadIndices.length - doneCount) / 32)} 分钟` }}</p><p v-if="consumeMessage" class="consume-status" role="status">{{ consumeMessage }}</p><template v-if="mode === 'color'"><label class="build-color-search"><span aria-hidden="true">⌕</span><input v-model="colorQuery" type="search" placeholder="搜索本作品色号" aria-label="搜索制作色号" /></label><div class="target-list"><button v-for="item in filteredMaterials" :key="item.code" :class="{ active: activeColor === item.code }" :title="`${item.name} · 豆仓库存 ${item.stock} 颗`" @click="setActiveColor(item.code)"><i :style="{ background: item.hex }"></i><span><b>{{ item.code }}</b><small>进度 {{ [...completed].filter(index => grid.cells[index] === item.code).length }}/{{ item.quantity }} · 库存 {{ item.stock }}</small></span></button><p v-if="!filteredMaterials.length" class="build-color-empty">本作品未使用该色号</p></div></template><div v-else-if="mode === 'region'" class="target-list"><button v-for="(name,index) in regionNames" :key="name" :class="{ active: activeSection === index }" @click="setActiveSection(index)"><i>▦</i><span><b>{{ name }}</b><small>分区制作</small></span></button></div><div v-else class="target-list row-targets"><button v-for="row in grid.height" :key="row" :class="{ active: activeSection === row - 1 }" @click="setActiveSection(row - 1)"><i>☰</i><span><b>第 {{ row }} 行</b><small>逐行完成</small></span></button></div><button class="primary-button finish-target" :disabled="targetDone === targetIndices.length" @click="finishTarget">{{ targetDone === targetIndices.length ? '当前目标已完成' : '完成当前目标' }}</button><button v-if="progress === 100 && syncStatus === 'synced' && projectId !== 'local' && projectRevision >= 1 && consumePhase === 'refresh'" class="primary-button consume-inventory" :disabled="!canRefreshConsumeInventory || consumeBusy" @click="retryConsumeInventoryRefresh">{{ consumeBusy ? '正在刷新豆仓…' : '只刷新库存和流水' }}</button><button v-else-if="progress === 100 && syncStatus === 'synced' && projectId !== 'local' && projectRevision >= 1" class="primary-button consume-inventory" :disabled="!canConsumeInventory || consumeBusy || consumePhase === 'consumed'" @click="confirmInventoryConsume">{{ consumeBusy ? '正在确认扣减…' : consumePhase === 'consumed' ? '已确认扣减库存' : consumePhase === 'retryable' ? '重试确认扣减库存' : '确认扣减豆仓库存' }}</button>
      <section v-if="progress === 100 && projectId !== 'local' && projectRevision >= 1" class="completion-photos" aria-label="完工照">
        <h4>完工照</h4>
        <p class="completion-photos-hint">绑定图纸版本 {{ projectRevision }}；经鉴权 API 上传与读取，不直连私有桶。</p>
        <p v-if="photoMessage" class="completion-photos-status" role="status">{{ photoMessage }}</p>
        <input ref="photoFileInput" class="completion-photo-input" type="file" accept="image/jpeg,image/png,image/webp" @change="onCompletionPhotoPicked" />
        <button class="primary-button completion-photo-upload" type="button" :disabled="!canUseCompletionPhotos || photoBusy" @click="pickCompletionPhoto">{{ photoBusy ? '处理中…' : '上传完工照' }}</button>
        <button v-if="canRetryCompletionPhoto" class="outline-button" type="button" :disabled="photoBusy" @click="retryCompletionPhotoAction">{{ completionPhotoRetryButtonLabel }}</button>
        <ul v-if="photos.length" class="completion-photo-list">
          <li v-for="photo in photos" :key="photo.id">
            <img v-if="photoPreviewUrls[photo.id]" :src="photoPreviewUrls[photo.id]" :alt="`完工照 ${photo.id.slice(0, 8)}`" />
            <span v-else class="completion-photo-placeholder">读取中…</span>
            <small>v{{ photo.projectRevision }} · {{ Math.round(photo.sizeBytes / 1024) }} KB</small>
          </li>
        </ul>
      </section>
      <button class="outline-button undo-build" :disabled="!undoStack.length" @click="undo">撤回上一步</button></aside>
  </section>
</template>
