import type { PatternGrid } from "./pixel-engine";
import { parseApiErrorEnvelope } from "./api-error";
import {
  completionPhotoContentPath,
  completionPhotoListPath,
  completionPhotoUploadPath,
  publicCompletionPhoto,
  type ApiCompletionPhoto,
} from "./completion-photos";
import { assertCloudGenerationDimensions, assertCloudProjectGrid } from "./cloud-contract";
import { resolveClientApiBase } from "../../src/data/client-api-base";

export type { ApiCompletionPhoto } from "./completion-photos";

const API_BASE = resolveClientApiBase({
  isWechatMini: false,
  development: import.meta.env?.DEV ?? true,
  configuredBase: import.meta.env?.VITE_API_BASE ?? "",
});
const API_BASE_CONFIGURATION_ERROR = "正式环境未配置 API 地址，请设置 VITE_API_BASE 为公网 HTTPS 接口地址。";

