  claimLoginRewards(): Promise<{ account: { balance: number }; welcomeGranted: boolean; dailyGranted: boolean; day: string }> {
    return this.request("/credits/login-rewards", { method: "POST", body: JSON.stringify({}) });
  }

  createLocalConversion(input: { name: string; paletteId: string; grid: PatternGrid; mode: "normal" | "pixel" }, key: string): Promise<{ project: ApiProject; account: { balance: number }; cost: number }> {
    return this.request("/local-conversions", {
      method: "POST", headers: { "Idempotency-Key": key },
      body: JSON.stringify({ ...input, grid: { ...input.grid, encoding: "palette-code-v1" }, deviceSource: "web" }),
    });
  }

