export type WebInviteGate = {
  synced: boolean;
  busy: boolean;
  loadFailed: boolean;
};

export type WebInviteAcceptGate = WebInviteGate & {
  hasPendingCode: boolean;
};

export type WebInviteFailureOutcome =
  | { kind: "retryable"; message: string }
  | { kind: "unauthorized"; message: string }
  | { kind: "conflict"; message: string };

export function canLoadWebInvite(gate: WebInviteGate): boolean {
  return gate.synced && !gate.busy;
}

export function canRetryWebInviteLoad(gate: WebInviteGate): boolean {
  return gate.synced && !gate.busy && gate.loadFailed;
}

export function canAcceptWebInvite(gate: WebInviteAcceptGate): boolean {
  return gate.synced && !gate.busy && gate.hasPendingCode;
}

export function webInviteOfflineMessage(): string {
  return "请先连接共享账号后再查看邀请码。未登录不会产生邀请奖励。";
}

export function webInvitePendingRewardMessage(): string {
  return "好友登录并绑定邀请码后，邀请人可获奖励：新用户 +3 次，老用户 +1 次；被邀请人 +0。到账以服务端账本为准，不会伪造次数。";
}

export function webInviteShareDisclaimer(): string {
  return "复制邀请码或点击分享本身不加次数；好友登录绑定成功后按新用户 +3 / 老用户 +1 给邀请人入账。";
}

export function interpretWebInviteFailure(error: unknown): WebInviteFailureOutcome {
  const status = typeof error === "object" && error && "status" in error
    ? Number((error as { status?: unknown }).status)
    : NaN;
  const code = typeof error === "object" && error && "code" in error
    ? String((error as { code?: unknown }).code ?? "")
    : "";
  const message = error instanceof Error
    ? error.message
    : typeof error === "object" && error && "message" in error && typeof (error as { message?: unknown }).message === "string"
      ? (error as { message: string }).message
      : "邀请操作失败";
  if (status === 401 || code === "UNAUTHORIZED" || code === "SESSION_REVOKED") {
    return { kind: "unauthorized", message: "共享会话已失效，请重新连接后再试。" };
  }
  if (status === 409 || code === "INVITE_SELF_NOT_ALLOWED" || code === "INVITE_ALREADY_BOUND") {
    return { kind: "conflict", message: message || "邀请关系冲突，未改动次数余额。" };
  }
  return {
    kind: "retryable",
    message: /网络|failed to fetch|timeout/i.test(message)
      ? "网络异常，邀请状态未更新。可重试。"
      : `${message}。邀请状态未更新，可重试。`,
  };
}
