export interface CropTransformInput {
  cropRatio: string;
  freeCropRatio: number;
  cropScale: number;
  cropOffsetX: number;
  cropOffsetY: number;
  rotation: number;
}

export interface CropRectangle {
  left: number;
  top: number;
  width: number;
  height: number;
  rotatedWidth: number;
  rotatedHeight: number;
  maxOffsetX: number;
  maxOffsetY: number;
  rotation: 0 | 90 | 180 | 270;
}

const MAX_API_OFFSET = 300;

function clamp(value: number, lower: number, upper: number): number {
  return Math.min(upper, Math.max(lower, value));
}

export function normalizeCropRotation(rotation: number): 0 | 90 | 180 | 270 {
  const normalized = ((Math.round(rotation / 90) * 90) % 360 + 360) % 360;
  return normalized as 0 | 90 | 180 | 270;
}

export function rotatedSourceSize(sourceWidth: number, sourceHeight: number, rotation: number): { width: number; height: number } {
  const normalized = normalizeCropRotation(rotation);
  return normalized === 90 || normalized === 270
    ? { width: sourceHeight, height: sourceWidth }
    : { width: sourceWidth, height: sourceHeight };
}

export function calculateCropRectangle(
  sourceWidth: number,
  sourceHeight: number,
  input: CropTransformInput,
): CropRectangle {
  const rotation = normalizeCropRotation(input.rotation);
  const rotated = rotatedSourceSize(sourceWidth, sourceHeight, rotation);
  const ratioMap: Record<string, number> = { "1:1": 1, "4:3": 4 / 3, "3:4": 3 / 4 };
  const aspect = input.cropRatio === "自由"
    ? clamp(input.freeCropRatio / 100, .65, 1.5)
    : ratioMap[input.cropRatio] ?? rotated.width / rotated.height;

  let fittedWidth = rotated.width;
  let fittedHeight = fittedWidth / aspect;
  if (fittedHeight > rotated.height) {
    fittedHeight = rotated.height;
    fittedWidth = fittedHeight * aspect;
  }

  const scale = clamp(input.cropScale / 100, 1, 2);
  const width = Math.max(1, Math.round(fittedWidth / scale));
  const height = Math.max(1, Math.round(fittedHeight / scale));
  const physicalMaxX = Math.max(0, (rotated.width - width) / 2);
  const physicalMaxY = Math.max(0, (rotated.height - height) / 2);
  const maxOffsetX = Math.min(MAX_API_OFFSET, physicalMaxX);
  const maxOffsetY = Math.min(MAX_API_OFFSET, physicalMaxY);
  const offsetX = clamp(input.cropOffsetX, -maxOffsetX, maxOffsetX);
  const offsetY = clamp(input.cropOffsetY, -maxOffsetY, maxOffsetY);

  return {
    left: Math.round(rotated.width / 2 + offsetX - width / 2),
    top: Math.round(rotated.height / 2 + offsetY - height / 2),
    width,
    height,
    rotatedWidth: rotated.width,
    rotatedHeight: rotated.height,
    maxOffsetX,
    maxOffsetY,
    rotation,
  };
}

/**
 * Draws the same rotate-then-crop result used by the generation service.
 * The destination may be any size; one-pixel crop rounding is retained.
 */
export function drawCropResult(
  context: CanvasRenderingContext2D,
  image: CanvasImageSource,
  sourceWidth: number,
  sourceHeight: number,
  crop: CropRectangle,
  destinationX: number,
  destinationY: number,
  destinationWidth: number,
  destinationHeight: number,
): void {
  const scaleX = destinationWidth / crop.width;
  const scaleY = destinationHeight / crop.height;
  context.save();
  context.beginPath();
  context.rect(destinationX, destinationY, destinationWidth, destinationHeight);
  context.clip();
  context.translate(destinationX - crop.left * scaleX, destinationY - crop.top * scaleY);
  context.scale(scaleX, scaleY);

  if (crop.rotation === 90) {
    context.translate(sourceHeight, 0);
    context.rotate(Math.PI / 2);
  } else if (crop.rotation === 180) {
    context.translate(sourceWidth, sourceHeight);
    context.rotate(Math.PI);
  } else if (crop.rotation === 270) {
    context.translate(0, sourceWidth);
    context.rotate(Math.PI * 1.5);
  }

  context.drawImage(image, 0, 0, sourceWidth, sourceHeight);
  context.restore();
}
