const TOKEN_KEY = "pindou.web.session";
const ACTIVE_PROJECT_KEY = "pindou.web.active-project";
const SESSION_SOURCE_KEY = "pindou.web.session-source";
type SharedSessionSource = "none" | "wechat-pair" | "development";

interface SharedState {
  status: "offline" | "connecting" | "synced" | "error";
  sessionSource: SharedSessionSource;
  paletteStatus: "idle" | "loading" | "ready" | "error";
  paletteError: string;
  userName: string;
  userId: string;
  credits: number | null;
  projects: ApiProjectListItem[];
  activeProject: ApiProject | null;
  palettes: ApiPalette[];
  activePalette: ApiPalette | null;
  inventory: ApiInventoryItem[];
  inventoryTransactions: ApiInventoryTransaction[];
  exports: ApiExportJob[];
  creditProducts: ApiCreditProduct[];
  creditLedger: ApiCreditLedgerEntry[];
  draftRevision: number;
  lastError: string;
}

const state = reactive<SharedState>({
  status: "offline",
  sessionSource: "none",
  paletteStatus: "idle",
  paletteError: "",
  userName: "",
  userId: "",
  credits: null,
  projects: [],
  activeProject: null,
  palettes: [],
  activePalette: null,
  inventory: [],
  inventoryTransactions: [],
  exports: [],
  creditProducts: [],
  creditLedger: [],
  draftRevision: 0,
  lastError: "",
});

const api = new ApiClient(localStorage.getItem(TOKEN_KEY) ?? "");
const DEFAULT_PALETTE_ID = "mard-221-v1";

function defaultPalette(): ApiPalette | null {
  return state.palettes.find((palette) => palette.id === DEFAULT_PALETTE_ID) ?? state.palettes[0] ?? null;
}

function ensureBundledPalette(): ApiPalette {
  const bundled = createBundledPalette(DEFAULT_PALETTE_ID);
  const existing = state.palettes.find((palette) => palette.id === bundled.id);
  if (existing?.colors.length === bundled.colors.length) return existing;

  state.palettes = [...state.palettes.filter((palette) => palette.id !== bundled.id), bundled];
  if (!state.activePalette || state.activePalette.id === bundled.id) state.activePalette = bundled;
  return bundled;
}

function applyPaletteCatalog(palettes: ApiPalette[]): void {
  const activePaletteId = state.activeProject?.paletteId ?? state.activePalette?.id ?? DEFAULT_PALETTE_ID;
  state.palettes = palettes.filter((palette) => palette.retired !== true);
  if (!state.palettes.some((palette) => palette.id === DEFAULT_PALETTE_ID)) {
    throw new Error("正式色卡目录不完整");
  }
  state.activePalette = state.palettes.find((palette) => palette.id === activePaletteId) ?? defaultPalette();
}

async function loadPaletteCatalog(): Promise<void> {
  state.paletteStatus = "loading";
  state.paletteError = "";
  try {
    const result = await api.palettes();
    applyPaletteCatalog(result.palettes);
    state.paletteStatus = "ready";
  } catch (error) {
    ensureBundledPalette();
    state.paletteStatus = "error";
    state.paletteError = error instanceof Error ? error.message : "正式色卡加载失败";
    throw error;
  }
}

async function hydrate(): Promise<void> {
  state.status = "connecting";
  state.lastError = "";
  try {
    await api.claimLoginRewards();
    const [me, projectPage, creditResult, , inventoryResult, transactionResult, exportResult, productResult, ledgerResult] = await Promise.all([
      api.me(),
      api.projects(),
      api.credits() as Promise<{ account: { balance: number } }>,
      loadPaletteCatalog(),
      api.inventory(),
      api.inventoryTransactions(),
      api.exports(),
      api.creditProducts(),
      api.creditLedger(),
    ]);
    const user = me.user as { displayName?: string; id?: string };
    state.userName = user.displayName ?? "微信用户";
    state.userId = user.id ?? "";
    state.credits = creditResult.account.balance;
    state.projects = projectPage.projects;
    state.inventory = inventoryResult.items;
    state.inventoryTransactions = transactionResult.transactions;
    state.exports = exportResult.exports;
    state.creditProducts = productResult.products;
    state.creditLedger = ledgerResult.entries;
    const storedProjectId = localStorage.getItem(ACTIVE_PROJECT_KEY);
    const preferredId = state.activeProject && projectPage.projects.some((project) => project.id === state.activeProject?.id)
      ? state.activeProject.id
      : storedProjectId && projectPage.projects.some((project) => project.id === storedProjectId)
        ? storedProjectId
        : projectPage.projects[0]?.id;
    if (preferredId) await loadProject(preferredId);
    else {
      state.activeProject = null;
      state.activePalette = defaultPalette();
      state.draftRevision = 0;
    }
    state.status = "synced";
  } catch (error) {
    state.status = "error";
    state.lastError = error instanceof Error ? error.message : "共享数据加载失败";
    throw error;
  }
}

async function restore(): Promise<boolean> {
  if (!localStorage.getItem(TOKEN_KEY)) {
    await loadPaletteCatalog().catch(() => undefined);
    return false;
  }
  if (localStorage.getItem(SESSION_SOURCE_KEY) !== "wechat-pair") {
    localStorage.removeItem(TOKEN_KEY);
    api.setToken("");
    state.sessionSource = "none";
    await loadPaletteCatalog().catch(() => undefined);
    return false;
  }
  try {
    await hydrate();
    return true;
  } catch {
    localStorage.removeItem(TOKEN_KEY);
    localStorage.removeItem(SESSION_SOURCE_KEY);
    api.setToken("");
    state.sessionSource = "none";
    state.activeProject = null;
    state.projects = [];
    state.inventory = [];
    state.inventoryTransactions = [];
    state.userId = "";
    state.status = "offline";
    await loadPaletteCatalog().catch(() => {
      state.status = "error";
    });
    return false;
  }
}

async function connectDevelopment(): Promise<void> {
  state.status = "connecting";
  state.sessionSource = "development";
  try {
    const session = await api.createDevSession("Web 创作者");
    localStorage.setItem(TOKEN_KEY, session.token);
    localStorage.setItem(SESSION_SOURCE_KEY, "development");
    await hydrate();
  } catch (error) {
    localStorage.removeItem(TOKEN_KEY);
    localStorage.removeItem(SESSION_SOURCE_KEY);
    api.setToken("");
    state.sessionSource = "none";
    state.status = "error";
    state.lastError = error instanceof Error ? error.message : "共享账号连接失败";
    throw error;
  }
}

async function adoptWebSession(sessionToken: string, pollToken: string): Promise<void> {
  const token = requireWebSessionToken(sessionToken, pollToken);
  api.setToken(token);
  localStorage.setItem(TOKEN_KEY, token);
  localStorage.setItem(SESSION_SOURCE_KEY, "wechat-pair");
  state.sessionSource = "wechat-pair";
  try {
    await hydrate();
  } catch (error) {
    localStorage.removeItem(TOKEN_KEY);
    localStorage.removeItem(SESSION_SOURCE_KEY);
    api.setToken("");
    state.sessionSource = "none";
    throw error;
  }
}

function clearAccountBoundState(): void {
  localStorage.removeItem(TOKEN_KEY);
  localStorage.removeItem(SESSION_SOURCE_KEY);
  localStorage.removeItem(ACTIVE_PROJECT_KEY);
  api.setToken("");
  state.sessionSource = "none";
  state.userName = "";
  state.userId = "";
  state.credits = null;
  state.projects = [];
  state.activeProject = null;
  state.inventory = [];
  state.inventoryTransactions = [];
  state.exports = [];
  state.creditProducts = [];
  state.creditLedger = [];
  state.draftRevision = 0;
  state.lastError = "";
  state.status = "offline";
}

let logoutBusy = false;

async function logout(): Promise<void> {
  const hasToken = Boolean(api.getToken() || localStorage.getItem(TOKEN_KEY));
  const gate = {
    synced: state.status === "synced",
    busy: logoutBusy || state.status === "connecting",
    hasToken,
  };
  if (!canStartWebLogout(gate)) {
    if (!hasToken || state.status !== "synced") {
      throw new Error("当前是本地模式，无需退出登录。");
    }
    throw new Error("正在退出登录，请稍候。");
  }
  logoutBusy = true;
  state.status = "connecting";
  state.lastError = "";
  try {
    await api.deleteSession();
    clearAccountBoundState();
    await loadPaletteCatalog().catch(() => undefined);
  } catch (error) {
    const outcome = interpretWebLogoutFailure(error);
    if (shouldClearLocalSessionAfterLogoutAttempt(outcome)) {
      clearAccountBoundState();
      await loadPaletteCatalog().catch(() => undefined);
      state.lastError = "";
      return;
    }
    state.status = "synced";
    state.lastError = outcome.message;
    throw new Error(outcome.message);
  } finally {
    logoutBusy = false;
  }
}

async function loadProject(projectId: string): Promise<ApiProject> {
  const [{ project }, draftResult] = await Promise.all([
    api.project(projectId),
    api.draft(projectId) as Promise<{ draft: { draftRevision: number; grid: PatternGrid; name?: string } | null }>,
  ]);
  if (draftResult.draft) {
    project.grid = { ...draftResult.draft.grid, encoding: "palette-code-v1" };
    project.name = draftResult.draft.name ?? project.name;
    state.draftRevision = draftResult.draft.draftRevision;
  } else {
    state.draftRevision = 0;
  }
  state.activeProject = project;
  localStorage.setItem(ACTIVE_PROJECT_KEY, project.id);
  state.activePalette = state.palettes.find((palette) => palette.id === project.paletteId) ?? null;
  return project;
}

async function openProject(projectId: string): Promise<ApiProject> {
  if (state.status !== "synced") throw new Error("请先连接共享账号");
  return loadProject(projectId);
}

async function createProject(name: string, grid: PatternGrid, mode: ApiProject["mode"], paletteId?: string): Promise<ApiProject> {
  if (state.status !== "synced") throw new Error("请先连接共享账号");
  const palette = (paletteId ? state.palettes.find((item) => item.id === paletteId) : null) ?? state.activePalette ?? defaultPalette();
  if (!palette) throw new Error("账号没有可用色卡");
  const { project } = await api.createProject({ name, paletteId: palette.id, grid, mode });
  const projectPage = await api.projects();
  state.projects = projectPage.projects;
  state.activeProject = project;
  state.activePalette = palette;
  state.draftRevision = 0;
  return project;
}

async function saveDraft(projectId: string, grid: PatternGrid, name: string): Promise<void> {
  if (state.status !== "synced" || !state.activeProject || state.activeProject.id !== projectId) {
    throw new Error("作品已切换，已阻止草稿写入错误项目");
  }
  const target = state.activeProject;
  const baseDraftRevision = state.draftRevision;
  const result = await api.saveDraft(target, grid, baseDraftRevision, name) as {
    draft: { draftRevision: number };
  };
  if (state.activeProject?.id !== target.id) return;
  state.draftRevision = result.draft.draftRevision;
}

async function commitActiveDraft(): Promise<ApiProject | null> {
  const target = state.activeProject;
  if (state.status !== "synced" || !target || state.draftRevision === 0) return target;
  const result = await api.commitDraft(target, state.draftRevision) as { project: ApiProject };
  if (state.activeProject?.id === target.id) {
    state.activeProject = result.project;
    state.draftRevision = 0;
  }
  state.projects = (await api.projects()).projects;
  return result.project;
}

async function refreshExports(): Promise<void> {
  state.exports = (await api.exports()).exports;
}

async function refreshCredits(): Promise<void> {
  const result = await api.credits() as { account: { balance: number } };
  state.credits = result.account.balance;
}

async function refreshAfterInventoryWrite(
  originFingerprint: string,
  kind: "delta" | "location",
): Promise<void> {
  try {
    await refreshInventorySnapshot(originFingerprint);
  } catch (error) {
    if (isInventoryCalibrateRefreshError(error)) throw error;
    throw new InventoryCalibrateRefreshError(
      error instanceof Error
        ? `${inventoryMaintainRefreshFailureMessage(kind)}（${error.message}）`
        : inventoryMaintainRefreshFailureMessage(kind),
      originFingerprint,
    );
  }
}

async function adjustInventory(colorCode: string, delta: number, paletteId?: string): Promise<void> {
  const palette = (paletteId ? state.palettes.find((item) => item.id === paletteId) : null) ?? state.activePalette;
  if (state.status !== "synced" || !palette) throw new Error("请先连接共享账号");
  const captured = sessionMaterial();
  const originFingerprint = await inventoryCalibrateSessionFingerprint(captured);
  if (sessionMaterial() !== captured) throw new Error("账号已切换，库存增减未提交。请切回原账号后重试。");
  const current = state.inventory.find((item) => item.paletteId === palette.id && item.colorCode === colorCode);
  const result = await api.applyInventoryBatch("delta", [{
    paletteId: palette.id,
    colorCode,
    delta,
    baseRevision: current?.revision ?? 0,
  }]);
  mergeInventoryItems(result.items);
  if (sessionMaterial() !== captured) {
    throw new InventoryCalibrateRefreshError(inventoryMaintainRefreshFailureMessage("delta"), originFingerprint);
  }
  await refreshAfterInventoryWrite(originFingerprint, "delta");
}

async function updateInventoryLocation(colorCode: string, location: string | null, paletteId?: string): Promise<void> {
  const palette = (paletteId ? state.palettes.find((item) => item.id === paletteId) : null) ?? state.activePalette;
  if (state.status !== "synced" || !palette) throw new Error("请先连接共享账号");
  const captured = sessionMaterial();
  const originFingerprint = await inventoryCalibrateSessionFingerprint(captured);
  if (sessionMaterial() !== captured) throw new Error("账号已切换，仓位未提交。请切回原账号后重试。");
  const current = state.inventory.find((item) => item.paletteId === palette.id && item.colorCode === colorCode);
  const nextLocation = normalizeInventoryLocation(location);
  if ((current?.location ?? null) === nextLocation) return;
  const result = await api.setInventoryItem(palette.id, colorCode, {
    quantity: current?.quantity ?? 0,
    location: nextLocation,
    baseRevision: current?.revision ?? 0,
  });
  mergeInventoryItems([result.item]);
  if (sessionMaterial() !== captured) {
    throw new InventoryCalibrateRefreshError(inventoryMaintainRefreshFailureMessage("location"), originFingerprint);
  }
  await refreshAfterInventoryWrite(originFingerprint, "location");
}

function accountKey(): string {
  return state.userId || state.userName;
}

function sessionMaterial(): string {
  return `${api.getToken()}|${localStorage.getItem(TOKEN_KEY) ?? ""}|${state.userId}|${state.userName}`;
}

function applyInventorySnapshot(
  items: ApiInventoryItem[],
  transactions?: ApiInventoryTransaction[],
): void {
  state.inventory = items;
  if (transactions) state.inventoryTransactions = transactions;
}

function mergeInventoryItems(items: ApiInventoryItem[], transactions?: ApiInventoryTransaction[]): void {
  for (const item of items) {
    const index = state.inventory.findIndex((row) => row.paletteId === item.paletteId && row.colorCode === item.colorCode);
    if (index >= 0) state.inventory[index] = item;
    else state.inventory.push(item);
  }
  if (transactions?.length) {
    state.inventoryTransactions = [...transactions, ...state.inventoryTransactions];
  }
}

const ACCOUNT_SWITCH_REFRESH_MESSAGE = "校准已提交到原账号，当前账号未更新。请切回原账号后只刷新库存和流水，不要再次提交。";

async function refreshInventorySnapshot(expectedFingerprint?: string | null, accountSwitchMessage = ACCOUNT_SWITCH_REFRESH_MESSAGE): Promise<void> {
  if (state.status !== "synced") throw new Error("请先连接共享账号");
  // Always validate against the caller-provided origin fingerprint — never treat a
  // newly switched session as the refresh target when an origin is expected.
  const captured = sessionMaterial();
  const fingerprint = await inventoryCalibrateSessionFingerprint(captured);
  if (expectedFingerprint && fingerprint !== expectedFingerprint) {
    throw new InventoryCalibrateRefreshError(accountSwitchMessage, expectedFingerprint);
  }
  if (sessionMaterial() !== captured) {
    if (expectedFingerprint) {
      throw new InventoryCalibrateRefreshError(accountSwitchMessage, expectedFingerprint);
    }
    throw new Error("账号已切换，未读取当前账号以外的库存或流水");
  }
  const [inventoryResult, transactionResult] = await Promise.all([
    api.inventory(),
    api.inventoryTransactions(),
  ]);
  if (sessionMaterial() !== captured) {
    if (expectedFingerprint) {
      throw new InventoryCalibrateRefreshError(accountSwitchMessage, expectedFingerprint);
    }
    throw new Error("账号已切换，未把原账号库存或流水写入当前账号");
  }
  if (expectedFingerprint) {
    const stillOrigin = await inventoryCalibrateSessionFingerprint(sessionMaterial());
    if (stillOrigin !== expectedFingerprint) {
      throw new InventoryCalibrateRefreshError(accountSwitchMessage, expectedFingerprint);
    }
  }
  applyInventorySnapshot(inventoryResult.items, transactionResult.transactions);
}

function consumeSubmittedRefreshFailed(
  originFingerprint: string,
  accountSwitched: boolean,
  transactionCount = 0,
): Extract<InventoryConsumeOutcome, { kind: "refresh_failed" }> {
  const outcome = inventoryConsumeAfterPostRefreshOutcome(false, transactionCount, originFingerprint, { accountSwitched });
  if (outcome.kind !== "refresh_failed") {
    return {
      kind: "refresh_failed",
      message: accountSwitched
        ? inventoryConsumeAccountSwitchRefreshMessage()
        : outcome.message,
      nextPhase: "refresh",
      originFingerprint,
    };
  }
  return outcome;
}

async function refreshAfterConsumeSubmit(
  originFingerprint: string,
  originSession: string,
  transactionCount: number,
  submitted?: Extract<InventoryConsumeOutcome, { kind: "already_consumed" }>,
): Promise<InventoryConsumeOutcome> {
  // POST (or 409 already_consumed) already committed on the origin account.
  if (sessionMaterial() !== originSession) {
    return consumeSubmittedRefreshFailed(originFingerprint, true, transactionCount);
  }
  try {
    await refreshInventorySnapshot(originFingerprint, inventoryConsumeAccountSwitchRefreshMessage());
    if (sessionMaterial() !== originSession) {
      return consumeSubmittedRefreshFailed(originFingerprint, true, transactionCount);
    }
    return submitted ?? inventoryConsumeAfterPostRefreshOutcome(true, transactionCount);
  } catch (error) {
    const accountSwitched = isInventoryCalibrateRefreshError(error)
      || sessionMaterial() !== originSession
      || (error instanceof Error && /原账号/.test(error.message));
    return consumeSubmittedRefreshFailed(originFingerprint, accountSwitched, transactionCount);
  }
}

async function consumeProjectInventory(
  projectId: string,
  projectRevision: number,
  expectedOriginFingerprint?: string | null,
): Promise<InventoryConsumeOutcome> {
  if (state.status !== "synced") {
    return { kind: "blocked", message: "请先连接共享账号后再确认扣减库存", nextPhase: "idle" };
  }
  const project = state.activeProject;
  if (!project || project.id !== projectId) {
    return { kind: "blocked", message: "请先打开云端作品后再确认扣减库存", nextPhase: "idle" };
  }
  if (project.currentRevision !== projectRevision || projectRevision < 1) {
    return { kind: "revision_mismatch", message: "只能扣减当前图纸版本的库存。请重新打开作品后再确认。", nextPhase: "idle" };
  }
  // Capture session identity synchronously before any await; fingerprint the frozen material.
  const originSession = sessionMaterial();
  const originUserId = state.userId;
  const originFingerprint = await inventoryCalibrateSessionFingerprint(originSession);
  if (expectedOriginFingerprint && expectedOriginFingerprint !== originFingerprint) {
    return {
      kind: "retryable",
      message: "当前账号不是原账号，没有重试扣减。请切回原账号后再试。",
      nextPhase: "retryable",
      originFingerprint: expectedOriginFingerprint,
    };
  }
  if (sessionMaterial() !== originSession || state.userId !== originUserId) {
    return { kind: "retryable", message: "账号已切换，扣减未提交。请切回原账号后重试。", nextPhase: "retryable" };
  }
  try {
    // Submit stage: only POST failures enter interpretInventoryConsumeFailure.
    let transactionCount = 0;
    try {
      const result = await api.consumeProjectInventory(projectId, projectRevision);
      transactionCount = result.consumption.transactions?.length ?? 0;
    } catch (error) {
      const outcome = interpretInventoryConsumeFailure(
        error instanceof ApiError
          ? { code: error.code, message: error.message, status: error.status, details: error.details as { consumedAt?: string } }
          : error,
      );
      // 409 already consumed: submit landed on the origin account — refresh-only even if UI switched.
      if (outcome.kind === "already_consumed") {
        return refreshAfterConsumeSubmit(originFingerprint, originSession, 0, outcome);
      }
      if (sessionMaterial() !== originSession || state.userId !== originUserId) {
        return {
          kind: "retryable",
          message: "扣减请求结果未确认，账号已切换。请切回原账号后再重试确认，避免在其他账号重复提交。",
          nextPhase: "retryable",
          originFingerprint,
        };
      }
      return outcome;
    }
    // Refresh stage: POST already succeeded — never fall back to retryable/POST.
    return refreshAfterConsumeSubmit(originFingerprint, originSession, transactionCount);
  } catch (error) {
    // Unexpected errors before a confirmed POST stay retryable; after POST this path is unused.
    if (sessionMaterial() !== originSession || state.userId !== originUserId) {
      return {
        kind: "retryable",
        message: "扣减请求结果未确认，账号已切换。请切回原账号后再重试确认，避免在其他账号重复提交。",
        nextPhase: "retryable",
        originFingerprint,
      };
    }
    return interpretInventoryConsumeFailure(
      error instanceof ApiError
        ? { code: error.code, message: error.message, status: error.status, details: error.details as { consumedAt?: string } }
        : error,
    );
  }
}

async function calibrateInventoryBatch(preview: InventoryCalibratePreview): Promise<void> {
  if (state.status !== "synced") throw new Error("请先连接共享账号");
  if (state.activePalette?.id !== preview.paletteId) {
    throw new Error("当前色卡已变化，请重新预览后再确认");
  }
  const fingerprint = inventoryCalibrateFingerprint(accountKey(), preview.paletteId, state.inventory);
  if (!isInventoryCalibratePreviewCurrent(preview, fingerprint)) {
    throw new Error("库存、色卡或账号已变化，请重新预览后再确认");
  }
  const items = toInventoryCalibrateBatchItems(preview);
  if (!items.length) throw new Error("没有可校准的色号");
  const captured = sessionMaterial();
  const originFingerprint = await inventoryCalibrateSessionFingerprint(captured);
  if (sessionMaterial() !== captured) {
    throw new Error("账号已切换，校准未提交。请切回原账号后重新预览。");
  }
  const result = await api.applyInventoryBatch("calibrate", items);
  if (sessionMaterial() !== captured) {
    throw new InventoryCalibrateRefreshError(ACCOUNT_SWITCH_REFRESH_MESSAGE, originFingerprint);
  }
  mergeInventoryItems(result.items, result.transactions);
  try {
    await refreshInventorySnapshot(originFingerprint);
  } catch (error) {
    if (isInventoryCalibrateRefreshError(error)) throw error;
    throw new InventoryCalibrateRefreshError(
      error instanceof Error
        ? `校准已提交，但库存或流水刷新失败：${error.message}。请只重试刷新，不要再次提交。`
        : undefined,
      originFingerprint,
    );
  }
}

async function changePalette(paletteId: string, maxColors: number, confirmUnreliableLegacyMappings = false): Promise<ApiProject | null> {
  const palette = state.palettes.find((item) => item.id === paletteId);
  if (!palette) throw new Error("色卡不存在或无权访问");
  if (!state.activeProject) {
    state.activePalette = palette;
    return null;
  }
  const { project } = await api.remapProject(state.activeProject, paletteId, maxColors, false, confirmUnreliableLegacyMappings);
  state.activeProject = project;
  state.activePalette = palette;
  state.draftRevision = 0;
  state.projects = (await api.projects()).projects;
  return project;
}

export function useSharedWorkspace() {
  return {
    state,
    api,
    restore,
    refresh: hydrate,
    refreshPalettes: loadPaletteCatalog,
    ensureBundledPalette,
    connectDevelopment,
    adoptWebSession,
    logout,
    openProject,
    createProject,
    saveDraft,
    commitActiveDraft,
    refreshExports,
    refreshCredits,
    adjustInventory,
    updateInventoryLocation,
    calibrateInventoryBatch,
    consumeProjectInventory,
    refreshInventorySnapshot,
    changePalette,
  };
}
