import type { GalleryWork } from "./gallery-catalog";
import type { PatternGrid } from "./pixel-engine";

interface GalleryPatternPayload {
  schemaVersion: number;
  id: string;
  title: string;
  palette: { id: string; candidateColors: number };
  grid: { width: number; height: number; beadCount: number };
  cells: unknown[];
}

export function parseGalleryPattern(input: unknown, work: GalleryWork, validCodes: ReadonlySet<string>): PatternGrid {
  if (!input || typeof input !== "object") throw new Error("图纸数据格式无效");
  const value = input as Partial<GalleryPatternPayload>;
  if (value.schemaVersion !== 1 || value.id !== work.id || value.title !== work.title) {
    throw new Error("图纸目录与数据版本不一致");
  }
  if (value.palette?.id !== "mard-221-v1" || value.palette.candidateColors !== 221) {
    throw new Error("该图纸不是 221 色库数据");
  }
  if (value.grid?.width !== work.width || value.grid.height !== work.height
    || value.grid.beadCount !== work.beadCount || !Array.isArray(value.cells)
    || value.cells.length !== work.width * work.height) {
    throw new Error("图纸尺寸或格子数量不完整");
  }
  const cells = value.cells.map((code) => {
    if (typeof code !== "string" || !validCodes.has(code)) throw new Error(`图纸包含无效色号：${String(code)}`);
    return code;
  });
  return { width: work.width, height: work.height, cells };
}
