const DATABASE_NAME = "pindou-local-images";
const DATABASE_VERSION = 1;
const IMAGE_STORE = "drafts";
const SELECTED_IMAGE_KEY = "selected-source";

interface StoredImageDraft {
  blob: Blob;
  name: string;
  type: string;
  lastModified: number;
}

function openDatabase(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DATABASE_NAME, DATABASE_VERSION);
    request.onupgradeneeded = () => {
      if (!request.result.objectStoreNames.contains(IMAGE_STORE)) {
        request.result.createObjectStore(IMAGE_STORE);
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error("本地图片存储不可用"));
    request.onblocked = () => reject(new Error("本地图片存储正在升级，请关闭其他项目标签页后重试"));
  });
}

export async function saveLocalImageDraft(file: File): Promise<void> {
  const database = await openDatabase();
  try {
    await new Promise<void>((resolve, reject) => {
      const transaction = database.transaction(IMAGE_STORE, "readwrite");
      transaction.objectStore(IMAGE_STORE).put({
        blob: file,
        name: file.name,
        type: file.type,
        lastModified: file.lastModified,
      } satisfies StoredImageDraft, SELECTED_IMAGE_KEY);
      transaction.oncomplete = () => resolve();
      transaction.onerror = () => reject(transaction.error ?? new Error("本地图片保存失败"));
      transaction.onabort = () => reject(transaction.error ?? new Error("本地图片保存失败"));
    });
  } finally {
    database.close();
  }
}

export async function loadLocalImageDraft(): Promise<File | null> {
  const database = await openDatabase();
  try {
    const stored = await new Promise<StoredImageDraft | undefined>((resolve, reject) => {
      const request = database.transaction(IMAGE_STORE, "readonly")
        .objectStore(IMAGE_STORE)
        .get(SELECTED_IMAGE_KEY);
      request.onsuccess = () => resolve(request.result as StoredImageDraft | undefined);
      request.onerror = () => reject(request.error ?? new Error("本地图片读取失败"));
    });
    if (!stored?.blob || typeof stored.name !== "string") return null;
    return new File([stored.blob], stored.name, {
      type: stored.type || stored.blob.type || "application/octet-stream",
      lastModified: Number.isFinite(stored.lastModified) ? stored.lastModified : Date.now(),
    });
  } finally {
    database.close();
  }
}
