export type WebSaveVersionGate = {
  synced: boolean;
  busy: boolean;
  hasCloudProject: boolean;
  hasUnresolvedDraftIssue: boolean;
};

export type WebSaveVersionRetryGate = WebSaveVersionGate & { lastFailed: boolean };

export type WebSaveVersionFailureOutcome =
  | { kind: "retryable"; message: string }
  | { kind: "unauthorized"; message: string }
  | { kind: "conflict"; message: string };

export function canStartWebSaveVersion(gate: WebSaveVersionGate): boolean {
  return gate.synced && gate.hasCloudProject && !gate.busy && !gate.hasUnresolvedDraftIssue;
}

export function canRetryWebSaveVersion(gate: WebSaveVersionRetryGate): boolean {
  return canStartWebSaveVersion(gate) && gate.lastFailed;
}

export function webSaveVersionOfflineMessage(): string {
  return "请先连接共享账号并打开云端作品，再保存不可变版本。";
}

export function webSaveVersionDraftIssueMessage(): string {
  return "请先解决草稿同步问题，再保存版本。工作副本与同步队列未改动。";
}

export function webSaveVersionBusyMessage(): string {
  return "正在保存版本，请稍候。";
}

export function webSaveVersionConfirmMessage(projectName: string): string {
  const name = projectName.trim() || "当前作品";
  return `确定将「${name}」的当前草稿保存为不可变版本？保存后继续编辑会写入新的工作副本，不会改写已保存版本。`;
}

export function webSaveVersionAlreadyCurrentMessage(revision: number): string {
  const label = Number.isInteger(revision) && revision > 0 ? `版本 ${revision}` : "当前版本";
  return `${label} 已是最新，没有待提交的工作草稿。`;
}

export function webSaveVersionSuccessMessage(revision: number): string {
  return `已保存为不可变版本 ${revision}。后续编辑进入新的工作副本。`;
}

export function interpretWebSaveVersionFailure(error: unknown): WebSaveVersionFailureOutcome {
  const status = typeof error === "object" && error && "status" in error
    ? Number((error as { status?: unknown }).status)
    : NaN;
  const code = typeof error === "object" && error && "code" in error
    ? String((error as { code?: unknown }).code ?? "")
    : "";
  const message = error instanceof Error
    ? error.message
    : typeof error === "object" && error && "message" in error && typeof (error as { message?: unknown }).message === "string"
      ? (error as { message: string }).message
      : "保存版本失败";
  if (status === 401 || code === "UNAUTHORIZED" || code === "SESSION_REVOKED") {
    return {
      kind: "unauthorized",
      message: "共享会话已失效，版本未保存。请重新连接后再试；工作草稿仍保留。",
    };
  }
  if (
    status === 409
    || code === "DRAFT_CONFLICT"
    || code === "PROJECT_REVISION_CONFLICT"
    || code === "DRAFT_REVISION_CONFLICT"
  ) {
    return {
      kind: "conflict",
      message: "草稿或作品版本已在其他设备更新。请先解决冲突后再保存；本机工作副本未提交。",
    };
  }
  return {
    kind: "retryable",
    message: /网络|failed to fetch|timeout/i.test(message)
      ? "网络异常，版本尚未保存。工作草稿保留，可重试。"
      : `${message}。版本尚未保存，工作草稿保留，可重试。`,
  };
}

export function shouldKeepDraftOnSaveVersionFailure(outcome: WebSaveVersionFailureOutcome): boolean {
  return outcome.kind === "retryable" || outcome.kind === "conflict" || outcome.kind === "unauthorized";
}
