import type { PatternGrid } from "./pixel-engine";

export const CLOUD_PROJECT_MAX_EDGE = 200;
export const CLOUD_GENERATION_MAX_EDGE = 128;

export class CloudContractError extends Error {
  constructor(public readonly code: "PROJECT_GRID_TOO_LARGE" | "GENERATION_GRID_TOO_LARGE" | "INVALID_GRID_DIMENSIONS", message: string) {
    super(message);
    this.name = "CloudContractError";
  }
}

function validDimension(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value > 0;
}

export function assertCloudProjectGrid(grid: Pick<PatternGrid, "width" | "height">): void {
  if (!validDimension(grid.width) || !validDimension(grid.height)) {
    throw new CloudContractError("INVALID_GRID_DIMENSIONS", "图纸尺寸无效，已阻止云端提交");
  }
  if (grid.width > CLOUD_PROJECT_MAX_EDGE || grid.height > CLOUD_PROJECT_MAX_EDGE) {
    throw new CloudContractError(
      "PROJECT_GRID_TOO_LARGE",
      `云端普通作品单边最多 ${CLOUD_PROJECT_MAX_EDGE} 格；当前 ${grid.width}×${grid.height} 已保留在本机，未提交云端`,
    );
  }
}

export function assertCloudGenerationDimensions(payload: unknown): void {
  if (!payload || typeof payload !== "object") {
    throw new CloudContractError("INVALID_GRID_DIMENSIONS", "AI 图纸尺寸无效，已阻止远端请求");
  }
  const { width, height } = payload as { width?: unknown; height?: unknown };
  if (!validDimension(width) || !validDimension(height)) {
    throw new CloudContractError("INVALID_GRID_DIMENSIONS", "AI 图纸尺寸无效，已阻止远端请求");
  }
  if (width > CLOUD_GENERATION_MAX_EDGE || height > CLOUD_GENERATION_MAX_EDGE) {
    throw new CloudContractError(
      "GENERATION_GRID_TOO_LARGE",
      `远端 AI 图纸单边最多 ${CLOUD_GENERATION_MAX_EDGE} 格；请求未发送`,
    );
  }
}

export function cloudProjectGridCompatible(grid: Pick<PatternGrid, "width" | "height">): boolean {
  return validDimension(grid.width)
    && validDimension(grid.height)
    && grid.width <= CLOUD_PROJECT_MAX_EDGE
    && grid.height <= CLOUD_PROJECT_MAX_EDGE;
}

export function compatibleAiLongSide(requested: number): number {
  const normalized = Number.isFinite(requested) ? Math.round(requested) : CLOUD_GENERATION_MAX_EDGE;
  return Math.max(24, Math.min(CLOUD_GENERATION_MAX_EDGE, normalized));
}
