const undo=shallowRef<Uint8Array[]>([]),redo=shallowRef<Uint8Array[]>([]);
const grid=shallowRef<PatternGrid|null>(null),project=shallowRef<ApiProject|null>(null),job=shallowRef<ApiGenerationJob|null>(null);
