const subjectPrepared=ref(false);
const manualQuality=ref(false);
const recommendation=computed(()=>raster.value&&mask.value?recommendSubjectQuality(raster.value,mask.value):null);
const projectName=ref('我的主体拼豆'),chargeKey=ref(''),chargeOwner=ref('');
const frozenCharge=shallowRef<{name:string;paletteId:string;grid:PatternGrid;mode:'normal'|'pixel'}|null>(null);
const aiCreateKey=ref(''),aiCreatePayload=shallowRef<Record<string,unknown>|null>(null),uploadKey=ref(''),aiAssetId=ref('');
const acceptingKey=ref(''),disposed=ref(false),restoring=ref(false);
const acceptingPayload=shallowRef<{variant:number;projects:Array<{outputSlot:string;projectName:string}>}|null>(null);
let painting=false,paintOrigin:Uint8Array|null=null,paintChanged=false,draftTimer:ReturnType<typeof setTimeout>|undefined;
let lastX=0,lastY=0;
const pixelsCount=computed(()=>grid.value?.cells.filter(Boolean).length??0);
const colorsCount=computed(()=>new Set(grid.value?.cells.filter(Boolean)??[]).size);
