const cost=computed(()=>mode.value==='ai'?3:1);

function notice(text:string){message.value=text;emit('notice',text)}
function presets(size:number,colors:number){manualQuality.value=true;gridSize.value=size;maxColors.value=colors}
function adoptRecommendation(){if(!recommendation.value)return;gridSize.value=recommendation.value.size;maxColors.value=recommendation.value.maxColors;manualQuality.value=false}
function openDraftDb():Promise<IDBDatabase>{return new Promise((resolve,reject)=>{const request=indexedDB.open('pindou-subject-draft-v1',1);request.onupgradeneeded=()=>request.result.createObjectStore('drafts');request.onerror=()=>reject(request.error);request.onsuccess=()=>resolve(request.result)})}
async function writeDraft(){
  if(restoring.value||!raster.value||!mask.value||!sourceFile.value)return false;
  try{
    const db=await openDraftDb();
    const data={version:1,source:sourceFile.value,variant:variant.value,manualQuality:manualQuality.value,mode:mode.value,owner:chargeOwner.value,paletteId:props.paletteId,layers:layers.value,selected:selected.value,subjectPrepared:subjectPrepared.value,mask:encodeMask(mask.value),width:raster.value.width,height:raster.value.height,framing:framing.value,style:style.value,size:gridSize.value,maxColors:maxColors.value,outline:outline.value,offsetX:offsetX.value,offsetY:offsetY.value,name:projectName.value,project:project.value,grid:grid.value,job:job.value,chargeKey:chargeKey.value,frozenCharge:frozenCharge.value,aiCreateKey:aiCreateKey.value,aiCreatePayload:aiCreatePayload.value,uploadKey:uploadKey.value,aiAssetId:aiAssetId.value,acceptingKey:acceptingKey.value,acceptingPayload:acceptingPayload.value};
