    const plain={...JSON.parse(JSON.stringify(data)),source:sourceFile.value,aiPreviews:Object.entries(aiPreviews.value).filter(([,value])=>value.file).map(([ordinal,value])=>({ordinal:Number(ordinal),file:value.file}))};
    await new Promise<void>((resolve,reject)=>{const tx=db.transaction('drafts','readwrite');tx.objectStore('drafts').put(plain,'current');if(project.value)tx.objectStore('drafts').put(plain,'project:'+project.value.id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)});db.close();draftWarning.value='';return true;
