}
function scheduleDraft(){if(draftTimer)clearTimeout(draftTimer);draftTimer=setTimeout(()=>void writeDraft(),250)}
async function readRaster(file:File){
  const bitmap=await createImageBitmap(file);
  const factor=Math.min(1,1024/Math.max(bitmap.width,bitmap.height));
  const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*factor));canvas.height=Math.max(1,Math.round(bitmap.height*factor));
  const ctx=canvas.getContext('2d',{willReadFrequently:true})!;ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();
  return {width:canvas.width,height:canvas.height,pixels:ctx.getImageData(0,0,canvas.width,canvas.height).data};
}
async function chooseImage(event:Event){
  const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;
  if(busy.value){notice('当前任务尚未结束，请稍后更换图片');return}
  if(file.size>10*1024*1024){notice('图片请小于10MB');return}
  if(frozenCharge.value||aiCreateKey.value&&!job.value){notice('上一次生成结果尚未确认，请先重试恢复结果，再更换图片');return}
  try{raster.value=await readRaster(file);sourceFile.value=file;mask.value=Uint8Array.from({length:raster.value.width*raster.value.height},(_,index)=>raster.value!.pixels[index*4+3]);subjectPrepared.value=mask.value.some(value=>value<128);manualQuality.value=false;layers.value=[];selected.value=[];grid.value=null;project.value=null;job.value=null;aiPreviews.value={};chargeKey.value='';chargeOwner.value='';aiCreateKey.value='';aiCreatePayload.value=null;aiAssetId.value='';uploadKey.value='';acceptingKey.value='';undo.value=[];redo.value=[];offsetX.value=0;offsetY.value=0;framing.value='full';view.value='source';notice('图片已就绪，可识别主体，也可用擦除／保留画笔手动修补');await nextTick();drawPreview();scheduleDraft()}catch{notice('图片无法读取，请换用JPG、PNG或WebP')}
}
async function identify(){
  if(!sourceFile.value||busy.value)return;
  if(!consent.value){notice('请先同意将图片用于主体识别；不需要登录，也不会扣生成次数');return}
  busy.value=true;notice('正在识别人物、动物、物品和植物…');
  try{const policy=await shared.api.privacyConsent();const result=await shared.api.extractSubjects(sourceFile.value,policy.consentVersion);layers.value=result.subjects;const preferred=result.subjects.find(item=>item.category==='person'||item.category==='animal')??result.subjects[0];selected.value=preferred?[preferred.id]:[];selectSubjects();view.value='subject';notice(`识别到${layers.value.length}个主体，可选择保留一个或多个并修补轮廓`)}catch(error){notice(error instanceof Error?error.message:'主体识别失败，仍可手动修补')}finally{busy.value=false;scheduleDraft()}
}
function selectSubjects(){if(!raster.value)return;mask.value=combineSubjectMasks(raster.value.width,raster.value.height,layers.value,selected.value);subjectPrepared.value=selected.value.length>0;if(!manualQuality.value&&!project.value&&!job.value)adoptRecommendation();undo.value=[];redo.value=[];drawPreview();updateExistingGrid();scheduleDraft()}
function toggleSubject(id:string){selected.value=selected.value.includes(id)?selected.value.filter(value=>value!==id):[...selected.value,id];selectSubjects()}
function keepWhole(){if(!raster.value)return;subjectPrepared.value=true;mask.value=new Uint8Array(raster.value.width*raster.value.height).fill(255);selected.value=[];undo.value=[];redo.value=[];view.value='source';drawPreview();updateExistingGrid();scheduleDraft()}
function drawPreview(){
