  node.width=data.width;node.height=data.height;
  const context=node.getContext('2d')!;context.putImageData(new ImageData(view.value==='source'?new Uint8ClampedArray(data.pixels):applySubjectAlpha(data.pixels,mask.value),data.width,data.height),0,0);
  try{const bounds=framedSubjectBounds(mask.value,data.width,data.height,framing.value,offsetX.value,offsetY.value);context.strokeStyle='#16815d';context.lineWidth=3;context.strokeRect(bounds.left,bounds.top,bounds.width,bounds.height)}catch{}
}
function drawResult(){
  const data=grid.value,node=resultPreview.value;if(!data||!node)return;
  const unit=Math.max(4,Math.round(384/data.width*zoom.value/100));node.width=data.width*unit;node.height=data.height*unit;
  const ctx=node.getContext('2d')!;ctx.clearRect(0,0,node.width,node.height);ctx.font=`${Math.max(5,unit*.35)}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';
  data.cells.forEach((code,index)=>{if(!code)return;const x=index%data.width,y=Math.floor(index/data.width),hex=colorMap.value.get(code)??'#777777';ctx.fillStyle=hex;ctx.fillRect(x*unit,y*unit,unit-1,unit-1);if(unit>=14){const n=parseInt(hex.slice(1),16);ctx.fillStyle=.299*(n>>16)+.587*((n>>8)&255)+.114*(n&255)>145?'#17212a':'#ffffff';ctx.fillText(code,(x+.5)*unit,(y+.5)*unit)}});
