}
function pointer(event:PointerEvent){const node=preview.value!,bounds=node.getBoundingClientRect();return {x:(event.clientX-bounds.left)*node.width/bounds.width,y:(event.clientY-bounds.top)*node.height/bounds.height}}
function startPaint(event:PointerEvent){if(!mask.value||busy.value||tool.value==='pan')return;painting=true;paintChanged=false;paintOrigin=new Uint8Array(mask.value);const p=pointer(event);lastX=p.x;lastY=p.y;preview.value?.setPointerCapture(event.pointerId);applyPaint(event)}
function applyPaint(event:PointerEvent){if(!painting||!raster.value||!mask.value)return;const p=pointer(event);if(tool.value==='move'){offsetX.value=Math.max(-.5,Math.min(.5,offsetX.value+(p.x-lastX)/raster.value.width));offsetY.value=Math.max(-.5,Math.min(.5,offsetY.value+(p.y-lastY)/raster.value.height));lastX=p.x;lastY=p.y;paintChanged=true;return}paintMask(mask.value,raster.value.width,raster.value.height,p.x,p.y,brush.value,tool.value==='keep');paintChanged=true;subjectPrepared.value=true;view.value='subject';drawPreview()}
function finishPaint(){if(!painting)return;painting=false;if(paintChanged&&paintOrigin&&tool.value!=='move'){undo.value=[...undo.value.slice(-11),paintOrigin];redo.value=[]}paintOrigin=null;updateExistingGrid();scheduleDraft()}
function undoMask(){const prior=undo.value[undo.value.length-1];if(!prior||!mask.value)return;redo.value=[...redo.value,new Uint8Array(mask.value)];undo.value=undo.value.slice(0,-1);mask.value=prior;drawPreview();updateExistingGrid();scheduleDraft()}
function redoMask(){const next=redo.value[redo.value.length-1];if(!next||!mask.value)return;undo.value=[...undo.value,new Uint8Array(mask.value)];redo.value=redo.value.slice(0,-1);mask.value=next;drawPreview();updateExistingGrid();scheduleDraft()}
function localGrid(){if(!raster.value||!mask.value)throw new Error('请先选择图片');return subjectToGrid({raster:raster.value,mask:mask.value,framing:framing.value,size:gridSize.value,maxColors:maxColors.value,palette:props.palette,pixelMode:mode.value==='pixel',outline:outline.value,offsetX:offsetX.value,offsetY:offsetY.value})}
function updateExistingGrid(){
  if(busy.value)return;
  try{
    if(mode.value==='ai'&&job.value&&['completed','accepted'].includes(job.value.status)){
      const source=aiPreviews.value[variant.value]?.raster??(grid.value?rasterFromGrid(grid.value,props.palette):null);
      if(source)grid.value=subjectToGrid({raster:source,mask:rasterAlpha(source),framing:'full',size:gridSize.value,maxColors:maxColors.value,palette:props.palette,outline:outline.value});
    }else if(project.value)grid.value=localGrid();
    nextTick(drawResult);
  }catch(error){notice(error instanceof Error?error.message:'无法调整图纸')}
}
function checkAccount(){if(shared.state.status!=='synced'){notice('生成前请连接账号，领取9次赠送和每日1次');emit('login');return false}if(chargeOwner.value&&chargeOwner.value!==shared.state.userId){notice('此草稿的付费结果属于原账号，请切回原账号后恢复');return false}return true}
async function generate(){
  if(busy.value||!raster.value||!mask.value||!props.palette.length)return;
  if(!subjectPrepared.value&&!frozenCharge.value&&!project.value&&!job.value){notice('请先识别并选择主体，或手动修补轮廓；也可以明确选择保留完整图片。本次尚未扣次。');return}
  if(!checkAccount())return;
  if(mode.value==='ai'){
    if(project.value&&grid.value){busy.value=true;try{project.value=(await shared.api.saveConvertedGrid(project.value,grid.value)).project;await writeDraft();notice('已保存图纸调整，没有再次扣次')}catch(error){notice(error instanceof Error?error.message:'保存未完成')}finally{busy.value=false}return}
    await generateAi();return
  }
  busy.value=true;
  try{
    if(!project.value){
      if(!frozenCharge.value){frozenCharge.value={name:projectName.value,paletteId:props.paletteId,grid:localGrid(),mode:mode.value==='pixel'?'pixel':'normal'};chargeKey.value=crypto.randomUUID();chargeOwner.value=shared.state.userId}
      if(!await writeDraft())throw new Error('未能安全保存请求，尚未扣次');
      const result=await shared.api.createLocalConversion(frozenCharge.value,chargeKey.value);project.value=result.project;grid.value=result.project.grid;frozenCharge.value=null;chargeKey.value='';shared.state.credits=(await shared.api.credits() as {account:{balance:number}}).account.balance;notice('图纸已生成并保存，消耗1次；后续调整不重复扣次');
    }else{grid.value??=localGrid();const result=await shared.api.saveConvertedGrid(project.value,grid.value);project.value=result.project;notice('已保存调整，没有再次扣次')}
    await nextTick();drawResult();await writeDraft();
  }catch(error){if((error as {code?:string})?.code==='INSUFFICIENT_CREDITS'){frozenCharge.value=null;chargeKey.value=''}notice(error instanceof Error?`${error.message}；重试会恢复同一请求，不重复扣次`:'保存失败，草稿已保留')}finally{busy.value=false;await writeDraft()}
}
async function subjectFile():Promise<File>{
  const data=raster.value!,alpha=mask.value!,bounds=framedSubjectBounds(alpha,data.width,data.height,framing.value,offsetX.value,offsetY.value);
  const canvas=document.createElement('canvas');canvas.width=data.width;canvas.height=data.height;canvas.getContext('2d')!.putImageData(new ImageData(applySubjectAlpha(data.pixels,alpha),data.width,data.height),0,0);
  const target=document.createElement('canvas');target.width=1024;target.height=1024;const ctx=target.getContext('2d')!,scale=960/Math.max(bounds.width,bounds.height);
  ctx.drawImage(canvas,bounds.left,bounds.top,bounds.width,bounds.height,(1024-bounds.width*scale)/2,(1024-bounds.height*scale)/2,bounds.width*scale,bounds.height*scale);
  const blob=await new Promise<Blob>((resolve,reject)=>target.toBlob(value=>value?resolve(value):reject(new Error('无法保存透明主体')),'image/png'));
  return new File([blob],'subject.png',{type:'image/png'});
}
async function generateAi(){
  if(!consent.value){notice('请先同意素材用于AI处理');return}
  if(job.value&&['completed','accepted'].includes(job.value.status)){notice('已有两个方案，可调整图纸参数或继续精修；重新生成请使用下方3次按钮');return}
