  try{
    if(job.value&&['queued','preprocessing','generating','mapping_colors','finalizing','retry_wait'].includes(job.value.status)){await pollAi();return}
    if(!aiCreatePayload.value){
      chargeOwner.value=shared.state.userId;const policy=await shared.api.privacyConsent();uploadKey.value||=crypto.randomUUID();if(!await writeDraft())throw new Error('未能安全保存请求，尚未上传或扣次');
      if(!aiAssetId.value){const upload=await shared.api.uploadAiSource(await subjectFile(),policy.consentVersion,uploadKey.value);aiAssetId.value=upload.asset.id;await writeDraft()}
      aiCreateKey.value=crypto.randomUUID();aiCreatePayload.value={kind:'portrait',paletteId:props.paletteId,sourceAssetId:aiAssetId.value,width:gridSize.value,height:gridSize.value,options:{subjectStyle:style.value,subjectFraming:framing.value,transparentBackground:true,removeBackground:false,maxColors:maxColors.value,crop:{ratio:'original',rotation:0,scale:1,offsetX:0,offsetY:0,flipX:false,flipY:false}}};
    }
    if(!await writeDraft())throw new Error('未能安全保存请求，尚未扣次');
    const created=await shared.api.createGenerationJob(aiCreatePayload.value,aiCreateKey.value);job.value=created.job;aiCreatePayload.value=null;aiCreateKey.value='';await writeDraft();await pollAi();
  }catch(error){notice(error instanceof Error?error.message:'AI生成未完成，请恢复原任务')}finally{busy.value=false;await writeDraft()}
}
async function pollAi(){
  for(let i=0;i<240&&!disposed.value;i++){
    if(!job.value)return;const result=await shared.api.generationJob(job.value.id);job.value=result.job;await writeDraft();
    if(job.value.status==='completed'||job.value.status==='accepted'){await loadAiPreviews();selectVariant(1);await shared.refreshCredits();notice('两个方案已生成，任选一个；调图纸参数和编辑不重复收费');return}
    if(job.value.status==='failed'||job.value.status==='canceled'){await shared.refreshCredits();throw new Error('AI任务未成功，次数按服务端状态退回，可重新生成')}
    notice(`AI正在处理 ${job.value.progress}%`);await new Promise(resolve=>setTimeout(resolve,1000));
  }
  notice('任务仍在服务端处理，草稿已保存；回来可恢复原任务，不重复创建');
}
async function loadAiPreviews(){
  if(!job.value)return;
  for(const item of job.value.variants){const output=item.outputs[0];if(!output)continue;if(aiPreviews.value[item.variantOrdinal])continue;
    try{if(!output.previewAssetId)throw new Error('no-preview');const blob=await shared.api.assetContent(output.previewAssetId),file=new File([blob],'ai-preview.png',{type:'image/png'});aiPreviews.value={...aiPreviews.value,[item.variantOrdinal]:{file,raster:await readRaster(file)}}}
    catch{aiPreviews.value={...aiPreviews.value,[item.variantOrdinal]:{raster:rasterFromGrid(output.grid,props.palette)}}}
  }
}
function selectVariant(value:number){variant.value=value;const output=job.value?.variants.find(item=>item.variantOrdinal===value)?.outputs[0];if(output){grid.value=output.grid;const source=aiPreviews.value[value]?.raster;if(source)grid.value=subjectToGrid({raster:source,mask:rasterAlpha(source),framing:'full',size:gridSize.value,maxColors:maxColors.value,palette:props.palette,outline:outline.value});nextTick(drawResult);scheduleDraft()}}
async function redrawAi(){
  if(!job.value||busy.value||!checkAccount())return;
  if(!window.confirm('重新生成两个方案会再次消耗3次，继续吗？'))return;
  busy.value=true;
  try{const result=await shared.api.redrawGeneration(job.value.id);job.value=result.job;aiPreviews.value={};project.value=null;acceptingKey.value='';await writeDraft();await pollAi()}catch(error){notice(error instanceof Error?error.message:'重新生成失败')}finally{busy.value=false;await writeDraft()}
}
async function continueEditing(){
  if(busy.value||!checkAccount()||!grid.value)return;
  busy.value=true;
  try{
    if(mode.value==='ai'&&job.value&&!project.value){
      if(!acceptingPayload.value){const selectedVariant=job.value.variants.find(item=>item.variantOrdinal===variant.value);if(!selectedVariant)throw new Error('请选择有效方案');acceptingKey.value=crypto.randomUUID();acceptingPayload.value={variant:variant.value,projects:selectedVariant.outputs.map(output=>({outputSlot:output.outputSlot,projectName:projectName.value}))}}
      if(!await writeDraft())throw new Error('未能安全保存采用请求，请重试');
      const result=await shared.api.acceptGenerationVariant(job.value.id,acceptingPayload.value.variant,acceptingPayload.value.projects,acceptingKey.value);project.value=result.variant.outputs[0]?.project??null;job.value=result.job;acceptingKey.value='';acceptingPayload.value=null;
    }
    if(project.value){project.value=(await shared.api.saveConvertedGrid(project.value,grid.value)).project}
    if(!project.value)throw new Error('请先生成并保存图纸');await writeDraft();await shared.refresh();emit('created',project.value.id);
  }catch(error){notice(error instanceof Error?error.message:'作品未能打开')}finally{busy.value=false}
}
function deleteRegion(region:number[]){if(!grid.value)return;const cells=grid.value.cells.slice();region.forEach(index=>cells[index]=null);grid.value={...grid.value,cells};nextTick(drawResult);scheduleDraft()}
function connectRegion(){notice('请点击“继续精修”进入编辑器，用画笔连接橙色标记区域；也可以保留独立配饰')}
