import { CLOUD_PROJECT_MAX_EDGE } from "./cloud-contract";
import type { PatternGrid } from "./pixel-engine";

export type CreateMode = "normal" | "pixel" | "portrait" | "couple";
export type CreationProfile = CreateMode | "quick";

export interface CreationDefaults {
  paletteId: "mard-48-v1" | "mard-221-v1" | "mard-291-v1";
  maxColors: 16 | 24 | 32;
}

const CREATION_DEFAULTS: Record<CreationProfile, CreationDefaults> = {
  quick: { paletteId: "mard-48-v1", maxColors: 16 },
  normal: { paletteId: "mard-221-v1", maxColors: 24 },
  pixel: { paletteId: "mard-221-v1", maxColors: 24 },
  portrait: { paletteId: "mard-291-v1", maxColors: 32 },
  couple: { paletteId: "mard-291-v1", maxColors: 32 },
};

/** Returns a copy so callers cannot mutate the product contract. */
export function creationDefaults(profile: CreationProfile): CreationDefaults {
  return { ...CREATION_DEFAULTS[profile] };
}

/**
 * The account can retain a last-opened cloud project while the canvas contains
 * an independent browser-only draft. Only an exact target match within the
 * cloud size contract is allowed to use project/build APIs.
 */
export function cloudWorkspaceProjectId(
  draftTargetId: string | null,
  activeProjectId: string | null,
  grid: Pick<PatternGrid, "width" | "height">,
): string | null {
  if (!draftTargetId || draftTargetId !== activeProjectId) return null;
  if (grid.width > CLOUD_PROJECT_MAX_EDGE || grid.height > CLOUD_PROJECT_MAX_EDGE) return null;
  return draftTargetId;
}

/** A local draft remains visible even when the connected account has projects. */
export function mergeLocalAndRemote<T extends { id: string }>(local: readonly T[], remote: readonly T[]): T[] {
  const localIds = new Set(local.map((item) => item.id));
  return [...local, ...remote.filter((item) => !localIds.has(item.id))];
}

export interface PaletteIdentity {
  id: string;
  version: number;
  colors: ReadonlyArray<{ code: string }>;
}

/** Restore by the persisted identity; never silently substitute the default palette. */
export function storedDraftPaletteId(
  saved: { paletteId?: string | null; paletteVersion?: number | null },
  palettes: readonly PaletteIdentity[],
): string | null {
  if (!saved.paletteId) return null;
  const palette = palettes.find((item) => item.id === saved.paletteId);
  if (!palette) return null;
  return palette.id;
}

export function gridUsesOnlyPaletteCodes(grid: PatternGrid, palette: Pick<PaletteIdentity, "colors">): boolean {
  const codes = new Set(palette.colors.map((color) => color.code));
  return grid.cells.every((code) => code === null || codes.has(code));
}

export interface LegacyPaletteConfirmationDetails {
  migrationVersion: string;
  targetPaletteId: string;
  mappings: Array<{
    oldCode: string;
    newCode: string;
    deltaE2000: number;
    reliable: boolean;
  }>;
}

export function parseLegacyPaletteConfirmationDetails(details: unknown): LegacyPaletteConfirmationDetails | null {
  if (!details || typeof details !== "object") return null;
  const value = details as Partial<LegacyPaletteConfirmationDetails>;
  if (typeof value.migrationVersion !== "string" || typeof value.targetPaletteId !== "string" || !Array.isArray(value.mappings)) return null;
  const mappings = value.mappings.filter((mapping): mapping is LegacyPaletteConfirmationDetails["mappings"][number] => Boolean(
    mapping
    && typeof mapping.oldCode === "string"
    && typeof mapping.newCode === "string"
    && typeof mapping.deltaE2000 === "number"
    && typeof mapping.reliable === "boolean",
  ));
  if (mappings.length !== value.mappings.length) return null;
  return { migrationVersion: value.migrationVersion, targetPaletteId: value.targetPaletteId, mappings };
}

export function legacyPaletteConfirmationMessage(details: LegacyPaletteConfirmationDetails): string {
  const rows = details.mappings.map((mapping) => `${mapping.oldCode}→${mapping.newCode} (ΔE ${mapping.deltaE2000.toFixed(2)})`).join("、");
  return `迁移版本：${details.migrationVersion}\n目标色卡：${details.targetPaletteId}\n差异较大的映射：${rows}\n\n是否明确确认并创建新版本？`;
}
