export type MiniInventoryPhase = "idle" | "busy" | "retryable" | "refresh";

export type MiniInventoryGate = {
  synced: boolean;
  busy: boolean;
  phase: MiniInventoryPhase;
  loadFailed: boolean;
};

export type MiniInventoryItem = {
  paletteId: string;
  colorCode: string;
  quantity: number;
  location: string | null;
  revision: number;
};

export type MiniInventoryWriteKind = "delta" | "location";

export type MiniInventoryWriteOutcome =
  | { kind: "ok"; message: string; nextPhase: "idle" }
  | { kind: "refresh_failed"; message: string; nextPhase: "refresh"; originFingerprint?: string }
  | { kind: "retryable"; message: string; nextPhase: "retryable" }
  | { kind: "blocked"; message: string; nextPhase: MiniInventoryPhase };

/** Normalize a user-entered inventory location for the shared batch/PUT contract. */
export function normalizeInventoryLocation(raw: string | null | undefined): string | null {
  if (raw == null) return null;
  const trimmed = raw.trim();
  return trimmed.length > 0 ? trimmed.slice(0, 100) : null;
}

export function inventoryMaintainRefreshFailureMessage(kind: MiniInventoryWriteKind): string {
  return kind === "location"
    ? "仓位已提交，豆仓与流水尚未刷新成功。请只刷新库存和流水，不要再次提交仓位。"
    : "库存增减已提交，豆仓与流水尚未刷新成功。请只刷新库存和流水，不要再次增减。";
}

export function inventoryMaintainUnsyncedMessage(): string {
  return "请先连接共享账号后再查看或改动豆仓。";
}

export function inventoryMaintainSuccessMessage(kind: MiniInventoryWriteKind): string {
  return kind === "location" ? "仓位已保存，豆仓与流水已刷新。" : "库存已更新，豆仓与流水已刷新。";
}

export function miniProfileMenuAction(label: string): "open-inventory" | "open-exports" | "open-palettes" | "open-invite" | "stub" {
  if (label === "我的豆仓") return "open-inventory";
  if (label === "导出记录") return "open-exports";
  if (label === "常用色卡") return "open-palettes";
  if (label === "邀请好友") return "open-invite";
  return "stub";
}

export function canLoadMiniInventory(gate: MiniInventoryGate): boolean {
  return gate.synced && !gate.busy;
}

export function canRetryMiniInventoryLoad(gate: MiniInventoryGate): boolean {
  return gate.synced && !gate.busy && gate.loadFailed;
}

export function canWriteMiniInventory(gate: MiniInventoryGate): boolean {
  return gate.synced && !gate.busy && gate.phase !== "refresh" && !gate.loadFailed;
}

export function shouldSendInventoryMaintainWrite(gate: MiniInventoryGate, _kind: MiniInventoryWriteKind): boolean {
  return canWriteMiniInventory(gate);
}

export function canRetryInventoryMaintainRefresh(gate: Pick<MiniInventoryGate, "synced" | "busy" | "phase">): boolean {
  return gate.synced && !gate.busy && gate.phase === "refresh";
}

export function inventoryMaintainAfterWriteRefreshOutcome(
  refreshOk: boolean,
  kind: MiniInventoryWriteKind,
  originFingerprint?: string,
): Extract<MiniInventoryWriteOutcome, { kind: "ok" | "refresh_failed" }> {
  if (refreshOk) {
    return { kind: "ok", message: inventoryMaintainSuccessMessage(kind), nextPhase: "idle" };
  }
  return {
    kind: "refresh_failed",
    message: inventoryMaintainRefreshFailureMessage(kind),
    nextPhase: "refresh",
    originFingerprint,
  };
}

type MaintainErrorLike = { code?: string; message?: string; status?: number };

export function interpretInventoryMaintainWriteFailure(error: MaintainErrorLike | Error | unknown): Extract<MiniInventoryWriteOutcome, { kind: "retryable" }> {
  const code = typeof error === "object" && error && "code" in error
    ? String((error as MaintainErrorLike).code ?? "")
    : "";
  const message = error instanceof Error
    ? error.message
    : typeof error === "object" && error && "message" in error && typeof (error as MaintainErrorLike).message === "string"
      ? (error as MaintainErrorLike).message!
      : "库存写入失败";
  if (code === "INVENTORY_REVISION_CONFLICT" || (typeof error === "object" && error && "status" in error && (error as MaintainErrorLike).status === 409)) {
    return {
      kind: "retryable",
      message: "库存已在其他设备更新，本次未提交。请刷新后再重试。",
      nextPhase: "retryable",
    };
  }
  return {
    kind: "retryable",
    message: /网络|failed to fetch|timeout/i.test(message)
      ? "网络异常，库存尚未提交。可重试。"
      : `${message}。库存尚未提交，可重试。`,
    nextPhase: "retryable",
  };
}

export function mergeMiniInventoryItems(current: MiniInventoryItem[], incoming: MiniInventoryItem[]): MiniInventoryItem[] {
  const next = current.map((item) => ({ ...item }));
  for (const item of incoming) {
    const index = next.findIndex((row) => row.paletteId === item.paletteId && row.colorCode === item.colorCode);
    if (index >= 0) next[index] = { ...item };
    else next.push({ ...item });
  }
  return next;
}

export function miniInventoryPositiveLineCount(items: MiniInventoryItem[]): number {
  return items.filter((item) => item.quantity > 0 && item.paletteId && item.colorCode).length;
}

export function inventoryMaintainLedgerLabel(type: string): string {
  if (type === "calibration") return "批量校准";
  if (type === "manual_adjustment") return "手工调整";
  if (type === "project_consumption") return "作品扣减";
  return type;
}
