/**
 * Client interpretation of Ark/provider generation failures.
 * HTTP paths use the Fastify envelope `retryable` flag when present.
 * Job terminal paths use `errorCode` (API exposes code + message; not a retryable field).
 */

export type GenerationFailureKind = "retryable" | "permanent" | "canceled";

export type GenerationFailureOutcome = {
  kind: GenerationFailureKind;
  message: string;
  /** Whether the UI should offer an immediate "重新生成" action. */
  canRetry: boolean;
  code: string | null;
};

const PERMANENT_GENERATION_CODES = new Set([
  "GENERATION_PROVIDER_REJECTED",
  "GENERATION_PROVIDER_RESPONSE_INVALID",
  "GENERATION_SOURCE_ASSET_NOT_FOUND",
  "GENERATION_SOURCE_ASSET_UNAVAILABLE",
  "GENERATION_SOURCE_ASSET_CORRUPTED",
  "GENERATION_SOURCE_REQUIRED",
  "GENERATION_SOURCE_TOO_LARGE",
  "GENERATION_SOURCE_FORMAT_UNSUPPORTED",
  "GENERATION_SOURCE_ANIMATED_UNSUPPORTED",
  "GENERATION_SOURCE_DIMENSIONS_EXCEEDED",
  "GENERATION_SOURCE_DECODE_FAILED",
  "GENERATION_SOURCE_TRANSFORM_FAILED",
  "GENERATION_CROP_INVALID",
  "GENERATION_CROP_OUTSIDE_SOURCE",
  "GENERATION_TARGET_SIZE_INVALID",
  "GENERATION_MAX_COLORS_INVALID",
  "GENERATION_RASTER_MODE_UNSUPPORTED",
  "GENERATION_PALETTE_INVALID",
  "GENERATION_CANDIDATES_INVALID",
  "GENERATION_CANDIDATE_LIMIT_EXCEEDED",
  "GENERATION_INVENTORY_EMPTY",
  "GENERATION_COLOR_LIMIT_EXCEEDED",
  "GENERATION_INVENTORY_CONSTRAINT_VIOLATED",
  "PALETTE_NOT_FOUND",
  "INVALID_GRID_ENCODING",
  "INVALID_GRID_SIZE",
  "INVALID_GRID_CELLS",
  "UNKNOWN_PALETTE_COLOR",
]);

export type GenerationHttpFailureInput = {
  status?: number;
  code?: string | null;
  message?: string | null;
  retryable?: boolean;
};

export type GenerationJobFailureInput = {
  status?: string | null;
  errorCode?: string | null;
  errorMessage?: string | null;
};

function asMessage(value: string | null | undefined, fallback: string): string {
  return typeof value === "string" && value.trim() ? value.trim() : fallback;
}

export function interpretGenerationHttpFailure(
  input: GenerationHttpFailureInput | Error | unknown,
): GenerationFailureOutcome {
  if (input instanceof Error) {
    const status = "status" in input && typeof (input as { status?: unknown }).status === "number"
      ? (input as { status: number }).status
      : undefined;
    const code = "code" in input && typeof (input as { code?: unknown }).code === "string"
      ? (input as { code: string }).code
      : null;
    const retryable = "retryable" in input && typeof (input as { retryable?: unknown }).retryable === "boolean"
      ? (input as { retryable: boolean }).retryable
      : undefined;
    return interpretGenerationHttpFailure({
      status,
      code,
      message: input.message,
      retryable,
    });
  }

  const record = input && typeof input === "object"
    ? input as GenerationHttpFailureInput
    : {};
  const code = record.code ?? null;
  const message = asMessage(record.message, "AI 请求失败");
  if (code && PERMANENT_GENERATION_CODES.has(code)) {
    return {
      kind: "permanent",
      code,
      canRetry: false,
      message: `${message}。请调整照片或设置后再试，当前请求不会自动重试。`,
    };
  }
  if (typeof record.retryable === "boolean") {
    return record.retryable
      ? {
        kind: "retryable",
        code,
        canRetry: true,
        message: /可稍后|请稍后|暂时/.test(message) ? message : `${message}。可稍后重试。`,
      }
      : {
        kind: "permanent",
        code,
        canRetry: false,
        message: `${message}。请调整后重试，当前请求不会自动重试。`,
      };
  }
  const status = typeof record.status === "number" ? record.status : NaN;
  if (Number.isFinite(status) && status >= 500) {
    return {
      kind: "retryable",
      code,
      canRetry: true,
      message: /可稍后|请稍后|暂时/.test(message) ? message : `${message}。可稍后重试。`,
    };
  }
  if (Number.isFinite(status) && status >= 400 && status < 500) {
    return {
      kind: "permanent",
      code,
      canRetry: false,
      message: `${message}。请检查设置后重试。`,
    };
  }
  return {
    kind: "retryable",
    code,
    canRetry: true,
    message: /网络|failed to fetch|timeout|超时/i.test(message)
      ? "网络异常，AI 请求未确认。可稍后重试。"
      : `${message}。可稍后重试。`,
  };
}

export function interpretGenerationJobFailure(
  job: GenerationJobFailureInput,
): GenerationFailureOutcome {
  const status = String(job.status ?? "");
  const code = job.errorCode ?? null;
  const message = asMessage(job.errorMessage, "AI 生成未完成");
  if (status === "canceled") {
    return {
      kind: "canceled",
      code,
      canRetry: false,
      message: message === "AI 生成未完成" ? "AI 生成已取消" : message,
    };
  }
  if (code && PERMANENT_GENERATION_CODES.has(code)) {
    return {
      kind: "permanent",
      code,
      canRetry: false,
      message: code === "GENERATION_PROVIDER_REJECTED"
        ? `${message}。供应商已拒绝本次请求，请调整照片或设置后再生成。`
        : code === "GENERATION_PROVIDER_RESPONSE_INVALID"
          ? `${message}。供应商返回无效结果，请调整后重新发起，不会自动重试。`
          : `${message}。请调整设置后再生成。`,
    };
  }
  if (
    code === "GENERATION_PROVIDER_UNAVAILABLE"
    || code === "GENERATION_PROVIDER_TIMEOUT"
    || code === "GENERATION_PROVIDER_FAILED"
  ) {
    return {
      kind: "retryable",
      code,
      canRetry: true,
      message: /可稍后|请稍后|暂时/.test(message) ? message : `${message}。可重新生成。`,
    };
  }
  return {
    kind: "retryable",
    code,
    canRetry: true,
    message: /可稍后|请稍后|暂时|重新生成/.test(message) ? message : `${message}。可重新生成。`,
  };
}
