import { MINI_PALETTES, type MiniPaletteId } from "../../src/data/mard-palettes";

import type { ApiPalette } from "./api";

const BUNDLED_PALETTE_SOURCE = {
  name: "Pindou bundled palette catalog",
  url: "https://github.com/maxcleme/beadcolors",
  revision: "f97ff4283d03cef5cd7e1071a86f5892e0c0c61b",
  license: "MIT",
} as const;

export function createBundledPalette(paletteId: MiniPaletteId): ApiPalette {
  const palette = MINI_PALETTES[paletteId];
  return {
    id: palette.id,
    name: palette.name,
    brand: "Pindou",
    series: "2.6 mm",
    material: "PE",
    beadSizeMm: palette.beadSizeMm,
    verified: true,
    version: 1,
    retired: false,
    source: { ...BUNDLED_PALETTE_SOURCE },
    colors: palette.colors.map((color) => ({
      ...color,
      unitPriceCents: 0,
      available: true,
    })),
  };
}
