import { applySubjectAlpha,framedSubjectBounds,restoreFullMask } from "../../src/data/subject-core";

/** Restore the cutout/AI image belonging to this exact paid project. */
export async function subjectEditorSource(projectId:string,userId:string):Promise<{file:File;image:HTMLImageElement;url:string;size:number;maxColors:number}|null>{
  const db=await new Promise<IDBDatabase>((resolve,reject)=>{const request=indexedDB.open('pindou-subject-draft-v1',1);request.onupgradeneeded=()=>request.result.createObjectStore('drafts');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});
  const draft=await new Promise<any>((resolve,reject)=>{const tx=db.transaction('drafts','readonly'),request=tx.objectStore('drafts').get('project:'+projectId);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});db.close();
  if(!draft||draft.owner!==userId||draft.project?.id!==projectId||!(draft.source instanceof Blob))return null;
  let file:File;
  if(draft.mode==='ai'){
    const candidate=(draft.aiPreviews??[]).find((item:{ordinal:number})=>item.ordinal===(draft.variant??1));
    if(!(candidate?.file instanceof Blob))return null;
    file=new File([candidate.file],'ai-subject.png',{type:'image/png'});
  }else{
    const bitmap=await createImageBitmap(draft.source),canvas=document.createElement('canvas');canvas.width=draft.width;canvas.height=draft.height;
    const context=canvas.getContext('2d')!;context.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();
    const mask=restoreFullMask(canvas.width,canvas.height,draft.mask),pixels=context.getImageData(0,0,canvas.width,canvas.height).data;
    context.putImageData(new ImageData(applySubjectAlpha(pixels,mask),canvas.width,canvas.height),0,0);
    const bounds=framedSubjectBounds(mask,canvas.width,canvas.height,draft.framing??'full',draft.offsetX??0,draft.offsetY??0),target=document.createElement('canvas');
    target.width=target.height=1024;const scale=960/Math.max(bounds.width,bounds.height);
    target.getContext('2d')!.drawImage(canvas,bounds.left,bounds.top,bounds.width,bounds.height,(1024-bounds.width*scale)/2,(1024-bounds.height*scale)/2,bounds.width*scale,bounds.height*scale);
    const blob=await new Promise<Blob>((resolve,reject)=>target.toBlob(value=>value?resolve(value):reject(new Error('图片无法恢复')),'image/png'));
    file=new File([blob],'subject.png',{type:'image/png'});
  }
  const url=URL.createObjectURL(file),image=new Image();
  try{await new Promise<void>((resolve,reject)=>{image.onload=()=>resolve();image.onerror=()=>reject(new Error('图片无法恢复'));image.src=url});return{file,image,url,size:draft.size??96,maxColors:draft.maxColors??24}}
  catch(error){URL.revokeObjectURL(url);throw error}
}
