function cropGeometry() {
  return calculateCropRectangle(cropSourceSize.width || 1, cropSourceSize.height || 1, {
    cropRatio: cropRatio.value,
    freeCropRatio: freeCropRatio.value,
    cropScale: cropScale.value,
    cropOffsetX: cropOffsetX.value,
    cropOffsetY: cropOffsetY.value,
    rotation: rotation.value,
  });
}

const estimatedGrid = computed(() => {
  const crop = cropGeometry();
  const longSide = Math.max(24, Math.round(Number.isFinite(createSettings.size) ? createSettings.size : 256));
  const ratio = crop.width / crop.height;
  const width = ratio >= 1 ? longSide : Math.max(8, Math.round(longSide * ratio));
  const height = ratio >= 1 ? Math.max(8, Math.round(longSide / ratio)) : longSide;
  return {
    width,
    height,
    beads: width * height,
    physicalWidth: (width * props.beadSizeMm / 10).toFixed(1),
    physicalHeight: (height * props.beadSizeMm / 10).toFixed(1),
    workload: width * height <= 100_000 ? "轻量" : width * height <= 500_000 ? "高清" : width * height <= 2_000_000 ? "较大" : "超大",
    memoryMb: Math.max(1, Math.ceil(width * height * 12 / 1024 / 1024)),
  };
});

function clampCropOffsets(): void {
  const bounds = cropGeometry();
  cropOffsetX.value = Math.max(-bounds.maxOffsetX, Math.min(bounds.maxOffsetX, cropOffsetX.value));
  cropOffsetY.value = Math.max(-bounds.maxOffsetY, Math.min(bounds.maxOffsetY, cropOffsetY.value));
}

const cropGuideStyle = computed(() => ({
  left: `${cropRenderLayout.left}px`,
  top: `${cropRenderLayout.top}px`,
  width: `${cropRenderLayout.width}px`,
  height: `${cropRenderLayout.height}px`,
}));

function drawCropPreview(): void {
  const preview = cropPreview.value;
  const canvas = cropCanvas.value;
  const image = cropSourceImage.value;
  if (!preview || !canvas || !image?.complete || !image.naturalWidth || !image.naturalHeight) return;

  const crop = cropGeometry();
  const availableWidth = Math.max(1, preview.clientWidth);
  const availableHeight = Math.max(1, preview.clientHeight);
  const cropAspect = crop.width / crop.height;
  let width = availableWidth;
  let height = width / cropAspect;
  if (height > availableHeight) {
    height = availableHeight;
    width = height * cropAspect;
  }
  const left = (availableWidth - width) / 2;
  const top = (availableHeight - height) / 2;
  Object.assign(cropRenderLayout, { left, top, width, height });

  const pixelRatio = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = Math.max(1, Math.round(width * pixelRatio));
  canvas.height = Math.max(1, Math.round(height * pixelRatio));
  canvas.style.left = `${left}px`;
  canvas.style.top = `${top}px`;
  canvas.style.width = `${width}px`;
  canvas.style.height = `${height}px`;
  const context = canvas.getContext("2d");
  if (!context) return;
  context.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
  context.clearRect(0, 0, width, height);
  context.imageSmoothingEnabled = true;
  context.imageSmoothingQuality = "high";
  drawCropResult(context, image, image.naturalWidth, image.naturalHeight, crop, 0, 0, width, height);
}

function cropImageLoaded(event: Event): void {
  const image = event.currentTarget as HTMLImageElement;
  cropSourceSize.width = image.naturalWidth;
  cropSourceSize.height = image.naturalHeight;
  clampCropOffsets();
  nextTick(drawCropPreview);
}

function cropPointerDown(event: PointerEvent): void {
  if (!props.sourceUrl || event.button > 0) return;
  cropPointerId = event.pointerId;
  cropDragging.value = true;
  cropDragStart = { x: event.clientX, y: event.clientY, offsetX: cropOffsetX.value, offsetY: cropOffsetY.value };
  (event.currentTarget as HTMLElement).setPointerCapture(event.pointerId);
}

function cropPointerMove(event: PointerEvent): void {
  if (!cropDragging.value || cropPointerId !== event.pointerId) return;
  const preview = cropPreview.value;
  if (!preview) return;
  const crop = cropGeometry();
  cropOffsetX.value = cropDragStart.offsetX - (event.clientX - cropDragStart.x) * crop.width / Math.max(1, cropRenderLayout.width);
  cropOffsetY.value = cropDragStart.offsetY - (event.clientY - cropDragStart.y) * crop.height / Math.max(1, cropRenderLayout.height);
  clampCropOffsets();
}

function cropPointerUp(event: PointerEvent): void {
  if (cropPointerId !== event.pointerId) return;
  cropDragging.value = false;
  cropPointerId = null;
  const target = event.currentTarget as HTMLElement;
  if (target.hasPointerCapture(event.pointerId)) target.releasePointerCapture(event.pointerId);
}

function cropKeydown(event: KeyboardEvent): void {
  const step = event.shiftKey ? 30 : 10;
  if (event.key === "ArrowLeft") cropOffsetX.value += step;
  else if (event.key === "ArrowRight") cropOffsetX.value -= step;
  else if (event.key === "ArrowUp") cropOffsetY.value += step;
  else if (event.key === "ArrowDown") cropOffsetY.value -= step;
  else return;
  event.preventDefault();
  clampCropOffsets();
}

function resetCropPosition(): void {
  cropOffsetX.value = 0;
  cropOffsetY.value = 0;
}

function resetCropTransform(): void {
  cropRatio.value = "原图";
