function beginCreate(mode: CreateMode = "normal"): void {
  selectCreateMode(mode);
  createStep.value = 1;
  resetCropTransform();
  emit("navigate", "create");
}

function applyModeDefaults(mode: CreateMode): void {
  const defaults = creationDefaults(mode);
  createSettings.maxColors = defaults.maxColors;
  if (["portrait", "couple"].includes(mode)) {
    createSettings.size = Math.min(CLOUD_GENERATION_MAX_EDGE, createSettings.size);
  }
  emit("prepareCreate", { mode, ...defaults });
}

function selectCreateMode(mode: CreateMode): void {
  createMode.value = mode;
  applyModeDefaults(mode);
}

function nextCreateStep(): void {
  if (createStep.value === 1 && !props.hasSource) {
    emit("notify", "请先上传一张图片");
    return;
  }
  if (createStep.value === 3) {
    const requestedSize = Math.round(Number(createSettings.size));
    if (!Number.isFinite(requestedSize) || requestedSize < 24) {
      emit("notify", "图纸长边至少需要 24 格");
      return;
    }
    if (remoteAiMode.value && requestedSize > CLOUD_GENERATION_MAX_EDGE) {
      createSettings.size = CLOUD_GENERATION_MAX_EDGE;
      emit("notify", `远端 AI 单边最多 ${CLOUD_GENERATION_MAX_EDGE} 格，已调整为兼容尺寸`);
    } else {
      createSettings.size = requestedSize;
    }
    if (estimatedGrid.value.beads > 500_000 && !window.confirm(
      `将生成 ${estimatedGrid.value.width}×${estimatedGrid.value.height}，约 ${estimatedGrid.value.beads.toLocaleString()} 颗豆。预计至少占用 ${estimatedGrid.value.memoryMb} MB 工作内存，是否继续？`,
    )) return;
  }
  if (createStep.value < 3) createStep.value += 1;
  else if (["portrait", "couple"].includes(createMode.value)) {
    if (props.syncStatus !== "synced") {
      emit("notify", "收费生成前请连接共享账号，抠图预览与手动绘制免费");
      return;
    }
    const cost = 3;
    if ((props.credits ?? 0) < cost) {
      emit("notify", `AI 次数不足，还差 ${cost - (props.credits ?? 0)} 次`);
      emit("navigate", "credits");
      return;
    }
    createStep.value = 4;
    candidate.value = 1;
    emit("startAi", {
      mode: createMode.value,
      size: createSettings.size,
      maxColors: createSettings.maxColors,
      transparentBackground: createSettings.transparentBackground,
      inventoryOnly: createSettings.inventoryOnly,
      cropRatio: cropRatio.value,
      freeCropRatio: freeCropRatio.value,
      cropScale: cropScale.value,
      cropOffsetX: Math.round(cropOffsetX.value),
      cropOffsetY: Math.round(cropOffsetY.value),
      rotation: rotation.value,
      removeBackground: removeBackground.value,
      figureStyle: figureStyle.value,
      coupleLayout: coupleLayout.value,
    });
  } else finishCreate();
}

function finishCreate(): void {
  if (["portrait", "couple"].includes(createMode.value)) {
    emit("acceptAi", candidate.value);
    return;
  }
  emit("finishCreate", {
    mode: createMode.value,
    ...createSettings,
    cropRatio: cropRatio.value,
    freeCropRatio: freeCropRatio.value,
    cropScale: cropScale.value,
    cropOffsetX: Math.round(cropOffsetX.value),
    cropOffsetY: Math.round(cropOffsetY.value),
    rotation: rotation.value,
    removeBackground: false,
  });
}

function toggleProject(id: string): void {
  selectedProjects.value = selectedProjects.value.includes(id)
    ? selectedProjects.value.filter((item) => item !== id)
    : [...selectedProjects.value, id];
}

function queueBatchExport(): void {
  if (!selectedProjects.value.length) {
    emit("notify", "请先勾选需要导出的作品");
    return;
  }
  if (props.syncStatus !== "synced") {
    emit("notify", "批量 PDF 需要先连接共享账号并锁定作品版本");
    return;
  }
  emit("batchExport", [...selectedProjects.value]);
  selectedProjects.value = [];
  emit("navigate", "exports");
}

function applyMaintainOutcome(kind: "ok" | "refresh" | "error", message: string, originFingerprint: string | null): void {
  inventoryBusy.value = false;
  if (kind === "refresh") {
    maintainRefreshMessage.value = message;
    maintainOriginFingerprint.value = originFingerprint;
  } else {
    maintainRefreshMessage.value = "";
    maintainOriginFingerprint.value = null;
  }
  emit("notify", message);
}

function updateStock(code: string, delta: number): void {
  if (inventoryBusy.value || maintainRefreshMessage.value) return;
  const row = inventory.value.find((item) => item.code === code);
  if (!row) return;
  if (props.syncStatus === "synced") {
    inventoryBusy.value = true;
    emit("adjustInventory", code, delta, applyMaintainOutcome);
  } else {
    row.stock = Math.max(0, row.stock + delta);
    localStorage.setItem("pindou-web-inventory", JSON.stringify(inventory.value));
  }
}

function saveLocation(code: string): void {
  if (inventoryBusy.value || maintainRefreshMessage.value) return;
  if (props.syncStatus !== "synced") {
    emit("notify", "仓位写入需要先连接共享账号");
    return;
  }
  inventoryBusy.value = true;
  emit("updateInventoryLocation", code, locationDrafts.value[code] ?? "", applyMaintainOutcome);
}

function retryMaintainRefresh(): void {
  if (inventoryBusy.value || !maintainRefreshMessage.value) return;
  inventoryBusy.value = true;
  emit("refreshInventorySnapshot", (ok, message) => {
    inventoryBusy.value = false;
    if (ok) {
      maintainRefreshMessage.value = "";
      maintainOriginFingerprint.value = null;
    }
    emit("notify", message);
  }, maintainOriginFingerprint.value);
}

function invalidateCalibrateRead(): void {
  calibrateReadId.value += 1;
}

function openCalibrate(): void {
  if (props.syncStatus !== "synced") {
    emit("notify", "CSV 批量校准需要先连接共享账号");
    return;
  }
  if (!props.activePaletteId) {
    emit("notify", "请先选择当前色卡");
    return;
  }
  invalidateCalibrateRead();
  calibrateOpen.value = true;
  calibratePhase.value = "edit";
  calibrateErrors.value = [];
  calibratePreview.value = null;
  calibrateBusy.value = false;
  calibrateOriginFingerprint.value = null;
}

function closeCalibrate(): void {
  if (calibrateBusy.value || calibratePhase.value === "refresh") return;
  invalidateCalibrateRead();
  calibrateOpen.value = false;
  calibratePreview.value = null;
  calibrateErrors.value = [];
  calibratePhase.value = "edit";
}

function onCalibrateTextInput(): void {
  invalidateCalibrateRead();
  calibratePreview.value = null;
}

function readCalibrateFile(event: Event): void {
  const input = event.target as HTMLInputElement;
  const file = input.files?.[0];
  if (!file) return;
  const readId = calibrateReadId.value + 1;
  calibrateReadId.value = readId;
  void file.text().then((text) => {
    if (!isCalibrateFileReadCurrent({ readId, currentReadId: calibrateReadId.value, dialogOpen: calibrateOpen.value })) return;
    calibrateText.value = text;
    calibratePreview.value = null;
    calibrateErrors.value = [];
    calibratePhase.value = "edit";
  }).catch(() => {
    if (!isCalibrateFileReadCurrent({ readId, currentReadId: calibrateReadId.value, dialogOpen: calibrateOpen.value })) return;
    calibrateErrors.value = ["无法读取所选文件，已保留当前表格内容"];
  }).finally(() => {
    input.value = "";
  });
}

function previewCalibrate(): void {
  if (calibratePhase.value === "refresh") return;
  const parsed = parseInventoryCalibrateTable(calibrateText.value, props.palette);
  if (!parsed.ok) {
    calibrateErrors.value = parsed.errors;
    calibratePreview.value = null;
    return;
  }
  calibrateErrors.value = [];
  calibratePreview.value = buildInventoryCalibratePreview(
    parsed.rows,
    props.activePaletteId,
    props.inventoryItems ?? [],
    inventoryFingerprint.value,
  );
}

function confirmCalibrate(): void {
  const preview = calibratePreview.value;
  if (!preview || calibrateBusy.value || calibratePhase.value === "refresh") return;
  if (calibrateStale.value) {
    calibrateErrors.value = ["库存、色卡或账号已变化，请重新预览后再确认"];
    calibratePreview.value = null;
    return;
  }
  calibrateBusy.value = true;
  emit("calibrateInventory", preview, (result, message, originFingerprint) => {
    calibrateBusy.value = false;
    emit("notify", message);
    if (result === "ok") closeCalibrate();
    else if (result === "refresh") {
      calibratePhase.value = "refresh";
      calibrateOriginFingerprint.value = originFingerprint;
      calibrateErrors.value = [message];
    }
  });
}

function retryInventoryRefresh(): void {
  if (calibrateBusy.value) return;
  calibrateBusy.value = true;
  emit("refreshInventorySnapshot", (ok, message) => {
    calibrateBusy.value = false;
    emit("notify", message);
    if (ok) {
      calibratePhase.value = "edit";
      calibrateOriginFingerprint.value = null;
      closeCalibrate();
    } else {
      calibratePhase.value = "refresh";
      calibrateErrors.value = [message];
    }
  }, calibrateOriginFingerprint.value);
}

function createExport(): void {
  if (props.syncStatus !== "synced") {
    emit("notify", "分页 PDF 需要先连接共享账号；可在编辑器直接导出本机 PNG");
    return;
  }
  emit("createExport", "pdf");
}

function retryExport(id: string): void {
  emit("retryExport", id);
}

function cancelExport(id: string): void {
  if (props.syncStatus !== "synced") {
    emit("notify", "请先连接共享账号后再取消导出任务。");
    return;
  }
  if (props.exportCancelBusyId) {
    emit("notify", "正在取消导出，请稍候。");
    return;
  }
  emit("cancelExport", id);
}

function buyCredits(): void {
  const pack = creditPacks.value[selectedPack.value];
  if (!pack || props.syncStatus !== "synced") {
    emit("notify", "请先连接共享账号，再读取服务端商品");
    return;
  }
  emit("notify", `请在微信小程序购买“${pack.title}”套餐；到账后 Web 会读取同一服务端余额`);
}

watch(() => props.page, (page) => {
  document.title = `${pageTitle.value} · ${PRODUCT_NAME}`;
  const url = new URL(window.location.href);
  url.searchParams.set("view", page);
  history.replaceState({ page }, "", url);
});
watch(() => props.palette, (palette) => {
  const previous = new Map(inventory.value.map((item) => [item.code, item]));
  inventory.value = palette.map((item) => {
    if (props.syncStatus === "synced") return { ...item };
    const local = previous.get(item.code);
    return {
      ...item,
      stock: local?.stock ?? item.stock,
      location: local?.location ?? item.location,
    };
  });
  const drafts: Record<string, string> = {};
  for (const item of inventory.value) drafts[item.code] = item.location ?? "";
  locationDrafts.value = drafts;
}, { deep: true });
watch([cropRatio, freeCropRatio, cropScale, rotation], () => {
  clampCropOffsets();
  nextTick(drawCropPreview);
});
watch([cropOffsetX, cropOffsetY], () => nextTick(drawCropPreview));
watch(createStep, (step) => {
  if (step === 2) nextTick(drawCropPreview);
});
watch(() => props.sourceUrl, (url, previousUrl) => {
  resetCropTransform();
  cropSourceSize.width = 0;
  cropSourceSize.height = 0;
  if (url && url !== previousUrl && props.page === "create") createStep.value = 2;
});

onMounted(() => {
  cropResizeObserver = new ResizeObserver(() => drawCropPreview());
  if (cropPreview.value) cropResizeObserver.observe(cropPreview.value);
});

watch(cropPreview, (preview, previous) => {
  if (previous) cropResizeObserver?.unobserve(previous);
  if (preview) {
    cropResizeObserver?.observe(preview);
    nextTick(drawCropPreview);
  }
});

onBeforeUnmount(() => cropResizeObserver?.disconnect());

watch(creditPacks, (packs) => {
  if (selectedPack.value >= packs.length) selectedPack.value = 0;
});

try {
  const saved = JSON.parse(localStorage.getItem("pindou-web-inventory") ?? "null") as typeof inventory.value | null;
  if (Array.isArray(saved) && saved.length) inventory.value = saved;
} catch {
  // Invalid local inventory falls back to the seeded palette.
}
</script>

