      <div class="inventory-toolbar"><label class="search-box">⌕<input v-model="inventoryQuery" aria-label="搜索豆仓色号或颜色名称" placeholder="搜索色号或颜色名称" /></label><select :value="activePaletteId" :disabled="!paletteOptions.length" aria-label="当前色卡" @change="emit('changePalette', ($event.target as HTMLSelectElement).value)"><option v-if="!paletteOptions.length" value="">尚未加载色卡</option><option v-for="item in paletteOptions" :key="item.id" :value="item.id">{{ item.colors.length }} 色</option></select><button class="outline-button" :disabled="syncStatus !== 'synced'" @click="emit('importPalette')">导入自定义色卡</button><button class="outline-button" :disabled="syncStatus !== 'synced' || !activePaletteId" @click="openCalibrate">CSV 批量校准</button></div>
      <p v-if="maintainRefreshMessage" class="calibrate-stale" role="status">{{ maintainRefreshMessage }} <button class="outline-button" :disabled="inventoryBusy" @click="retryMaintainRefresh">{{ inventoryBusy ? '正在刷新…' : '只刷新库存和流水' }}</button></p>
