            <table v-if="calibratePreview && !calibrateStale" class="calibrate-preview"><thead><tr><th>色号</th><th>名称</th><th>旧库存</th><th>新数量</th></tr></thead><tbody><tr v-for="row in calibratePreview.rows" :key="row.colorCode"><td>{{ row.colorCode }}</td><td>{{ row.name }}</td><td>{{ row.previousQuantity }}</td><td>{{ row.quantity }}</td></tr></tbody></table>
