export function resolveClientApiBase(input: {
  isWechatMini: boolean;
  development: boolean;
  configuredBase: string;
  localDevelopmentBase?: string;
}): string {
  const configuredBase = input.configuredBase.trim().replace(/\/+$/, "");
  if (!input.isWechatMini) {
    if (!configuredBase) return input.development ? "/api/v1" : "";
    if (input.development) return configuredBase;

    try {
      const url = new URL(configuredBase);
      if (url.protocol !== "https:" || isLoopbackHost(url.hostname)) return "";
      return configuredBase;
    } catch {
      return "";
    }
  }

  if (configuredBase) {
    if (input.development) return configuredBase;
    // WeChat's device JS runtime does not provide the browser URL constructor.
    // Validate the configured absolute HTTPS address without browser globals.
    const match = /^https:\/\/(\[[0-9a-f:.]+\]|[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?)(?::([0-9]{1,5}))?(?:[/?#][^\s\\]*)?$/i.exec(configuredBase);
    if (!match || isLoopbackHost(match[1])) return "";
    if (match[2] && (Number(match[2]) < 1 || Number(match[2]) > 65535)) return "";
    return configuredBase;
  }

  return input.development ? input.localDevelopmentBase || "" : "";
}

function isLoopbackHost(hostname: string): boolean {
  const host = hostname.toLowerCase().replace(/^\[|\]$/g, "");
  return host === "localhost" || host === "::1" || host === "0.0.0.0" || /^127(?:\.\d{1,3}){3}$/.test(host);
}
