/**
 * Pure helpers for Web pairing login UI: busy/cancel generation and poll teardown.
 * Does not invent production WeChat success — only gates the existing challenge/poll/adopt contract.
 */

export type WebLoginUiPhase = "idle" | "creating" | "waiting" | "adopting";

export function nextWebLoginGeneration(current: number): number {
  return current + 1;
}

export function shouldAdoptWebLogin(input: {
  generation: number;
  activeGeneration: number;
  status: string;
}): boolean {
  return input.generation === input.activeGeneration && input.status === "approved";
}

export function shouldContinueWebLoginPoll(input: {
  generation: number;
  activeGeneration: number;
  status: string;
}): boolean {
  if (input.generation !== input.activeGeneration) return false;
  if (input.status === "approved" || input.status === "expired") return false;
  return true;
}

export function webLoginCreatingMessage(): string {
  return "正在获取配对码…可取消。";
}

export function webLoginWaitingMessage(code: string): string {
  return `配对码 ${code} · 正在等待小程序确认`;
}

export function webLoginCancelKeepsLocalDraftMessage(): string {
  return "已取消配对。未建立共享会话；本机草稿未改动。";
}

export function webLoginOverlayVisible(phase: WebLoginUiPhase, hasCode: boolean): boolean {
  return phase === "creating" || phase === "waiting" || phase === "adopting" || hasCode;
}

export function canCancelWebLogin(phase: WebLoginUiPhase, busy: boolean): boolean {
  return busy || phase === "creating" || phase === "waiting";
}
