export function requireWebSessionToken(sessionToken: unknown, pollToken: string): string {
  if (typeof sessionToken !== "string" || sessionToken.length < 8) {
    throw new Error("Web 登录缺少独立会话令牌，已拒绝使用轮询令牌");
  }
  if (sessionToken === pollToken) {
    throw new Error("Web 登录会话令牌与轮询令牌相同，已拒绝建立会话");
  }
  return sessionToken;
}
