export type WebLogoutGate = {
  synced: boolean;
  busy: boolean;
  hasToken: boolean;
};

export type WebLogoutRetryGate = WebLogoutGate & { lastFailed: boolean };

export type WebLogoutFailureOutcome =
  | { kind: "retryable"; message: string }
  | { kind: "session_gone"; message: string };

export function canStartWebLogout(gate: WebLogoutGate): boolean {
  return gate.synced && gate.hasToken && !gate.busy;
}

export function canRetryWebLogout(gate: WebLogoutRetryGate): boolean {
  return gate.synced && gate.hasToken && !gate.busy && gate.lastFailed;
}

export function webLogoutOfflineMessage(): string {
  return "当前是本地模式，无需退出登录。连接共享账号后可在此退出。";
}

export function webLogoutBusyMessage(): string {
  return "正在退出登录，请稍候。";
}

export function webLogoutSuccessMessage(): string {
  return "已退出共享账号，回到本地模式。本机草稿仍保留。";
}

export function webLogoutConfirmMessage(hasUnsavedDraft: boolean): string {
  return hasUnsavedDraft
    ? "确定退出共享账号？未保存或本机草稿会保留在此浏览器；云端同步将停止，可稍后重新连接。"
    : "确定退出共享账号？将清除本机会话并回到本地模式，可稍后重新连接。";
}

export function interpretWebLogoutFailure(error: unknown): WebLogoutFailureOutcome {
  const status = typeof error === "object" && error && "status" in error
    ? Number((error as { status?: unknown }).status)
    : NaN;
  const code = typeof error === "object" && error && "code" in error
    ? String((error as { code?: unknown }).code ?? "")
    : "";
  const message = error instanceof Error
    ? error.message
    : typeof error === "object" && error && "message" in error && typeof (error as { message?: unknown }).message === "string"
      ? (error as { message: string }).message
      : "退出登录失败";
  if (status === 401 || code === "UNAUTHORIZED" || code === "SESSION_REVOKED") {
    return {
      kind: "session_gone",
      message: "共享会话已失效，已切回本地模式。本机草稿仍保留。",
    };
  }
  return {
    kind: "retryable",
    message: /网络|failed to fetch|timeout/i.test(message)
      ? "网络异常，共享会话尚未退出。可重试退出登录。"
      : `${message}。共享会话尚未退出，可重试。`,
  };
}

export function shouldClearLocalSessionAfterLogoutAttempt(outcome: WebLogoutFailureOutcome): boolean {
  return outcome.kind === "session_gone";
}
