/** Fastify standard error envelope: `{ error: { code, message, retryable, details } }`. */

export type ApiErrorEnvelope = {
  code: string;
  message: string;
  retryable: boolean;
  details: unknown;
};

export type ApiErrorPayload = {
  error?: {
    code?: unknown;
    message?: unknown;
    retryable?: unknown;
    details?: unknown;
  } | null;
} | null;

export function parseApiErrorEnvelope(
  status: number,
  payload: ApiErrorPayload,
  fallbackMessage = `请求失败（${status}）`,
): ApiErrorEnvelope {
  const error = payload && typeof payload === "object" ? payload.error : null;
  const code = typeof error?.code === "string" && error.code
    ? error.code
    : "REQUEST_FAILED";
  const message = typeof error?.message === "string" && error.message
    ? error.message
    : fallbackMessage;
  const retryable = typeof error?.retryable === "boolean"
    ? error.retryable
    : status >= 500;
  return {
    code,
    message,
    retryable,
    details: error?.details ?? null,
  };
}
