export type InventoryConsumePhase = "idle" | "busy" | "consumed" | "retryable" | "refresh";

export type InventoryConsumeGate = {
  synced: boolean;
  cloudProject: boolean;
  buildComplete: boolean;
  busy: boolean;
  phase: InventoryConsumePhase;
};

export type InventoryConsumeOutcome =
  | { kind: "ok"; message: string; nextPhase: "consumed" }
  | { kind: "already_consumed"; message: string; nextPhase: "consumed"; consumedAt?: string }
  | { kind: "refresh_failed"; message: string; nextPhase: "refresh"; originFingerprint?: string }
  | { kind: "insufficient"; message: string; nextPhase: "idle" }
  | { kind: "not_completed"; message: string; nextPhase: "idle" }
  | { kind: "revision_mismatch"; message: string; nextPhase: "idle" }
  | { kind: "retryable"; message: string; nextPhase: "retryable"; originFingerprint?: string }
  | { kind: "blocked"; message: string; nextPhase: InventoryConsumePhase };

/** UI may show the confirm control only when a cloud completed build can still be confirmed. */
export function canConfirmInventoryConsume(gate: InventoryConsumeGate): boolean {
  return gate.synced
    && gate.cloudProject
    && gate.buildComplete
    && !gate.busy
    && gate.phase !== "consumed"
    && gate.phase !== "refresh";
}

/** Network POST must not fire unless the gate allows confirmation. */
export function shouldSendInventoryConsumeRequest(gate: InventoryConsumeGate): boolean {
  return canConfirmInventoryConsume(gate) && gate.phase !== "busy";
}

/** After POST (or already-consumed) succeeded, only inventory/ledger refresh may retry. */
export function canRetryInventoryConsumeRefresh(gate: Pick<InventoryConsumeGate, "synced" | "busy" | "phase">): boolean {
  return gate.synced && !gate.busy && gate.phase === "refresh";
}

export function inventoryConsumeSuccessMessage(transactionCount: number): string {
  return transactionCount > 0
    ? `已确认扣减库存（${transactionCount} 个色号），豆仓与流水已刷新。制作完成状态保持不变。`
    : "已确认扣减库存，豆仓与流水已刷新。制作完成状态保持不变。";
}

export function inventoryConsumeRefreshFailureMessage(): string {
  return "扣减已提交，豆仓与流水尚未刷新成功。请只刷新库存和流水，不要再次确认扣减。";
}

/** POST already landed on the origin account; current session must not refresh or mark success. */
export function inventoryConsumeAccountSwitchRefreshMessage(): string {
  return "原账号已提交，请切回原账号后仅刷新库存和流水，不要再次确认扣减。";
}

/** Map POST-success + refresh result into the terminal UI phase. */
export function inventoryConsumeAfterPostRefreshOutcome(
  refreshOk: boolean,
  transactionCount: number,
  originFingerprint?: string,
  options?: { accountSwitched?: boolean; message?: string },
): Extract<InventoryConsumeOutcome, { kind: "ok" | "refresh_failed" }> {
  if (refreshOk) {
    return {
      kind: "ok",
      message: inventoryConsumeSuccessMessage(transactionCount),
      nextPhase: "consumed",
    };
  }
  return {
    kind: "refresh_failed",
    message: options?.message
      ?? (options?.accountSwitched
        ? inventoryConsumeAccountSwitchRefreshMessage()
        : inventoryConsumeRefreshFailureMessage()),
    nextPhase: "refresh",
    originFingerprint,
  };
}

type ConsumeErrorLike = {
  code?: string;
  message?: string;
  status?: number;
  details?: { consumedAt?: string; shortages?: unknown };
};

export function interpretInventoryConsumeFailure(error: ConsumeErrorLike | Error | unknown): InventoryConsumeOutcome {
  const code = typeof error === "object" && error && "code" in error
    ? String((error as ConsumeErrorLike).code ?? "")
    : "";
  const message = error instanceof Error
    ? error.message
    : typeof error === "object" && error && "message" in error && typeof (error as ConsumeErrorLike).message === "string"
      ? (error as ConsumeErrorLike).message!
      : "库存扣减失败";
  const details = typeof error === "object" && error && "details" in error
    ? (error as ConsumeErrorLike).details
    : undefined;

  if (code === "PROJECT_INVENTORY_ALREADY_CONSUMED") {
    return {
      kind: "already_consumed",
      message: "该图纸版本已确认扣减过库存。制作完成状态保持不变；已刷新豆仓展示。",
      nextPhase: "consumed",
      consumedAt: typeof details?.consumedAt === "string" ? details.consumedAt : undefined,
    };
  }
  if (code === "INVENTORY_INSUFFICIENT") {
    return {
      kind: "insufficient",
      message: "豆仓库存不足，未扣减任何色号。作品仍保持制作完成，可补货后再确认扣减。",
      nextPhase: "idle",
    };
  }
  if (code === "PROJECT_BUILD_NOT_COMPLETED") {
    return {
      kind: "not_completed",
      message: "项目制作完成后才能确认扣减库存。未发送重复扣减。",
      nextPhase: "idle",
    };
  }
  if (code === "INVENTORY_CONSUMPTION_REVISION_MISMATCH") {
    return {
      kind: "revision_mismatch",
      message: "只能扣减当前图纸版本的库存。请重新打开作品后再确认。",
      nextPhase: "idle",
    };
  }
  if (!code || code === "REQUEST_FAILED" || /网络|failed to fetch|Failed to fetch|timeout/i.test(message)) {
    return {
      kind: "retryable",
      message: message.includes("网络") || /fetch/i.test(message)
        ? "网络异常，库存尚未扣减。作品仍保持制作完成，可重试确认扣减。"
        : `${message}。库存尚未扣减，可重试确认扣减。`,
      nextPhase: "retryable",
    };
  }
  return {
    kind: "retryable",
    message: `${message}。库存尚未扣减，可重试确认扣减。`,
    nextPhase: "retryable",
  };
}
