/**
 * Client helpers for project completion photos.
 * Transport uses Bearer + Idempotency-Key multipart to the project-scoped API only.
 * Never store or display private object keys / signed storage URLs.
 */

export type ApiCompletionPhoto = {
  id: string;
  projectId: string;
  projectRevision: number;
  mimeType: string;
  sizeBytes: number;
  width: number;
  height: number;
  sha256: string;
  createdAt: string;
};

export type CompletionPhotoFailureKind = "retryable" | "permanent" | "auth";

export type CompletionPhotoFailureOutcome = {
  kind: CompletionPhotoFailureKind;
  message: string;
  canRetry: boolean;
  /** Caller should mint a new Idempotency-Key before the next upload attempt. */
  rotateIdempotencyKey: boolean;
  code: string | null;
};

const ROTATE_KEY_CODES = new Set([
  "IDEMPOTENCY_CONFLICT",
  "COMPLETION_PHOTO_UPLOAD_UNAVAILABLE",
  "COMPLETION_PHOTO_STORAGE_CONFLICT",
]);

const PERMANENT_CODES = new Set([
  "PROJECT_BUILD_NOT_COMPLETED",
  "PROJECT_COMPLETION_REVISION_MISMATCH",
  "PROJECT_COMPLETION_STATE_CHANGED",
  "COMPLETION_PHOTO_LIMIT_EXCEEDED",
  "COMPLETION_PHOTO_STORAGE_LIMIT_EXCEEDED",
  "COMPLETION_PHOTO_FIELDS_NOT_ALLOWED",
  "SINGLE_COMPLETION_PHOTO_REQUIRED",
  "COMPLETION_PHOTO_REQUIRED",
  "ASSET_TOO_LARGE",
  "INVALID_IMAGE",
  "UNSUPPORTED_IMAGE_TYPE",
  "COMPLETION_PHOTO_CONTENT_CORRUPTED",
  "COMPLETION_PHOTO_CONTENT_UNAVAILABLE",
  "COMPLETION_PHOTO_NOT_FOUND",
  "PROJECT_NOT_FOUND",
  "PROJECT_REVISION_NOT_FOUND",
  "INVALID_MULTIPART_UPLOAD",
  "COMPLETION_PHOTO_ASSET_INVALID",
]);

export type CompletionPhotoGate = {
  synced: boolean;
  cloudProject: boolean;
  buildComplete: boolean;
  busy: boolean;
  authenticated: boolean;
};

export function canManageCompletionPhotos(gate: CompletionPhotoGate): boolean {
  return gate.authenticated && gate.synced && gate.cloudProject && gate.buildComplete && !gate.busy;
}

export function canRetryCompletionPhotoAction(gate: Pick<CompletionPhotoGate, "busy"> & { retryable: boolean }): boolean {
  return !gate.busy && gate.retryable;
}

export type CompletionPhotoRetryKind = "upload" | "load";

export function completionPhotoRetryLabel(kind: CompletionPhotoRetryKind | null): string {
  if (kind === "upload") return "重试上传完工照";
  if (kind === "load") return "重试加载完工照";
  return "重试";
}

export function completionPhotoUploadFingerprint(
  file: Pick<File, "name" | "size" | "lastModified" | "type">,
  projectRevision: number,
): string {
  return `${file.name}:${file.size}:${file.lastModified}:${file.type}|rev:${projectRevision}`;
}

export function completionPhotoUploadPath(projectId: string, projectRevision: number): string {
  return `/projects/${encodeURIComponent(projectId)}/completion-photos?projectRevision=${projectRevision}`;
}

export function completionPhotoListPath(projectId: string, revision?: number): string {
  const base = `/projects/${encodeURIComponent(projectId)}/completion-photos`;
  return revision === undefined ? base : `${base}?revision=${revision}`;
}

export function completionPhotoContentPath(projectId: string, photoId: string): string {
  return `/projects/${encodeURIComponent(projectId)}/completion-photos/${encodeURIComponent(photoId)}/content`;
}

/** Keep only public API fields; drop any accidental storage URL/key fields. */
export function publicCompletionPhoto(input: unknown): ApiCompletionPhoto | null {
  if (!input || typeof input !== "object") return null;
  const row = input as Record<string, unknown>;
  if (typeof row.id !== "string" || !row.id) return null;
  if (typeof row.projectId !== "string" || !row.projectId) return null;
  if (!Number.isInteger(row.projectRevision) || (row.projectRevision as number) < 1) return null;
  if (typeof row.mimeType !== "string" || !row.mimeType) return null;
  if (!Number.isInteger(row.sizeBytes) || (row.sizeBytes as number) < 0) return null;
  if (!Number.isInteger(row.width) || (row.width as number) < 0) return null;
  if (!Number.isInteger(row.height) || (row.height as number) < 0) return null;
  if (typeof row.sha256 !== "string" || !row.sha256) return null;
  if (typeof row.createdAt !== "string" || !row.createdAt) return null;
  return {
    id: row.id,
    projectId: row.projectId,
    projectRevision: row.projectRevision as number,
    mimeType: row.mimeType,
    sizeBytes: row.sizeBytes as number,
    width: row.width as number,
    height: row.height as number,
    sha256: row.sha256,
    createdAt: row.createdAt,
  };
}

export function completionPhotoUploadSuccessMessage(photo: ApiCompletionPhoto): string {
  return `完工照已上传（版本 ${photo.projectRevision}）`;
}

export function completionPhotoListEmptyMessage(): string {
  return "当前版本还没有完工照";
}

function asMessage(value: string | null | undefined, fallback: string): string {
  return typeof value === "string" && value.trim() ? value.trim() : fallback;
}

export function interpretCompletionPhotoFailure(
  input: { status?: number; code?: string | null; message?: string | null; retryable?: boolean } | Error | unknown,
): CompletionPhotoFailureOutcome {
  if (input instanceof Error) {
    const status = "status" in input && typeof (input as { status?: unknown }).status === "number"
      ? (input as { status: number }).status
      : undefined;
    const code = "code" in input && typeof (input as { code?: unknown }).code === "string"
      ? (input as { code: string }).code
      : null;
    const retryable = "retryable" in input && typeof (input as { retryable?: unknown }).retryable === "boolean"
      ? (input as { retryable: boolean }).retryable
      : undefined;
    return interpretCompletionPhotoFailure({
      status,
      code,
      message: input.message,
      retryable,
    });
  }

  const status = typeof (input as { status?: unknown })?.status === "number"
    ? (input as { status: number }).status
    : undefined;
  const code = typeof (input as { code?: unknown })?.code === "string"
    ? (input as { code: string }).code
    : null;
  const message = asMessage(
    typeof (input as { message?: unknown })?.message === "string"
      ? (input as { message: string }).message
      : null,
    status ? `完工照请求失败（${status}）` : "完工照请求失败",
  );
  const explicitRetryable = typeof (input as { retryable?: unknown })?.retryable === "boolean"
    ? (input as { retryable: boolean }).retryable
    : undefined;

  if (status === 401 || status === 403 || code === "UNAUTHORIZED" || code === "FORBIDDEN") {
    return {
      kind: "auth",
      message: "登录已失效，请重新登录后再管理完工照",
      canRetry: false,
      rotateIdempotencyKey: false,
      code,
    };
  }

  if (code && ROTATE_KEY_CODES.has(code)) {
    return {
      kind: "permanent",
      message: `${message}。请换一张照片或使用新的上传重试。`,
      canRetry: true,
      rotateIdempotencyKey: true,
      code,
    };
  }

  if (code && PERMANENT_CODES.has(code)) {
    return {
      kind: "permanent",
      message,
      canRetry: false,
      rotateIdempotencyKey: false,
      code,
    };
  }

  const retryable = explicitRetryable ?? (typeof status === "number" ? status >= 500 || status === 429 : true);
  return {
    kind: retryable ? "retryable" : "permanent",
    message: retryable ? `${message}。可重试。` : message,
    canRetry: retryable,
    rotateIdempotencyKey: false,
    code,
  };
}
