import { parseCsvRecords } from "./csv";

export const INVENTORY_BATCH_CALIBRATE_LIMIT = 100;

export interface InventoryCalibrateParsedRow {
  colorCode: string;
  quantity: number;
  name: string;
}

export interface InventoryCalibratePreviewRow extends InventoryCalibrateParsedRow {
  previousQuantity: number;
  location: string | null;
  baseRevision: number;
}

export interface InventoryCalibratePreview {
  paletteId: string;
  fingerprint: string;
  rows: InventoryCalibratePreviewRow[];
}

export type InventoryCalibrateParseResult =
  | { ok: true; rows: InventoryCalibrateParsedRow[] }
  | { ok: false; errors: string[] };

export interface InventoryCalibrateSnapshotItem {
  paletteId: string;
  colorCode: string;
  quantity: number;
  location: string | null;
  revision: number;
}

export class InventoryCalibrateRefreshError extends Error {
  readonly submitted = true as const;
  readonly originFingerprint: string | null;

  constructor(
    message = "校准已提交，但库存或流水刷新失败。请只重试刷新，不要再次提交。",
    originFingerprint: string | null = null,
  ) {
    super(message);
    this.name = "InventoryCalibrateRefreshError";
    this.originFingerprint = originFingerprint;
  }
}

export function isInventoryCalibrateRefreshError(error: unknown): error is InventoryCalibrateRefreshError {
  return Boolean(
    error
    && typeof error === "object"
    && (error as { name?: string }).name === "InventoryCalibrateRefreshError"
    && (error as { submitted?: unknown }).submitted === true,
  );
}

export type InventoryCalibrateDone = (
  result: "ok" | "refresh" | "error",
  message: string,
  originFingerprint: string | null,
) => void;

export type InventoryCalibrateRefreshDone = (ok: boolean, message: string) => void;

export async function inventoryCalibrateSessionFingerprint(material: string): Promise<string> {
  const digest = await globalThis.crypto.subtle.digest("SHA-256", new TextEncoder().encode(material));
  return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, "0")).join("");
}

export function isCalibrateFileReadCurrent(input: {
  readId: number;
  currentReadId: number;
  dialogOpen: boolean;
}): boolean {
  return input.dialogOpen && input.readId === input.currentReadId;
}

function extraCells(row: string[]): string[] {
  return row.slice(2).filter((cell) => cell.trim().length > 0);
}

function tableRecords(text: string): Array<{ line: number; cells: string[] }> {
  const source = text.replace(/^\uFEFF/, "");
  const tabs = (source.match(/\t/g) ?? []).length;
  const commas = (source.match(/,/g) ?? []).length;
  return parseCsvRecords(tabs > commas ? source.replace(/\t/g, ",") : source);
}

function isHeader(row: string[]): boolean {
  const left = (row[0] ?? "").trim().toLowerCase();
  const right = (row[1] ?? "").trim().toLowerCase();
  return /^(色号|code|颜色)$/.test(left) && /^(数量|qty|quantity|库存|stock)$/.test(right);
}

export function parseInventoryCalibrateTable(
  text: string,
  palette: ReadonlyArray<{ code: string; name: string }>,
): InventoryCalibrateParseResult {
  const errors: string[] = [];
  let records: Array<{ line: number; cells: string[] }>;
  try {
    records = tableRecords(text);
  } catch (error) {
    return { ok: false, errors: [error instanceof Error ? error.message : "表格无法解析"] };
  }
  if (records[0] && isHeader(records[0].cells)) {
    if (extraCells(records[0].cells).length) {
      return { ok: false, errors: [`第 ${records[0].line} 行不能包含多余列`] };
    }
    records = records.slice(1);
  }
  if (!records.length) return { ok: false, errors: ["请粘贴或选择包含色号和数量的表格"] };

  const paletteByCode = new Map(palette.map((color) => [color.code.trim().toUpperCase(), color]));
  const seen = new Map<string, number>();
  const parsed: InventoryCalibrateParsedRow[] = [];

  records.forEach((record) => {
    const line = record.line;
    const row = record.cells;
    const colorCode = (row[0] ?? "").trim().toUpperCase();
    const quantityText = (row[1] ?? "").trim();
    if (!colorCode && !quantityText && extraCells(row).length === 0) return;
    if (extraCells(row).length) {
      errors.push(`第 ${line} 行不能包含多余列`);
      return;
    }
    if (!colorCode || !quantityText) {
      errors.push(`第 ${line} 行需要色号和数量`);
      return;
    }
    if (!/^\d+$/.test(quantityText)) {
      errors.push(`第 ${line} 行数量必须是非负整数`);
      return;
    }
    const quantity = Number(quantityText);
    if (!Number.isSafeInteger(quantity) || quantity > 2_147_483_647) {
      errors.push(`第 ${line} 行数量超出范围`);
      return;
    }
    const swatch = paletteByCode.get(colorCode);
    if (!swatch) {
      errors.push(`第 ${line} 行色号 ${colorCode} 不在当前色卡`);
      return;
    }
    const previous = seen.get(colorCode);
    if (previous != null) {
      errors.push(`色号 ${colorCode} 重复（第 ${previous} 行与第 ${line} 行）`);
      return;
    }
    seen.set(colorCode, line);
    parsed.push({ colorCode: swatch.code, quantity, name: swatch.name });
  });

  if (!parsed.length && !errors.length) return { ok: false, errors: ["请粘贴或选择包含色号和数量的表格"] };
  if (parsed.length > INVENTORY_BATCH_CALIBRATE_LIMIT) {
    errors.push(`每批最多校准 ${INVENTORY_BATCH_CALIBRATE_LIMIT} 个色号`);
  }
  if (errors.length) return { ok: false, errors };
  return { ok: true, rows: parsed };
}

export function inventoryCalibrateFingerprint(
  accountId: string,
  paletteId: string,
  inventory: ReadonlyArray<InventoryCalibrateSnapshotItem>,
): string {
  const rows = inventory
    .filter((item) => item.paletteId === paletteId)
    .map((item) => `${item.colorCode}:${item.quantity}:${item.location ?? ""}:${item.revision}`)
    .sort();
  return `${accountId}|${paletteId}|${rows.join(",")}`;
}

export function buildInventoryCalibratePreview(
  rows: readonly InventoryCalibrateParsedRow[],
  paletteId: string,
  inventory: ReadonlyArray<InventoryCalibrateSnapshotItem>,
  fingerprint: string,
): InventoryCalibratePreview {
  return {
    paletteId,
    fingerprint,
    rows: rows.map((row) => {
      const current = inventory.find((item) => item.paletteId === paletteId && item.colorCode === row.colorCode);
      return {
        ...row,
        previousQuantity: current?.quantity ?? 0,
        location: current?.location ?? null,
        baseRevision: current?.revision ?? 0,
      };
    }),
  };
}

export function isInventoryCalibratePreviewCurrent(
  preview: InventoryCalibratePreview,
  fingerprint: string,
): boolean {
  return preview.fingerprint === fingerprint;
}

export function toInventoryCalibrateBatchItems(
  preview: InventoryCalibratePreview,
): Array<{ paletteId: string; colorCode: string; quantity: number; location: string | null; baseRevision: number }> {
  return preview.rows.map((row) => ({
    paletteId: preview.paletteId,
    colorCode: row.colorCode,
    quantity: row.quantity,
    location: row.location,
    baseRevision: row.baseRevision,
  }));
}
